/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20201013-4","meetingId":"r02-c-settlement","date":"2020年10月13日","dateIso":"2020-10-13","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を173件整理しています。","topics":[{"id":"topic-01","title":"令和元年度品川区一般会計歳入歳出決算","agenda":"令和元年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"芹澤委員","kind":"質問・要望","question":"その場合、またおっしゃっていただきたいと思うのですが、これまで宮古市と品川区の児童が交流を持つ２泊３日のツアーをやってきたと伺っています。児童・生徒大体１０組程度が２泊３日で伺って、防災、実際の災害の現場を訪れて様々な勉強をしていく。","respondent":"有馬庶務課長、工藤指導課長","answer":"この事業は、青少年育成活動、親子体験交流事業ということで実施していると捉えております。学校への広がりというところは、今後研究してまいりたいと思います。 現在は家庭での活用も含めて、持ち帰る中で家庭でどのように活用が図れるかというのを含めて、活用を検討しています。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"確認","question":"それで、タブレットはもう一度確認したいのですが、そうすると、持ち帰りが前提になるということでよろしいのでしょうか。それとも、まだ学校での判断もしくは保護者の判断で、それぞれ持ち帰っていただければというような方向性なのか尋ねました。","respondent":"工藤指導課長","answer":"タブレットにつきましては、持ち帰りが前提でということで検討を進めているところです。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"提案","question":"続けて８３運動についてお伺いいたします。８３運動については、予算特別委員会の中で何度か提案をさせていただきましたとの意見を述べました。","respondent":"有馬庶務課長","answer":"８３運動ですが、今後の取組みについてどういうふうに進めていこうかというような話し合いの場を持たせていただきました。８３運動が、８３運動推進委員会で作っているということですので、そういった意味で一歩前に進んでいるというような状況です。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"特にまたコロナの中で、不審者情報などが相次ぐ中で、８３運動の事業というのが、さらに大きな意義を持っていくと理解しています。これまでのＰＴＡに対しての周知とは、また、より１つギアを上げて周知されるというような理解でよろしいのか尋ねました。","respondent":"有馬庶務課長","answer":"それに対応して、本当の側面支援という形でしたけれども、いろいろな案が出ています。あるいは、「子どもたちにポスターを描いてもらうというのも１つの方法だね」など、何かできることを進めていきたいと考えているところです。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"意見","question":"例えば何か予算をつけて、例えば６年生の行事も含めて、積極的にストレスの解消というものに教育委員会で取り組んでほしいと求めました。何かあればご意見を説明を求めました。","respondent":"有馬庶務課長","answer":"コロナ禍でいろいろと行事ができなかったところもありますので、一応、心のケアではないですけれど、何か思い出づくりということに取り組んでいこうということで考えているところです。","id":"exchange-005"},{"speaker":"松澤委員","kind":"確認","question":"私からは、３６７ページ、学校ＩＣＴ活用経費、３６９ページ、学校システム運営費についてお伺いいたします。私自体、教育ＩＣＴが詳しく分からないので、確認しながらの質問になることをお許しください。","respondent":"篠田学務課長","answer":"各学校に４０台ずつのタブレットを配置しまして、それぞれ今、校内ＬＡＮを使った環境で学習をしていただけるという状況です。例えば壊れてしまったということでお預かりして、その間、代替機をお渡ししてお使いいただくというような形で対応しています。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"代替機を渡すことは、壊した家庭が負担するということはないということでよろしいか尋ねました。","respondent":"篠田学務課長","answer":"例えば故意で、明らかにいたずらをして壊してしまったなどということがなければ、そういった確認が取れなければ、基本的には公費で全て対応しています。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"そこでお聞きいたします。この２点をお願いします。","respondent":"篠田学務課長","answer":"現在配備してある無線ＬＡＮを活用した形で、Ｗｉ－Ｆｉでつなぐような形の、いわゆるハイブリッドの構成を考えているところです。","id":"exchange-008"},{"speaker":"松澤委員","kind":"意見","question":"こういった図書館でのＷｉ－Ｆｉの活用などを私は考えましたが、話し合いの場でどのような議論がされたのかというのが１点。そして、家庭でのインターネット環境についてのアンケートの結果が分かりましたらお願いいたしますとの意見を述べました。","respondent":"篠田学務課長","answer":"国がＧＩＧＡスクール構想ということでかなり強力に推し進めているというところがございまして、事業者の方に働きかけがあったと聞いております。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問・要望","question":"全国どこでも、どこの学校にいても、最新の質の高い学習環境を利用できる仕組みの整備が求められております。品川区でも、例えばＣｈｒｏｍｅｂｏｏｋとまなびポケットを組み合わせるなど、品川区での今後の予定などがありましたら説明を求めました。","respondent":"篠田学務課長","answer":"今回私どもがＧＩＧＡスクールで導入しようとしているのが、ｉＰａｄを入れようということで、今、取り組んでいるところです。何らか対応していくことが必要だろうということで、現在、どういった形のものを入れていくかというのは検討を進めているところです。","id":"exchange-010"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひ、子どもたちにとって何が一番いいのかを考えて活用していただきたいと要望いたします。これは家庭の問題だとは思うのですけれども、学校側から何かそういうものに向けて取り組む課題やお考えというのはありますか尋ねました。","respondent":"工藤指導課長","answer":"やはり今、中に入れる学習コンテンツの中では、現在品川区でも活用しているｅライブラリアドバンスというものの引き続きの活用を検討しています。そういったことで、家庭学習・自学自習を習慣化していくことにも取り組むというところで検討を進めているところです。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"最近では、情報化統括責任者であるＣＩＯというのですか、最高情報責任者を置く民間企業が増えていると聞いております。そこで、雇用や勤務形態は様々ですが、品川区におけるＩＣＴ支援員の現状と今後の取組みについて説明を求めました。","respondent":"篠田学務課長","answer":"その１０校以外の学校に関しましては、各学期に１回回りまして、それぞれの学校での対応を行っているです。できるだけ厚みを持った形での対応をしていきたいということと、また来年度においても、そのための対応は十分取っていきたいと考えているところです。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"電話で済む話なのですけれども、そういった部分で困っている、要はＳＮＳでやってほしいです。欠席届をオンラインでやり取りするとか、学校プリントのデジタル化を含めた現場の先生の負担軽減等の考え方も含めてご見解を説明を求めました。","respondent":"工藤指導課長","answer":"そういったことも含めて、研究も含めながら、今、検討を進めているところではあります。ですので、また学校の教員の働き方改革という観点からも、効率よく連絡がしっかりとできるようなところを検討してまいりたいと考えています。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問・要望","question":"結果的には８割以上の保護者がＬＩＮＥで出席・欠席・遅刻連絡を行っていまして、教員の業務改善にも役立つということが立証されておりました。ＩＣＴ教育に対する負担を軽減するためにも改善していただきたいと考えますが、先ほどとかぶってしまいますけれども、ご見解を説明を求めました。","respondent":"工藤指導課長","answer":"すぐ採点されて、自分が分かる・分からない、分からないところを確認できる。教員については、また授業改善に資することができるとも考えておりますので、そういった活用についても含めて様々検討していきたいと考えています。","id":"exchange-014"},{"speaker":"松澤委員","kind":"質問・要望","question":"特に先生たちが、コロナ禍というのもありまして、いろいろな負担を強いられていると思います。そういった方々をしっかりと把握してフォローする、そういった環境の整備を要望して質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"３６１ページ、マイスクール運営費、３６７ページ、学校ＩＣＴ活用経費から関連してお伺いいたします。１日の授業が、全てオンラインが活用されたのかということもお伺いいたします。","respondent":"篠田学務課長","answer":"１クラスで２名ずつぐらい、少しつながりの悪いところが、ご家庭で設定がうまくいっていなかったというようなことがあったと伺っています。本日からは本格的に授業で取り組むと聞いていますので、まだ詳細を聞き及んではいないのですけれども、今日から活用されているです。","id":"exchange-016"},{"speaker":"新妻委員","kind":"確認","question":"保護者を交えてオンラインでの安否確認をするということで、９月と、今回のオンライン授業に活かされてくるのかと考えています。今回この学校がオンライン授業を展開するにあたっては、これらの準備が活かされてきていると認識するのですが、区の見解を伺います。","respondent":"工藤指導課長","answer":"お話しいただいたところは、早くから計画的にＺｏｏｍを活用するというところを進めていたという事例であると私どもも認識しています。そういったことを学校間で共有しながら、Ｚｏｏｍの活用も含めて図っていきたいと考えています。","id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"マイスクールに通いたい人は、マイスクールに入室というのでしょうか、マイスクールに入っていくのかという流れをお知らせほしいと求めました。そして、この入室判断はどの段階で誰が行うのかということをお知らせください。","respondent":"矢部教育総合支援センター長","answer":"所管は教育総合支援センターですので、そちらのＨＥＡＲＴＳを中心とした指導主事にも相談して、これからの道筋について考えてまいります。本当に適応指導教室がよろしいのか、学校の中で対応できるのか、その辺の検討からまず始めます。","id":"exchange-018"},{"speaker":"新妻委員","kind":"確認","question":"前期の文教委員会の所管事務調査でひきこもりを取り上げた際に、教育委員会には、マイスクールの現状、人数等々も含めて確認させていただきました。空きがなかなか少ないというようなことも伺いましたけれども、この３つのマイスクールに、また待機者というのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"マイスクール八潮につきましては、３０名が定員ですが、もうほぼ定員に満ちている状況、さらに見学者も何人かいらっしゃると聞いております。昨年度末で、五反田のほうが２６名、浜川のほうが十数名という報告を受けてあります。","id":"exchange-019"},{"speaker":"新妻委員","kind":"質問","question":"だけれども、見学を申し込んではいるものの、空きがないということで、年度初めの来年４月まで待ってほしいと言われたと。今後のマイスクールの在り方やニーズ等を踏まえて、マイスクールの拡充等も必要かと思いますが、区の見解をお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"小学生につきましては、委員ご指摘のとおり、八潮で対応しています。今後ともこの３教室の在り方について前向きに検討してまいりたいと考えております。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"質疑後、中学生の保護者から、見直しを求める質問への共感、さらに、理不尽な校則の実態など、様々な声が届きました。校長会について、誰がいつどんなお話を何度もしているのか、伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"それを踏まえまして、見直しのことですが、昨年も含めてこれまでも、校長会で教育長より見直しの指導はございました。現在、生活指導主任会でも話題に挙げて、見直しの検討をしています。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"私が伺った中学１年生と中学３年生の生徒は、「ツーブロック禁止っておかしいよね」とか、生徒の中で様々話題になっていることが分かりました。先ほども伺いましたが、教員の中ではどんな議論が実際にされているのかも伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"地域や児童・生徒、今までの時代の流れといったものを背景にして、見直すことが必要だというお話でございました。小学校も含めてですけれど、何でここにこうあるのか、また共通理解をどのようにするべきかというような議論が交わされております。","id":"exchange-022"},{"speaker":"中塚委員","kind":"提案","question":"お伺いしますが、生徒の髪形禁止の不満の声は教育委員会にどのように届いているのか、どんな声があるのか伺いたいと思います。こうした姿勢が重要だと思いますけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"生徒自らが自分たちの校則を考えるというのは、とても大事なことだと考えております。どちらにしましても、そこはこれからも見直しのほうの働きかけを進めてまいりたいと考えております。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"見直しの働きかけは歓迎したいと思いますけれども、質問したのは、生徒の髪形についての不満の声は区教育委員会に届いているのか、どんな声があるのか、改めて伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"失礼いたしました。児童・生徒の髪形についての意見については、私どもには聞こえてきておりません。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"実際に、保護者からも、納得がいかなくて教育委員会に電話をするということもよく伺います。声をつかんでいないというのは、あまりにも、生徒の声、保護者の声を軽視していると思いますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"児童・生徒、保護者の声を軽く考えていることは全くございません。生活指導主任会を２か月に１度ほど行いますので、今回の校則の見直しの話題の際にも、その中では協議されていることと考えております。","id":"exchange-025"},{"speaker":"中塚委員","kind":"提案","question":"今の中学校がどうかまでは私は確認しておりませんけれども、ポニーテール禁止について教育委員会は知っているのか、なぜ禁止なのか。私はおかしいと思いますけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"各学校が吟味して作成していると考えておりますので、委員がおっしゃるとおり、見直しはまだこれからも続けるよう働きかけてまいります。ただ、今のお話の中で、成績に関わるような指摘については不適切だと考えますので… ただ、今申し上げましたように、様々な事例については指導の前後というのがあります。先ほど教育総合支援センター長からもありましたとおり、個々の事情につきましては前後関係があるということをご承知いただければと思います。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"ポニーテールというのがそもそもどういう髪形なのか聞いたところではあるのですけれども、結ぶ位置が上のほうにあるということでいいのですね。そんな理由で、主に女子生徒が自分の好きな髪形を禁止するというのは、理不尽だと思いますけれども、いかがか尋ねました。","respondent":"工藤指導課長","answer":"今後は検討していく、変わらずに進めていくところではありますが、ご理解いただければと思います。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"そして、大人が決めた校則ですから、自ら、やはりこれは時代に合わないと思うものは、正していくことも必要だと思います。主体性にこそ向き合う、そういう指導をしてほしいと求めましたが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"どれも重要なことだと考えております。そこの場面で十分活躍させて褒めていきたいと考えております。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"お互いの個性を認め合い、磨き合い、だからこそ集団生活が成り立つのだと思います。今後とも、生徒や保護者、また現場の教員の声に耳を傾けていただいて、学校教育を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"筒井委員","kind":"確認","question":"私からは、３４８ページ、教育費全般から、コロナウイルスによる影響と少人数教育について、３６４ページ、図書館費についてお伺いいたします。行っていたとすれば、それはいつから始められたのか尋ねました。","respondent":"篠田学務課長","answer":"そのままの形で間を取りながら、前を向いて、言葉をなるべくしゃべらないようにして静かに食べるという形です。これを始めたのは、学校が再開されました６月から分散登校を始め、そのときからそういった形で始めて、現在も継続しています。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"こうした、コロナウイルスによって子どもが受けたストレス、心のダメージがあるという実感や事例というのはあるのでしょうか。コロナ感染防止対策に気を遣うのと相まって、ストレスや心のダメージが相当あるかと思いますけれども、そうした実感や事例はありますか尋ねました。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"６月に一斉登校が始まりまして、その後、我々もお子さんの様子が大変気になりましたので、アンケートを取りました。その中では、やはり学習に対する不安と、もう一つ、クラスが変わったところがありますので… 他方で、教育活動を進める中では、教員も知らず知らずのうちにストレスをため込んでいるということが懸念されるところではあります。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"子どもも当然そうですけれども、学習面や友達との関係で悩みがあるということですが、そうした子どもたちと教員の心のケアはどうされていくのか。生徒たちに対しては思い出づくりをやっていくというようなことをおっしゃられましたけれども、具体的にそれはどのような形でやっていくのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"思い出づくりにつきましては、繰り返しの答弁になりますけれども、各学校で既にいろいろな工夫をして考えてあります。それぞれ自分たちが考えた活動をやろうということで、７月に学校の中で楽しいレクリエーションをやったということも聞いてあります。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"思い出づくりをさせるといったこと以外で、子どもたちに対してもう少し丁寧に聞き取るとか寄り添うとか、そういった活動というのはないのか尋ねました。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"当然、相談があれば教育総合支援センターも、ＨＥＡＲＴＳの派遣や相談窓口を紹介したりしております。先般、文部科学大臣、また区教育委員会からも、お子さんに宛てての直接の手紙の形で、いじめや差別の防止について周知したところで… 教員の心のケアにつきましては、先ほど申し上げましたが、不調が見られたりした場合には、もちろん必要に応じて産業医面談につなぐなど、やはり教職員のケアについても引き続き注意深く見ながら進めていきたいと考えています。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"続けて少人数学級のほうをお伺いいたしますけれども、文部科学省が、３０人学級に１０年をかけて段階的に移行するというような方向性を発表しました。物理的・場所的制約といった地域事情も加味されるべきかと思うのですけれども、本区としては、どう対応されていくのか尋ねました。","respondent":"篠田学務課長","answer":"先般、文部科学省からもそういった形で考え方が示されているのは、私どもも承知しています。今、まだ考え方が示されているだけですので、それに沿った対応を考えていく必要があるだろうとは受け止めているところです。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問","question":"これは注意深く見ていただいて、それに対しての準備はしていくべきかと思いますので、しっかりと対応のほどよろしくお願いします。今、書籍消毒器というのが区内の図書館に幾つかあると思いますけれども、各図書館の設置台数とメーカーと１台当たりの値段を説明を求めました。","respondent":"横山品川図書館長","answer":"品川図書館をはじめ図書館６館に１台ずつ、また大崎駅西口図書取次施設に１台、計７台を設置しています。２、３冊に対応するＣＯＣＯＣＨＩという機種が、５０万円から７０万円台で入ってあります。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問","question":"ぜひそうした書籍消毒器の対応というのもお願いしたいと思いますが、どうしても今後もウィズコロナということ、もうどうしても足りなくなる。例えば統括館の品川図書館から、電子図書館の実証実験というのを始めてはいかがかと思うのですけれども、区のご見解をお願いします。","respondent":"横山品川図書館長","answer":"そういう形で、今、品川区では、検討にあたって研究を進めてはいるものの、導入にまでは至らない状態ではあります。品川区にしかない資料については、これからデジタル化を進めていこうという形で、状況を見ながら対応していこうと思っているところです。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"理由として大きいかと思いますけれども、デジタル化の流れで、図書館も変革を迫られるのではないかと考えております。そして、図書館を電子化しますと国から急に言われたときに、いつでもすぐに対応できるような準備をぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"３４８ページ以降、３７３ページ、学校給食放射性物質検査について伺います。給食の安全を確認するためにも継続して検査すること、単品検査への切替えを再度求めますが、見解を伺います。","respondent":"篠田学務課長","answer":"実施にあたっては考えていくということでお話を申し上げまして、全部の学校で進めるのではなくて、実施するかしないかというのは。今の形になっている、全ての食材を検査するという形になってきてありますので、基本的にこのやり方を今変更する考えはございません。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"デートＤＶ、性教育について伺います。保健体育の教科書を確認したところ、デートＤＶについてほんの１文触れていましたが、改めて伺います。","respondent":"矢部教育総合支援センター長","answer":"デートＤＶに限らず、子どもたちの人権を守るという点で、市民科をはじめ各社会科でも、教科を中心に指導してきたところです。各学校におきましては、セーフティ教室などで、子どもたちの、自分で身を守る被害防止に努めているところです。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"ホルモンの働きを学ぶことも確認していますが、人によっては月経の約２週間前から直前までの期間、言及はないと聞きます。その結果、不妊をはじめとした気づきにくい様々な病気の早期発見にもつながると考えますが、区教育委員会の見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"学習指導要領の中には、今、委員がおっしゃったような、月経に関わる詳細な指導については示されてございませんので、現状は個別対応になります。もしも必要であれば学校医とも相談して、丁寧に、プライバシーを守って対応してまいりたいと考えております。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"養護教諭やＰＴＡ、保健センターなどと協力して、子どもが体について学ぶ機会の確保を求めたいと要望しますが、見解を伺います。都の改善を待たずに、区としての調査を早急に行うことを求めますが、見解を伺います。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"初めに、月経に関わる対応のお話ですが、私たちとしましては、子どもたちは様々な悩みを抱えてありますので、担任を中心に子どもたちに丁寧に向き合って対応してまいりたいと考えております。東京都教育委員会が行っています調査につきましては、実施時期が１２月ということで、生徒向けには１２月という案内をしています。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"中・高生の体罰の質問用紙についての期間については、小学生の質問用紙を確認すると、期間というのは書かれていないのです。区教育委員会としての趣旨説明が必要だと考えますが、見解を伺います。","respondent":"工藤指導課長","answer":"体罰あるいは不適切な指導をなくすということが非常に重要なことであると認識していますし、不適切な指導の根絶に向けて取り組みたいと考えています。期間を外すことにつきましては、都が定めた様式ですので、そこは都と意見交換などを行うことを進めていければと考えています。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"そして次に、新型コロナウイルス感染症関係について伺います。民生費でも伺いましたが、例年とは違い、準備が間に合わないまま進学します。","respondent":"矢部教育総合支援センター長","answer":"新１年生・新７年生の進学につきましては、配慮していくことが重要だと感じております。既に６年生は今、また中学校のほうも対応して、そのような状況を踏まえて丁寧に対応してまいりたいと考えております。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"小学生になった子どもたちは、例年に比べてできることが少ないかもしれませんが、それを受け止めてほしいと要望します。区教育委員会と学校だけでなく、幼稚園や保育園などの先生たちと情報共有を行い、子どもたちを迎える体制を整えてほしいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"松本委員","kind":"質問・要望","question":"本日は、３６７ページ、学校ＩＣＴ活用経費、３５４ページ、区教員経費、あるいは３５５ページ、教職員人材育成経費について伺います。タブレットとペーパーレスの関係の中でも、学校現場でも必要ではないかと思いますが、ご見解を伺います。","respondent":"工藤指導課長","answer":"一部、職員会議などで部分的に取り組んでいるといった事例はありますけれども、なかなか課題もあるために進んでいない現状もあります。今後のタブレット配備も併せながら、大事な視点であると認識していますので、そういった意味では検討してまいりたいと考えています。","id":"exchange-045"},{"speaker":"松本委員","kind":"質問","question":"教職員のところはまた後ほどお伺いできればと思うのですけれども、タブレットに通知表を配信するというふうな考え方もあり得るのではないかと思いますが、こういった可能性についても伺えればと思います。","respondent":"工藤指導課長","answer":"今ご質問いただきました点につきましては、例えば通知表というものには、もちろん成績、あるいは学習の記録と文章も記録されるものです。検討課題であるという認識ではありますので、現行の様式と併せながら、何が一番有効であるのかというのは検討してまいりたいと考えています。","id":"exchange-046"},{"speaker":"松本委員","kind":"質問・要望","question":"要望です。少しお伺いしたいのですけれども、全員ではなくて希望者には配付するべきだという話が出てきた場合、お伺いできればと思います。","respondent":"工藤指導課長","answer":"ワークシートに関して、またドリル学習についても、個別に採点して教えるべきものがいいということもあります。何が有効かというのは検討する必要があるとも思いますし、取組みの趣旨というのをご理解いただくということも踏まえながら進めたいと考えています。","id":"exchange-047"},{"speaker":"松本委員","kind":"質問・要望","question":"タブレットが配付されて、正当な理由があれば別ですけれども、そういうことがない限り毅然とした対応をしてほしいと求めました。これはぜひ進めてほしいと求めましたが、ほかの学校での取組みや、推進していく流れというところもお願いできればと思います。","respondent":"工藤指導課長","answer":"それを、例えば現在の機能で言えば（イントラネットの）回覧機能を使って、既に送っておくということで取り組んでいる学校もあると存じています。","id":"exchange-048"},{"speaker":"松本委員","kind":"質問","question":"その中でまたお伺いしたいのですけれども、一部の教員が、自分が雇用されたときにはタブレットなどなかった。あるいは職員会議も、希望者には資料を学校側できちんと印刷して紙で配るべきだと主張した場合に、学校側としてはどのように対応するか尋ねました。","respondent":"工藤指導課長","answer":"私ども、例えば現状も、ＧＩＧＡスクール構想の中で、１人１台タブレットを実現していくというところで、今、推進しています。教員に課されている使命であるというところは、教員に対しては指導してまいりたいと思いますし、そのように取り組んでいきたいと考えています。","id":"exchange-049"},{"speaker":"松本委員","kind":"質問","question":"希望者には資料を紙で配付するべきだと、資料を作成する側もそういったことがあると、教員にも負担となると考えています。停滞させている人たちに対しては強く怒りを持っているということを改めて申し上げまして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"西村委員","kind":"質問","question":"３５９ページ、学校と家庭の連携推進事業と、３６１ページ、マイスクール運営費、関連しまして、不登校、ひきこもりについて伺ってまいります。中学生は１クラスに１名、小学生は７０人に１名程度かと思いますが、区内の現状はいかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"平成３０年の不登校の出現率につきましては０.５５％、中学校につきましては３.７１％と、例年、徐々に増加傾向にあります。","id":"exchange-051"},{"speaker":"西村委員","kind":"質問・要望","question":"不登校児童・生徒への支援の在り方について伺ってまいりたいと思います。把握が難しいとは理解していますが、マイスクールやフリースクールに行かない、行けない児童・生徒の推計値はどのようになっているか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"実際には個別対応になりまして、体制をつくりながら、家庭と連携を取って連絡しています。学習については各ご家庭のご判断もありますので、自学する、またはインターネット環境が整っていれば、ｅライブラリ等の紹介もできるです。","id":"exchange-052"},{"speaker":"西村委員","kind":"質問・要望","question":"児童センターに行くお子さんもいると伺っています。文部科学省による「魅力ある学校づくり検討チーム」の設置もあり、多様な状況に対応した支援・指導体制の確立がますます求められています。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"今後、１人１台タブレットが配付されますので、学習面・生活面でも検討を進めていきたいと考えています。今後、校長判断で教育課程を履修したということを認めるような通知も出てありますので… 区内においても、マイスクール五反田等で通い始めて、自分で学びたいという意欲が上がってきて、進学につながっているという実績もあります。そういったところが相まって進学率が上がってきていると認識しています。","id":"exchange-053"},{"speaker":"西村委員","kind":"質問","question":"公的な支援がありませんので、親が学費を負担しなければならず、金銭面で苦しむ家庭も少なくないと伺っています。こういった、学校に行けない児童・生徒のこれからの公教育はどうあるべきか、区のお考えを説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"例えば１日のスケジュールの内容が適切であること、今、そのような条件が満たされれば出席と認めていいことになってあります。不登校が長期化することを助長してしまうということは文部科学省の通知にもありますので、その辺りを慎重に進めてまいりたいと考えております。","id":"exchange-054"},{"speaker":"西村委員","kind":"質問","question":"ひきこもり支援について伺いますが、経済産業省の委託事業で、「ｅスポーツを活性化させるための方策に関する検討会」という報告書を読みました。都市部は特に、ゲーム、オンライン、ｅスポーツなどの取組みが注目されていますが、この辺りはどのようにお考えか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"ｅスポーツにつきましては、世界でも認知されているということは承知しています。新しく学習指導要領が改訂されましたが、そちらには示しがございませんので、国または東京都の示しを踏まえて対応していきたいと考えております。","id":"exchange-055"},{"speaker":"西村委員","kind":"質問・要望","question":"対話が中心の哲学カフェのような、非認知能力を養う講座を出席扱いとしたり、スタディーサプリを無料で受講できるといった事例も伺いました。学校と家庭の連携推進事業につきまして、改めて簡単に説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"それ以外に専門家、特に不登校への対応についての専門家をお呼びして、校内で研修を行っていただく。そのような事業です。","id":"exchange-056"},{"speaker":"西村委員","kind":"意見","question":"１学期・２学期は外部の講師を呼ぶことが中止になりまして、コロナ対策をした上で、コミュニティ・スクールをぜひ継続してほしいと考えています。その辺り、ご意見を説明を求めました。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"各学校の行事につきましては、委員がおっしゃったとおり、１学期はコロナ禍でございましたので大分控えてございましたが、新たな形で、日にちを分けたり、時間を分けたり、来ていただく方を制限したりということで進めてあります。 やはり地域の関わりのところは、学校支援地域本部も含めまして、コミュニティ・スクール全体として進めたいと考えています。","id":"exchange-057"},{"speaker":"西村委員","kind":"質問・要望","question":"最後に、まもるっちについて伺いたいのですが、項目が特別になく、見つけられず、すみません。説明会が難しい場合は、何かＹｏｕＴｕｂｅで動画で作っていただくなど工夫していただきたいと思うのですが、可能か尋ねました。","respondent":"有馬庶務課長","answer":"ところが、今年度につきましては、保護者の方に十分な説明が学校からできなかったのかと拝察いたします。時を見てもう一度周知できる部分があれば、まもるっち通信なども出しておりますので、そのようなところで周知を図っていきたいと考えております。","id":"exchange-058"},{"speaker":"西村委員","kind":"質問","question":"私の子どもが１年生で、なかなか、まもるっちを理解できていなくて、コロナ禍ということがあったのだと改めて理解いたしました。はこれは２４時間対応できているのかなどのご質問も保護者の方たちからありまして、ぜひとも取組みをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"つる委員","kind":"提案","question":"３６９ページ、それから３５２ページ、教育指導費について伺っていきたいと思います。中学校については、今年度についてはモデル校として、冨士見台中学校では市民科の授業で取り組まれていると伺いましたとの意見を述べました。","respondent":"横山品川図書館長","answer":"６歳から１２歳が学び、目標の１から１７まで順番に取り上げて、１か月ずつブックリストを発表していくという方針が出されております。学校図書館につきましても、選書の際に、ＳＤＧｓは市民科でも取り上げる項目ですので、そちらに留意しながら選書しています。","id":"exchange-060"},{"speaker":"つる委員","kind":"質問・要望","question":"これは２０１９年ですか、２０１８年だったでしょうか、朝の登校時間の課題のご相談を頂きました。そういう学校も伺っているところであります。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"それに対応しまして、管理職を中心に、早めにお子さんを一部お預かりしている事例はあります。そのような地域の方にもご協力をいただきながら、また安全という面では… これは学習面の支援ということではございませんが、通学安全業務につきましては７時半から配置できるようにということで対応しています。","id":"exchange-061"},{"speaker":"つる委員","kind":"質問・要望","question":"オンラインの活用なども含めて個別具体のことは伺いましたし、また文教委員会でも一定程度質疑がされているのも確認させていただきました。それから小学校６年生も受験の方もいらっしゃるでしょうし、９年生ないし中学校３年生、児童・生徒に対する様々なお考えを説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"市民科で取り上げられた授業も聞いておりますので、こういった新たなコロナ禍の体制でも授業が充実したということは１つあるかと思います。これから、学校独自の工夫した、子どもたちの創意を活かしたような行事も組み立てていきたいと考えています。","id":"exchange-062"},{"speaker":"つる委員","kind":"質問・要望","question":"生きる力というか勉強を頑張るという気持ちになっていて、やはりこんな、子どもの心に響くような教師が１人でも増えていただきたいと考えています。ちなみに、これを書いてくれたのは、教育総合支援センター長です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"くにば委員","kind":"質問","question":"私は、３５７ページ、一貫教育推進経費、３６７ページ、学校ＩＣＴ活用経費から、オンライン学習について伺います。それらを踏まえて総合的に、どちらに優位性があるかなど、特に相違が見られる点を中心に説明を求めました。","respondent":"工藤指導課長","answer":"小学校、３校種の体制を取りながら、また学校を選んでいただける選択制も相まってということで成果を上げているものと認識をしています。特に５・６・７年生、そういった面で９年間の教育を進めやすいというメリットのところでは成果が上げられていると認識しています。","id":"exchange-064"},{"speaker":"くにば委員","kind":"質問","question":"今、品川区には義務教育学校が６校ありますけれども、今後さらにこの取組みを強化して、義務教育学校を増やしていく方針はありますでしょうか。ご答弁をお願いします。","respondent":"工藤指導課長、篠田学務課長","answer":"例えば３校種ある中で、１点、義務教育学校で取組みを始めた勉強合宿ということがあります。取り組み方を変更しながら中学校にも広がりを見せているところがありますので… 義務教育学校の今後の展開についてのお尋ねです。地域バランス等を考えて設置してまいりましたけれども、３校種の体制、現時点では義務教育学校をこれ以上増やす予定はございません。","id":"exchange-065"},{"speaker":"くにば委員","kind":"質問","question":"義務教育学校出身者について、その後の職業分布等の違いなど、客観的な統計データを取る調査やアンケート等はなさっていますでしょうか。こちらについては、全国の自治体や文部科学省で、同様に、この点の中長期的な統計調査は取っているのか尋ねました。","respondent":"工藤指導課長","answer":"高等学校等への進学につきましては把握していますが、その先の進路につきましては、私どもが把握するところではございません。国のほうのそういった統計的な調査があるかということにも、現状、私どもも、そういったものがあるという把握もしてございません。","id":"exchange-066"},{"speaker":"くにば委員","kind":"質問・要望","question":"そういった保護者の声について、区はどのように捉え、受け止めていますでしょうか。生徒へのケアだけではなく保護者の負担軽減、メンタル面への配慮やケアが必要だと考えますけれども、この点のお考えを説明を求めました。","respondent":"工藤指導課長","answer":"まずオンライン教育の非常に大事な視点というのは、児童・生徒、子どもたちの学びを止めないというところであると認識しています。例えば保護者の方に採点をお願いするなどという事例も幾つかあったと認識していますけれども、いわゆるリモート学習というものも進めておりました。","id":"exchange-067"},{"speaker":"くにば委員","kind":"質問","question":"今、それぞれの生徒が考えるということが重要になるとおっしゃっていましたけれども、最後に、オンライン学習のデメリットについて伺います。これらのデメリットに対する具体的な改善策の取組み、例えば集中力持続のための具体的な方策のアドバイスなど、どのようになさっていますか尋ねました。","respondent":"工藤指導課長","answer":"それで、その家庭学習に取り組む時間であるとか、様々タブレットを運用する時間なども含めて、どんなふうな扱いをするのかも併せて検討しています。","id":"exchange-068"},{"speaker":"くにば委員","kind":"質問・要望","question":"オンライン学習については非常に有用で、今後必ず進めていかなければいけない分野だと思います。オンライン学習が、より生徒が今までの学習よりもプラスになるような研究を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"インクルーシブ教育の充実を求めて、学習支援員・介助員の拡充、それから特別支援教育推進計画の策定を求めて質問したいと思います。そのことで現場がどう変わったのか、また現場の状況から、今後さらに大幅に増やすことが必要ではないかと考えますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"品川区の人口が増えておりますので、今後も、広げてまいりたいと考えております。介助員・学習支援員の数については、手元にすぐ出てきませんので、今はお答えできません。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"増えた人数に合わせて５倍にした場合どうなるのかと計算しましたら、８億８,０００万円ぐらいになるのですけれども、いかがでしょうか。そういうことからすれば、ここのところの大幅増をすべきではないかと思いますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"ただし、担任も十分理解しなくてはいけないことで、１日そのお子さんの横に介助員がずっといなければいけないことばかりではないと考えております。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"時間数の増、１人についての時間数の増も含めて、大幅増員をしていただきたいと強く要望しておきます。インクルーシブ教育を充実させるというところからすると、ぜひ特別支援教育推進計画を策定してほしいと求めましたが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"来年度におきましても、荏原平塚学園と日野学園において、特別支援学級の前期課程のほうの対応をするところです。これからも様々な状況を鑑みながら計画的に進めてまいりたいと考えています。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"隣の目黒区、そのほかの幾つもの区がつくっているのですけれども、隣の目黒区では、平成１９年に第一次をつくり、今年３月に第四次をつくりました。区としてもぜひ推進計画をつくって、この取組みを拡充させていただきたいと思うのですが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"ご意見のとおり、これまでも計画的に進めてきたところです。まだまだ課題もあると思いますので、これからの成果とともに十分検討してまいりたいと考えております。","id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして課題を明らかにして、そして何が今大事なのかというところを精査して、具体的な対策というところにつなげていくことができると思うのです。ぜひとも推進計画をつくっていただくように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"せお委員","kind":"質問","question":"３６３ページ、主要施策の成果報告書の４８ページ、特別支援学級等運営費についてお聞きします。お聞きしたいのが、名前をつけて品川区独自に活用方法を検討するのか、この活用方法について見解を説明を求めました。","respondent":"工藤指導課長","answer":"区独自で授業活用の教員向けのガイドブックといいますか、そういったものを今、作成しておるところです。やはり区としても、品川区の一貫教育に合った活用を図るという観点で、学校、また教員の意見も反映させながら作成しておるところです。","id":"exchange-075"},{"speaker":"せお委員","kind":"質問","question":"今おっしゃられた、本当に品川区の特性に合わせた部分というのを取り入れていただけると効果が上がると思いますので、ぜひお願いいたします。言いますと、このトータル学習システムは今後どのような取扱いになりますか尋ねました。","respondent":"篠田学務課長","answer":"こちらは、それぞれ子どもたちが持っているタブレットの中にインストールして使うという形のものになってあります。今回、トータル学習システムはここまでという形で、ほかのコンテンツに置き換えるということを考えているところです。","id":"exchange-076"},{"speaker":"せお委員","kind":"質問","question":"全く新しいものに変わるということで、教師の方も子どもたちも混乱しないようなＩＣＴの活用をお願いしたいと思っています。先ほどは教科の面でしたが、今度は特別支援教育におけるＩＣＴの活用について、品川区での具体的な方法を伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"既に特別支援学級におきましてはタブレットが渡っておりまして、１人１台とは申し上げられませんけれども活用しております。大きな画面に写したり、そこで学習を進めたりという展開は、既にもう学級で行われてあります。","id":"exchange-077"},{"speaker":"せお委員","kind":"質問・要望","question":"お聞きしたいのですが、現在、個別最適化した学びのための支援というのはどのように行っているのか。以上、２点、説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"そこで個別に教員も回りまして、子どもたちの考えを活かして、その後、追究、検討となるわけです。そのようなことで、個々の時間において個別に対応していると考えています。","id":"exchange-078"},{"speaker":"せお委員","kind":"提案","question":"一般質問でもご提案しました、望んでいた未来に近づきそうで、とても期待が持てます。そこのところを東京都と連携して積極的に進めていっていただきたいのですが、見解を説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"委員にご紹介いただきましたＩＣＴ活用も含めまして、これまでの特別支援学級等のＩＣＴ活用を、有効なものを取り入れて、今後もほかの、１人１台タブレットに向けて、有効な活用を考えてまいりたいと思います。","id":"exchange-079"},{"speaker":"せお委員","kind":"質問・要望","question":"あるいは感染拡大を防ぐためにおしゃべり禁止などの指導を行うケースもあると伺っており、児童・生徒のメンタルヘルスを保つことは難しくなります。７年生、全員と行うよう求めていて、どのようにフォローしているのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"５年生・７年生以外の面談またはスクールカウンセラーの対応ですが、また保護者と随時連携して、丁寧に対応していきたいと考えています。全学校において全ての教職員が情報共有をして、子どもたちの心のケアにあたってまいりたいと考えております。","id":"exchange-080"},{"speaker":"せお委員","kind":"質問・要望","question":"それで、児童・生徒に負担がかかり過ぎるような感染対策というのは、いま一度検討していただきたいと要望いたします。さらに、現在の就学相談はどのような流れで実施していますか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"さらに校長、また特別支援学級のあった学校の元校長、特別支援学校や特別支援学級の教員が集まって協議を致します。先ほど申し上げました委員で協議いたしまして、後日、保護者にご連絡をする形となっています。","id":"exchange-081"},{"speaker":"せお委員","kind":"質問","question":"今の就学相談の流れなのですが、お子さんの様子を見て面談をして、その後、どこがいいかとお伝えする。就学相談の中身はそれだけなのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"保護者と医師と校長とが面談しまして意向も伺います。いかがですかということで、そこからさらに次の枝葉に分かれる選択肢、または相談に乗るというような手順です。","id":"exchange-082"},{"speaker":"せお委員","kind":"質問・要望","question":"主要施策の成果報告書の４８ページから、こちらも確認なのですが、「特別支援学級の新設を継続して行う」とあります。「特別支援学級の新設を継続して行う」なのですが、これは今後も継続していくという方向性という認識でよろしいのか、説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"増設ということは考えておりませんが、お子さんたちの数が大変増えてありますので、そのニーズには応えていかなければいけないと考えております。","id":"exchange-083"},{"speaker":"せお委員","kind":"質問","question":"最後に１点だけ。特別支援学級を増設してほしいというか、多分、そういうニーズがあるということへの理由というのは何だとお感じか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"例えば、ここ１０年間、私が教育委員会にいた間でも、特別支援教育に対する理解はとても深まっていると思います。要因の一点と考えています。","id":"exchange-084"},{"speaker":"せお委員","kind":"質問・要望","question":"そういったところが本来のインクルーシブ教育ではないかと私は思っています。ぜひともそこを念頭に、これからの教育のビジョンを考えていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"横山委員","kind":"質問・要望","question":"学校における健診と保健衛生部門との連携をお願いしたいと思いますが、現在の状況についてお伺いいたします。３点目の、美術工芸品・芸術文化資料類についてもお伺いいたします。","respondent":"工藤指導課長、矢部教育総合支援センター長、有馬庶務課長、篠田学務課長","answer":"９年間の一貫教育の中で、学校の教育活動全体を通じて確実に行えるよう、各学校で取り組んでいるところです。私どもが１番目に掲げているもので言え… どうやって勉強していったらいいだろう、どうやって調べていったらいいだろうということを、教材も含めて方法を検討します。５・６年生以上は… 美術工芸品関係ですが、ここに書いてある５７点のうち、学校の絵画という点では１校で８点あります。","id":"exchange-086"},{"speaker":"横山委員","kind":"意見","question":"みんな違っていい、みんなオーケーを両立するということをお願いしたいと思います。美術品についてなのですけれども、低稼働率のものなどがありましたら、なるべく区内全域の多くの子どもたちに鑑賞してもらえるようお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"小芝委員","kind":"質問","question":"３６３ページ、３６９ページ、学校図書館経費に関連して電子書籍の促進についてお伺いいたします。今年の３月から学校が休校となりましたが、学校の再開後、給食も再開されたと思いますけれども、いつ頃から具体的に再開されたのかを説明を求めました。","respondent":"篠田学務課長","answer":"今年度の学校給食の再開ですけれども、学校が６月から分散登校ということで再開されましたので、それに合わせて給食も提供させていただいたところです。","id":"exchange-088"},{"speaker":"小芝委員","kind":"意見","question":"コロナ禍で被害を受けた日本の食を守ることを、大人も子どもも一緒に考えていく１つの試みでもあると考えています。子どもたちの思い出づくりをサポートすることになると思いますし、食育の機会にもなると思いますが、お考えをお聞かせほしいと求めました。","respondent":"篠田学務課長","answer":"なかなかそちらでもコロナ対応等、かなり忙しかったということがあるのでしょうか、あまり積極的ではなかったと伺っております。そういった面で制度面が整ってくれば、一定程度、私どもも対応の仕方はあるのかとは考えているところです。","id":"exchange-089"},{"speaker":"小芝委員","kind":"質問・要望","question":"続きまして、３６３ページ、教科書採択事務についてお伺いいたします。教育委員会で教科書が採択されるまでの、ざっくりとした流れというものを教えてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"初めに、教科用図書調査検討委員会を立ち上げます。その結果を、次にもう一度、教科用図書調査検討委員会に上げまして、その報告を教育委員会でしていただく。","id":"exchange-090"},{"speaker":"小芝委員","kind":"質問・要望","question":"教科書採択には、文部科学省のホームページにもあるとおり、公正性と透明性が求められています。その後、教科書採択の公正性を担保するために品川区が取り組んできたことがあれば、教えてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"２か所、品川区役所と教育総合支援センターにおきまして、教科書展示会を１か月間ほど行いました。特に委員がご心配されるような内容はございませんでした。","id":"exchange-091"},{"speaker":"小芝委員","kind":"質問","question":"そこでお聞きします。これまでの教科書採択の歴史の中で、これまで教育委員会、また採択に関わる人々に対してされた事実はありましたか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"当然、意見を書きますので、このたびＡ社、Ｂ社についてご意見はありました。ただ、そこは、受ける意見の一つだと考えていますので、そのように認識しています。","id":"exchange-092"},{"speaker":"小芝委員","kind":"提案","question":"３６９ページの学校図書館経費に関連して、電子書籍の促進についてお伺いいたします。今年の第１回定例会で、我が会派の芹澤委員からも導入の提案がありました電子書籍について、コロナ禍を生きる子どもたちの未来に向けた質問をしますとの意見を述べました。","respondent":"横山品川図書館長","answer":"区立図書館から学校図書館へ、学校支援スタッフを派遣している状況ですが、休校が明けましてからは、スタッフも学校図書館で生徒を待って対応しているような状況が続いて、通常どおり開館しています。","id":"exchange-093"},{"speaker":"小芝委員","kind":"意見","question":"大人も子どもも読書の習慣がつけば、教養だけでなく新しい活路を見いだすことにもなるかもしれません。その環境を整えていくことも、学校図書館への電子書籍の導入を視野に入れた前向きなお考えを頂ければと思いますが、との意見を述べました。","respondent":"横山品川図書館長","answer":"民間の団体ではありますが、青空文庫といいまして、著作権がフリーになっている書籍を集めたサイトがあります。先ほどご案内しましたように、電子図書館の導入そのものについても、今後の状況を見ながら検討していきたいと思ってあります。","id":"exchange-094"},{"speaker":"小芝委員","kind":"質問","question":"今、こういうコロナ禍の状況ですけれど、感染拡大防止につながる点で、私も電子書籍の導入に向けて質問させていただきました。品川区に限らず東京都、そして全国に至って、読書のパーセンテージを上げていただきますことを期待しまして質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまで、学校司書が毎日いるように配置を求めてきました。学校司書の全日配置に向けて、予算化などを含めて、今、どんな取組みをしているのか、伺います。","respondent":"横山品川図書館長","answer":"現在配置されているスタッフのご意見や、事業者の配置状況を変えることによる影響についてアンケートや話し合いをして、状況の把握に努めてあります。今後の動きについて検討する形とともに、週１５時間の配置の中で、学校ごとに状況を把握した中で進めていく考えです。","id":"exchange-096"},{"speaker":"のだて委員","kind":"意見","question":"今、いろいろなスタッフの方など、アンケートをしたり話し合いをしているということでしたけれども、現段階でどういった形というか、どういう意見が出されているのか、できる範囲でご説明いただけたらと思いますとの意見を述べました。","respondent":"横山品川図書館長","answer":"今、週１５時間という配置ですので、家庭や家族の方のケアをする時間とのバランスを取って勤めていらっしゃる方がかなり多い状況です。増えてしまうのが急であると対応しづらいというのが、スタッフ、また事業者の意見でもあります。","id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"区内の学校でもいろいろな状況があるということですので、できる学校から始めてほしいと求めましたが、いかがでしょうか。司書のいる学校図書館が求められているということですので、教育委員会が責任を持って学校司書の全日配置を行うことを求めますが、いかがか尋ねました。","respondent":"横山品川図書館長、工藤指導課長","answer":"学校ごとに導入というお話を頂きました。全校一斉でなくても、どれぐらいの規模でできるかどうかというのは、時間をかけてじっくりと検討するような形を取っていきたいと思ってあります。学校図書館を教育活動の中で有効に活用して成果を上げていくというのは、教育要領でも定めているとおりで、ご指摘いただいているとおりです。","id":"exchange-098"},{"speaker":"のだて委員","kind":"質問・要望","question":"しかし、そもそも学校司書が行うべき仕事ができているのでしょうか。現在の学校司書配置時間で、ボランティアなどができない部分について、十分だと考えているのか、伺います。","respondent":"横山品川図書館長","answer":"まず運営にあたって毎月１回、また学校ボランティアの方も時には参加して、次の月の運営について打合せを持つような形が義務づけられてあります。","id":"exchange-099"},{"speaker":"のだて委員","kind":"質問","question":"ボランティア等学校全体でということですが、そういう方ができない、司書としての専門性が活かされる部分というのがあると思うのです。そういったところで、しっかりとした十分な時間が取れているのかということを改めて伺いたいと思います。","respondent":"横山品川図書館長","answer":"スタッフのほうが司書の資格を持っている場合もかなり多いですが、各学校に司書教諭の先生が配置されております。学校の責任としては校長先生が学校図書館長ですので、その指揮の下、司書教諭の先生が取りまとめをする形で運営している状況です。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問・要望","question":"運営スタッフや先生からも時間増の要望が上がっています。１２学級以上ある学校では、学校司書の配置時間を増やしてほしいと求めましたが、いかがでしょう。","respondent":"横山品川図書館長","answer":"以前にも申し上げましたとおり、将来的には調整の上で時間を増やすことを検討していきたいと思ってありますので、先ほどのアンケートや打合せの結果も踏まえて、丁寧に対応について検討し、計画を進めていきたいと思ってあります。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"１２学級以上ある学校の大変さというのは今起きていることですので、ぜひ早めに配置していくようにということで求めておきたいと思います。司書教諭のスキルアップも必要だと思いますけれども、区の司書教諭の研修はどのように行われているのか、伺います。","respondent":"工藤指導課長","answer":"こちらにつきましては、１２学級以上に配置するという基準に従いまして、そういった配置をしています。研修会という形を開いてはございませんけれども、適宜校長から、また学校運営のスタッフなどと協議しながら進めていくというところがあります。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそういったこともやっていただいて、司書教諭と学校司書の連携で、創造的な授業をやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"塚本委員","kind":"確認","question":"それから３６７ページ、３６９ページ、３７５ページの保健運営費について伺っていきたいと思います。朝７時の段階での気象情報がこうだから休校です云々といった情報発信をしていくようなお話も聞いていたのですけれども、確認でお知らせください。","respondent":"矢部教育総合支援センター長","answer":"７時の判断は変わりませんけれども、特別警報と暴風警報の２つが出た場合は、休校というお知らせをホームページにしていただくようになっております。今年度はまだその事案が発生してございませんので、今後努めてまいります。","id":"exchange-104"},{"speaker":"塚本委員","kind":"質問","question":"この４つを満たしていれば、容認してもいいのではないかといった通知です。このことに関して、都から区にどのように伝えられているのか、初めにお伺いします。","respondent":"矢部教育総合支援センター長","answer":"スマートフォン等の持込みについては、国からの指示に従って、特段、東京都からの通知はまだ認知してございません。","id":"exchange-105"},{"speaker":"塚本委員","kind":"質問","question":"この４つの条件は品川区としてどのように捉えているかというところが、焦点というか、お伺いしたい点になってくるかと思います。この４つの条件は、区としてこういった４つの条件が品川区内の学校でどのような状況にあると認識しているのか、お聞きいたします。","respondent":"矢部教育総合支援センター長","answer":"これまでどおり、中学校も小学校も原則、持込み禁止です。ただし、事案によっては、保護者と相談しながら個別に対応しているケースもあると理解しています。","id":"exchange-106"},{"speaker":"塚本委員","kind":"質問","question":"つまり、この４つの条件を満たしていれば、どうぞ、お持ち込みくださいというスタンスなのか、いや、そうではないのだと。１つの選択肢というか、検討すべき事案ではないのかなとも思っておりますので、もう一度ご答弁をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"原則禁止にのっとって、これまでに引き続き、ただ個別の対応には応じていくです。中学生はブザーを配付していますので、それを活用して自分で身を守るという点で、登下校の安全を守りたいと考えております。","id":"exchange-107"},{"speaker":"塚本委員","kind":"質問・要望","question":"身を守るという部分ではなくて、保護者との連絡手段として、要望というかお声が出ているので、ブザーはちょっと、この問題の解決としては違うのです。その点についてお考えをお聞きしたいのと、保護者として子どもと連絡を取りたいということに応えていくことについて、もう一度。","respondent":"矢部教育総合支援センター長","answer":"個別の対応については、その辺りは十分保護者の方に説明しながら対応していくことになるかと存じます。２点目、検討の余地がありますけれども、検討してまいりたいと考えています。","id":"exchange-108"},{"speaker":"塚本委員","kind":"質問","question":"その部分について、１つはＩＣＴ支援員というのが、いよいよ支援員を強力に配置してというところでの支援という体制は伺っておりますけれども。こういったところについてお伺いしたいと思います。","respondent":"工藤指導課長","answer":"教員が授業づくりのモデルを共有することも可能であると考えておりますので、そういったところで、個々に補い合いながら進められればと思っています。その教員による伝達研修も行いながら、授業の効果的な活用というのは図っていきたい、そのような体制を考えているところです。","id":"exchange-109"},{"speaker":"塚本委員","kind":"質問","question":"あるいは、例えば校長会などをＺｏｏｍでやったりしたなどということがあったり、この先やるかもしれないのか。そういった、教員における現状のオンライン活用の様子というのをお伺いしたいと思います。","respondent":"工藤指導課長","answer":"Ｚｏｏｍの活用につきましては、先月末にもＺｏｏｍの活用研修は、Ｚｏｏｍを使って全ての学校がつながって行ったところです。研修をオンラインで進めるということも併せて進めてありますので、そういったところで活用を図って、またその活用の仕方も共有を図っているです。","id":"exchange-110"},{"speaker":"塚本委員","kind":"質問","question":"教職員の方々がしっかりとそういった機器に慣れるというか、少しでも親しむというか、やはり慣れるということですか。今、１つの方策かと思いますので、今後とも教職員の間でも使っていくような場面をつくっていくようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"あべ委員","kind":"質問","question":"３５５ページ、それから３６７ページ、３５５ページの帰国児童・生徒等支援費についてもお伺いしたいと思います。今後改築する学校の教室数を多めに取るなど、何らかの準備をしていくことが必要ではないかと思うのですが、いかがお考えか尋ねました。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"３０人学級に絡みまして、今後の校舎改築等の対応です。３０人学級に対する考え方も出されているという中で、その辺は見据えながら、整備はしていく必要があるのかなと考えているところです。 痴漢対策のことです。生活指導主任会が定期的にありますので、今のような内容について一度確認しまして、また周知を広めていきたいと考えております。","id":"exchange-112"},{"speaker":"あべ委員","kind":"質問・要望","question":"通学途中に痴漢に遭って、怖くて学校に行けなくなってしまうというようなことは、もうこれ以上起きないようにしてほしい。ぜひ工夫していただきたいと思うので、今後について一言頂ければと思います。","respondent":"矢部教育総合支援センター長","answer":"委員のご指摘のとおり、もう一度確認して、できる範囲の中で進めてまいりたいと思います。","id":"exchange-113"},{"speaker":"あべ委員","kind":"質問・要望","question":"それから、６月の一般質問でも伺いましたけれど、病気やけがなど長期療養中の児童・生徒への活用は、検討状況はいかがでしょうか。教員以外の方もぜひＩＣＴの力を活用していただくことで、より学校をパワーアップしてほしいと求めましたが、いかがか尋ねました。","respondent":"工藤指導課長、矢部教育総合支援センター長、篠田学務課長","answer":"そういったことも検討の課題として、検討の課題というのは、そういったことの検討を具体的にしていくところです。そういったところで、今… 長期休業のお子さんに対する対応です。ただ、物が行くだけでは活用がうまくいきませんので、そこについては十分、間を詰めて丁寧に対応して… 機器の配備の関係で、教員以外の方の分ということでご質問です。","id":"exchange-114"},{"speaker":"あべ委員","kind":"質問・要望","question":"これも、再入国が始まっておりますので、子どもたちがかなり増えておりますので、ぜひ適切に対応してほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"鈴木（博）委員","kind":"質問","question":"このマニュアルも踏まえながら、この間の品川区の、学校における新型コロナウイルス感染症対策についてお伺いしていきたいと思います。品川区はどの感染レベルに相当すると教育委員会は考えておられるのか尋ねました。","respondent":"有馬庶務課長","answer":"ここのところ、学校でも感染が出てきたところですので、感じとしてはレベル１からレベル２の間というような肌感覚は持っているところです。それに基づいて、今、対応しています。","id":"exchange-116"},{"speaker":"鈴木（博）委員","kind":"質問","question":"品川区では子どもたちにどのように感染予防について教え、理解させているのでしょうか。特に教職員の目が届かないところでの注意事項など、具体的な取組みについて、示すよう求めました。","respondent":"矢部教育総合支援センター長","answer":"現在は、区で作成している感染予防ガイドラインにのっとって、３つの密の回避を徹底すること。感染予防教育につきましては、体育、保健等の中で指導内容としていますし、日常生活のお子さんの実態に応じて個別指導を展開しています。","id":"exchange-117"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、一般質問に引き続き、マスクについて再度お尋ねします。併せて、フェイスシールドやマウスシールドなどについても、教育委員会のご見解のご説明をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"ただ、お子さんによって（マスクを）したい、外したいというお子さんもいますので、個別に対応しています。飛沫防止に若干弱いというのは認識していますが、そういったお子さんの指導に対して、距離を取ってマウスシールドをつけていることもあります。","id":"exchange-118"},{"speaker":"鈴木（博）委員","kind":"確認","question":"皆勤賞なるものは、既に今、小学校ではなくなったと考えてもよろしいのでしょうか。その確認もお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"実際は欠席が多い場合も、進学先に理由を伝える方法はあるです。そこは学校の裁量で、それを楽しみに来ている子どもも実際にいましたので、そういう裁量になってあります。","id":"exchange-119"},{"speaker":"鈴木（博）委員","kind":"質問","question":"先ほども質問がありましたが、コロナ流行下においても、感染リスクに配慮しつつも積極的に進めていかなければならないと考えます。コロナ禍で配慮している点についてもお知らせください。","respondent":"篠田学務課長","answer":"基本的には、一人ひとり個別に授業のスタイルで、間を取りながら前を向いて会話しないで給食を取るという形が子どもたちのほうの対応です。６月の学校再開当初は、そういった細かい工夫をしながら、できるだけ感染拡大の防止に努めているところです。","id":"exchange-120"},{"speaker":"鈴木（博）委員","kind":"質問","question":"私の新型コロナウイルス感染症に関しての一連の質問は今日で終わりますが、新型コロナウイルス感染症は高齢者では今でも非常に恐ろしい病気です。温かみのある配慮を加えることによって、それで運営してこそコロナと共存する新しい生活様式だと確信して、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"性教育の充実を求めてきましたけれども、アフターピル、こうしたことの議論がＮＨＫなどでも報道されておりました。現に早まっている性体験に対して、子どもたちが正しく知識を持って対応するための教育が必要だと思いますけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"実際の指導には、水着の隠れる部分は見せたり触らせたりしないようにという指導は、日常的に小さな子でもやってあります。ＣＡＰやセーフティ教室の中でも、犯罪被害の防止に努めているところです。","id":"exchange-122"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうしたことも含めて教えてもらえたらと私も思っています。性の権利を守り、そして学び、男女ともに学んでいくことが必要だと思いますけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"こちらにいらっしゃる皆さんがそうだと考えております。学年の発達段階に応じて進めてまいりますが、国も性被害防止については検討していますので、我々も注視して対応していきたいと考えております。","id":"exchange-123"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"お互いの体を知り、そしてどうしたらどうなってしまうのかというのを、早い段階から教えていくことが必要だと思うのです。そこはいかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"学習指導要領にのっとるのは先ほどのとおりですが、教育会では、体育部門、保健部門がありますので、そちらのほうでの検討でいろいろな授業が展開される可能性はあります。","id":"exchange-124"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それは駄目なのだというのを教えても、そして性的アイデンティティや性的指向ということも含めて早い段階から教えていかないと、結局。ぜひその立場に立って、学校教育要領を含めて抜本的に見直してほしいと求めましたけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"本区の学校教育要領も学習指導要領を基に進めてありますので、意見は分かりましたけれども、発達段階に応じて、今、計画的に進めているところですので、あくまで人権尊重を基盤にして、各教科・領域において指導してまいりたいと考えております。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"しっかりと法にのっとった形で、放射性物質の検査についてはやめる方向でお願いしたいと思いますが、その見解をお聞きします。それから３５５ページ、教育指導費になるのか尋ねました。","respondent":"篠田学務課長、品川財政課長、有馬庶務課長、矢部教育総合支援センター長","answer":"福島県産のものについてもきちんと検査されているということは認識していますので、これまで震災以降、ずっと続けてきたという経緯があります。… 大体、学校１校改築分ぐらいを目安に積み立てております。今後、毎年１校から２校ぐらい、今、改築を進めているのですけれども… ８３運動につきましては、推進委員会が発足してということですので、区はあくまで側面支援という域です。いずれにしても子どもの安全に関わることで… モンスターペアレントという言葉でお尋ねになられたと思います。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"年に１校、２校という形でということなのですが、長期にわたっての計画があるのかを確認したいと思います。ここをお聞きしたいと思います。","respondent":"品川財政課長、矢部教育総合支援センター長","answer":"こういうところにも応じて、積立額というのは状況を見て変えていこうと考えています。今後、学校改築が続きますので、それを維持できるような形で、資金もしっかりと準備をしていきたいと考えております。 直接電話で頂くこともあります。少なくとも、悩んでいる保護者が多いので、学校名が分かれば、こちらから連絡をして、学校のほうで丁寧に対応しています。","id":"exchange-127"},{"speaker":"西本委員","kind":"質問","question":"そこのところの認識はどこまであるのでしょうか。その場合の、例えば弁護士を雇う、相談に乗るなどという体制は、どのぐらいまでできているのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"専門性のある者がおりますので、そのチームで学校を訪れて、どんなケースかというのを対応します。子ども家庭支援センターとも連携しまして、必要に応じて、福祉や医療（の部門）とも相談して進めてまいります。","id":"exchange-128"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３５１ページ、８３運動経費、３６１ページ、特別支援教育費、３６５ページ、図書館運営費からお伺いしたいと思います。８３運動経費は、関連して、ＰＴＡの方や地域の方々と区と協働で取り組む、児童・生徒の登下校における安全対策・防犯対策についてお尋ねいたします。","respondent":"有馬庶務課長","answer":"８３運動の見守りの効果ですが、これをどういうふうに検証するかというのは、なかなか難しい部分があるかと考えております。８３運動というのは、１つの生活習慣の中で、なかなか効果を出しにくい面があるかとは考えております。","id":"exchange-129"},{"speaker":"こんの委員","kind":"質問","question":"先週の総務費のところでも触れましたけれども、警視庁が発信している「メールけいしちょう」という不審者情報、こうしたメールはご存じでしょうか。こうした取組みは必要ではないかと考えるわけですが、いかがか尋ねました。","respondent":"有馬庶務課長","answer":"それをどういうふうにはかるかというところは難しいという説明をさせていただいたものです。令和元年度でも、発報で、ある程度、緊急事案とされたものが６件程度あるということですので、そんなに件数は多くありません。","id":"exchange-130"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ今後、考えていただければと、要望で終わります。この事業の中身をお尋ねする前に、特に特別支援学校教諭免許状を有しなくてもいいとされておりますけれども、免許の保有状況を説明を求めました。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"１３学級あります。それと、学級数は、令和２年度、固定級が２５学級、通級が７学級です。 特別支援学級に配置する、あるいは特別支援教室に配置する教員につきましては、経験者をできるだけ配置できるよう東京都にも要望しています。そういったバランスをよく見ながら、継続した支援ができるよう配置を行っているところです。","id":"exchange-131"},{"speaker":"こんの委員","kind":"質問・要望","question":"指導していく中で、どのようなコミュニケーション、指導力といったことへの指導というのはあるのでしょうか。真摯に保護者と向き合っていただいて、適切かつ十分なコミュニケーションで信頼関係を築けるようにしてほしい」、こうしたことを求める声があります。","respondent":"矢部教育総合支援センター長","answer":"ただ、そのときには、今、若手の特別支援教室の教員などもおりますので、ベテランと一緒に対応しているようなところです。特別支援教室については６９５人が昨年度までの数字です。","id":"exchange-132"},{"speaker":"こんの委員","kind":"提案","question":"今お話を伺って、どうか専門家の方の助言や指導といったことを取り入れながら、よりよい信頼関係を築いていっていただきたい。学校図書館の本を電子化して、もっと子どもたちの本に親しむ環境ができるのではないかと考えますが、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"図書館で検討いたしまして、現実的に検討できるかどうかというのを、計画立てて進めているところです。先ほどご案内しました青空文庫等、著作権の調整がついたサイトについてご紹介を進めて、これから調整させていただきたいと思ってあります。","id":"exchange-133"},{"speaker":"こんの委員","kind":"質問・要望","question":"近い将来、著作権のことなどの課題がクリアになったならば、学校図書館の本がタブレットで見られる。こうした環境を作っていけるよう要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"職員ということで拘束されてくるのではないかと想像するのですけれど、その辺のところは影響がないのかどうかということを１点確認させてください。その辺の規定があるのかどうかも確認させてください。","respondent":"工藤指導課長","answer":"学校地域コーディネーターは任期はございませんので、継続して任用することが可能なものです。１年ごとの任用ではありますが、それを継続することは可能ですので、続けていただける方がそのまま続けていただけるような状況です。","id":"exchange-135"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"本当に、学校と地域をうまくつないでいる方なので、これからも校区教育協働委員会とも協力しながら、いい形で進めていってほしいと求めました。質問の中で、品川コミュニティ・スクールにかける品川区の思いがもしあれば改めて一言頂ければと思うのですが、。","respondent":"工藤指導課長","answer":"やはり重要であると認識していますので、学校支援地域本部でのボランティアであるとか、そのまま進めていきたいと考えています。","id":"exchange-136"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これも要望にします。８年生が今、行っていると思うのですけれど、この取り組み状況を教えてほしいと求めました。","respondent":"工藤指導課長","answer":"現在、義務教育学校６校と中学校、合わせて８校で実施しています。宿泊型で行っているのが４校、通学型が４校ということで取組みを進めているところです。","id":"exchange-137"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ただ、少し気になっているのは、今８校だけがやっている中で、やはり全校展開できないのかなという思いもあります。それから夏の間ですから、やはり全員が受けられる体制も取ってほしいと、その辺のお考えを教えてほしいと求めました。","respondent":"工藤指導課長","answer":"ご指摘いただいたように、体制づくりのところでは、やはり多くの教員、あるいはボランティアなどの協力体制というところが必要です。支援にあたる、併せて取組みを進めて、拡充を図っていきたいと考えています。","id":"exchange-138"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"日数も長くしなくても、そういう機会をつくっていただいたほうがいいのではないかなと思いますので、これは要望にしておきます。就学援助を受給しているご家庭の６年生の勉強の機会をつくってもらっていた中で、その辺の進め方について、指導という点でお考えを説明を求めました。","respondent":"工藤指導課長","answer":"当初、予定していました３年目ということで、令和元年度におきまして学習支援については終了したところです。ですので、その１２名の進学に合わせて、進学支援のほうは継続しておるところです。","id":"exchange-139"},{"speaker":"鈴木（真）委員","kind":"質問","question":"やはり少し離れた学校に行っているところで、その辺は何か考えていらっしゃるのかどうか、説明を求めました。","respondent":"工藤指導課長","answer":"学芸大学の連携事業の場合は、会場が教育総合支援センターと、あと品川図書館という２会場で、週１回、放課後に行っていたものです。学習支援は行っていけるとは考えてありますが、いわゆる補充学習等につきましては、しっかりと取り組んでいきたいと考えています。","id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問","question":"ほかの学校でも、全てのページは難しいかもしれませんけれども、このような取組みをお願いしたいと思いますが、お考えを伺います。あれば、工事の方あるいは教職員、児童・生徒にけがなどはなかったのか尋ねました。","respondent":"工藤指導課長、矢部教育総合支援センター長、小林学校施設担当課長","answer":"やはりお互いに、また経験の浅い方がそれを習うだけではなく、新しい発想でというところがあります。同じ学年で… 学校だよりの振り仮名等ですが、本当に優しい対応だと感じております。確かに時間はかかりますけれども、好事例として紹介していきたいと思います。 改築工事での現場での事故というのは、ないものと記憶しております。","id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そういったところを地域未来塾でどのようにカバーしていらっしゃるのでしょうか。実施日数を増やすなどの、あるいは財政支援等で支援してほしいと求めましたが、いかがか尋ねました。","respondent":"工藤指導課長","answer":"地域未来塾につきましては、学校再開と同時に各学校、予定に従いまして進めることができております。自分で自学を進めているというところがありますので、そういったものを指導員の指導も含めながら補充を効果的に進めていきたいと考えています。","id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問","question":"どのような方が何人ぐらい学校を巡回しているのでしょうか。日数等は先ほど伺いました。","respondent":"篠田学務課長","answer":"推進校は毎月１回、それ以外の学校は学期に１回回っているという形です。回っているのは、民間のコンピュータ関係に詳しい方で、教育情報化コーディネータ２級という資格を持った方が回るという形で契約しています。","id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問","question":"この資格をお取りになって、いろいろな人材派遣のところに登録し、学校を巡回している方が多いと伺っています。この後、タブレットが支給された場合に、どれぐらいの頻度で学校を巡回していただけるのか尋ねました。","respondent":"篠田学務課長","answer":"したがいまして、かなり手厚くやっていく必要があるとは考えてあります。今のところ、様々検討しているところではありますけれども、少なくとも今まで以上の形での配置をしていきたいと考えているところです。","id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"質問","question":"それを授業でどういうふうにするかということの理解がある方が、ＩＣＴ支援員になり、熊本市ではかなり実績が上がっていると伺っています。時には授業に一緒に入ってというところまで踏み込んでのＩＣＴ支援員の活用について、いかがか尋ねました。","respondent":"篠田学務課長","answer":"仮に１つの学校に毎週１回ずつ支援員を派遣したとしますと、年間ではおよそ８,０００万円近くかかるだろうと見込んでいるところではあります。","id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"意見","question":"週１日だと８,０００万円余ということですので、手厚くお願いいたします。ＩＣＴ支援員の方も教職員の方とのコミュニケーションがうまく取れるように、学校でいろいろと配慮をお願いしますが、最後にそこだけお願いしますとの意見を述べました。","respondent":"篠田学務課長","answer":"これから、今まで入られた方も加えて、新たな方も入ってこられますので、きちんと学校と連携した形で、実のあるものとなるように、私どもも注視してまいりたいと思っているところです。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"学年ごとに必要な学習が身についていると、どのようにして判定するのですか。そして、判定テストでも行って、身についていない児童・生徒がいた場合、補習や再テストを行うのか尋ねました。","respondent":"工藤指導課長","answer":"それにあたっては、日々の学習の積み重ね、平素の授業の積み重ねをもって行います。その中では単元末に行うような確認テストなども含まれますけれども、あくまでも平素の授業などの成果を見て判定するというものです。","id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"自主欠席を行うことで、児童・生徒の学習にさらに遅れが生じることが予想されますが、この辺について学習保障はきちんとできるのですか。だったら、子どもたちはどういうふうにされるのか尋ねました。","respondent":"工藤指導課長","answer":"ホームページで課題を提示し、それを回収し、また教員が指導するなど、リモート学習も進めておりました。そういったところで学びを止めないという動きは、学校がしっかりと取り組んでいるところがあります。","id":"exchange-148"},{"speaker":"須貝委員","kind":"質問","question":"だったら、学校は要らなくなるのではないですか。そういうのも使って、できるだけ遅れないようにやるべきだと私は思うのですが、もう一度お考えを説明を求めました。","respondent":"工藤指導課長","answer":"そういった学校行事等を進める中で、対面で行うことのよさというものを認識しつつ、そういったところで参加できない部分をどう補うか。そこの参加をどうしていくのかというのは、そういったところはまた工夫をしながら各学校で進めていくよう、指導してまいりたいと思います。","id":"exchange-149"},{"speaker":"須貝委員","kind":"質問・要望","question":"その中で、１つここでお聞きしたいのですが、オンライン教育・授業のメリット・デメリットを教えてください。品川区はオンライン授業を発展させていくつもりなのか、そしてデメリットについてどういうふうにお考えか、説明を求めました。","respondent":"工藤指導課長","answer":"オンラインで取り組むというところで、学校で進めているもので言えば、コロナ禍の中では非常に難しいところがあります。こういったものを使いながら教育に活かしていくことが必要であると認識しています。","id":"exchange-150"},{"speaker":"須貝委員","kind":"質問","question":"だったら、こういうことをどうして教育委員会は考えていないのですか。そしてずっと考えて見守っていくということが、教育委員会として大事なことだと私は思うのですが、いかがか尋ねました。","respondent":"工藤指導課長","answer":"ですから、やる気という部分で言えば、例えば自分の進度で自学自習ができることで勉強への意欲が湧いたという事例も、私どもは認識しています。","id":"exchange-151"},{"speaker":"須貝委員","kind":"質問・要望","question":"この子どもたちをどういうふうに学ばせていくのだ、そして、教育というのを見ていただきたいと私は思います。何かご意見があったら、最後に一言言ってください。","respondent":"工藤指導課長","answer":"頂いたご意見がありますけれども、私どもは、やはりオンライン教育というもののよさを活用しながら学校教育を進めてまいります。","id":"exchange-152"},{"speaker":"安藤委員","kind":"質問・要望","question":"３６３ページ、教科書採択事務、３７３ページ、普通教室増設工事等に触れながら、少人数学級について伺います。伺いますが、以上２点を改めて求めたいと思いますが、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"私どもも次回の採択に向けて検討してまいりますが、１つは、最初に委員がおっしゃったような理由になります。区役所と教育総合支援センターで教科書展示を行いましたところ、来場者は延べですけれども１１６名、アンケートは７７通でございました。","id":"exchange-153"},{"speaker":"安藤委員","kind":"質問・要望","question":"今の説明を伺っても、別に立場がどうであれ、住民の関心事なのです。実際にどのように普通教室を増やしているのか、それぞれ伺います。","respondent":"篠田学務課長","answer":"子どもたちの入学予定者が増えてくるということから、それにあらかじめ備えるために、普通教室を用意しておくというものです。設置しているような部屋で、そのまま部品だけを入れれば使えるような部屋もあるのですけれども、工事で普通教室化するといったやり方をしています。","id":"exchange-154"},{"speaker":"安藤委員","kind":"質問","question":"もう一点伺いたいのですが、これらのように、現状、普通教室増設に使える多目的室などの教室は、これから改築していくというところはあるでしょうけれど、区内全体で、まだ改築していないところも含めてどれだけあるのか、伺いたいと思います。","respondent":"篠田学務課長","answer":"今から５年ほど前に一回全部洗い出しをしたときには、転用を行っているので、現状は百を切るような形の数字になっているのかと思います。実際には、いろいろな形で活用していますので、必ずしもきちんとした形での把握は難しいと考えているところではあります。","id":"exchange-155"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれど、本来なら３０人なのに小学校１年生から４０人というのは、いかがでしょうか。なぜ素直に学級数を増やさずに、あるならその解決に区教育委員会は援助しているのか、伺いたいと思います。","respondent":"篠田学務課長","answer":"１年生に関しましては、学級編制、法律でも３５人と定められているところですけれども、特例的に４０人での対応も可能であるという形です。法律を満たしたような形の３５人の学級編制が、特例の措置を取った上で、４０人に近い学級の編制をしています。","id":"exchange-156"},{"speaker":"安藤委員","kind":"質問","question":"この加配という現状についても伺いたのですが、現在の区内の学校の加配の状況について、区の独自教員の数は今、何人になっているのか。区が独自に加配する区費講師、そういう方もいらっしゃるということなので、その人数も伺いたいと思います。","respondent":"篠田学務課長、工藤指導課長","answer":"私どももできるだけそういう対応は取っていきたいとは考えているところですけれども、ここまで来たところです。そういうふうに増えてくれば、必然的に何らかの対応をしなければいけなくなってきますので… 小・中学校、義務教育学校を合わせて７１名、加配を頂いているところです。区で少人数指導を進める、また、あるいは教科担任制を進めるために区費講師として任用している者は５９名です。","id":"exchange-157"},{"speaker":"安藤委員","kind":"質問・要望","question":"こうした費用と人材措置をさらに強めた上で、区独自にクラスの規模を減らすということのために充てるべきだと私は思います。伺いますが、教員の増員を検討するよう求めますが、いかがか尋ねました。","respondent":"篠田学務課長、工藤指導課長","answer":"新たに教室を増設しようとしますと、今あるグラウンドにプレハブを建てるなど、かなり特別な対応を取っていかないと厳しい状況があります。最低でも七、できる限りの対応は取っていくつもりではありますけれども… 教員の数につきましては、やはり国および都の基準に従いながら進めていきたいと考えています。","id":"exchange-158"},{"speaker":"安藤委員","kind":"質問・要望","question":"コロナ禍を経て、大きく考え方も変わってきております。子どもたち第一に、ぜひ少人数学級に、区として前進していただければと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"たけうち委員","kind":"質問・要望","question":"質問させていただきまして、あそこは台場と言うぐらいですから、小学校が３階建て。校庭を一回出ないといけないという中で、いろいろと対応を要望させていただいたのですけれども、その後の状況について分かればお知らせください。","respondent":"矢部教育総合支援センター長、小林学校施設担当課長、篠田学務課長","answer":"委員ご質問の１番目と３番目についてお答えいたします。様々な工夫を学校が取り入れてあります。 現在、取付け位置および取付けの方法などを検討しております。今後、都なども含めて協議して、取り付ける方向で考えていきたいと考えています。 新型コロナに感染した児童・生徒の数ですけれども、昨日時点で、今、１０名です。学校の数で言いますと５校です。","id":"exchange-160"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それは１つの成果かと思うので、そういうものがもしあれば、分かれば教えてほしいと求めました。都営なので、勝手にできないので、その上で、またさらにやりますということだと思うのですけれど、一応確認させてください。","respondent":"矢部教育総合支援センター長、小林学校施設担当課長","answer":"スクールカウンセラーの実施状況ですが、４月から６月についてはお子さんがいないということもありまして、ほぼ実績はございません。ＰＴＡの協力も仰ぎましてフィールドワークを行い、主体的に調べ… そのとおりでございまして、今後、取り付けていくよう進めてまいりたいと考えております。","id":"exchange-161"},{"speaker":"たけうち委員","kind":"質問・要望","question":"きちんと件数も確認されているということで安心しました。全校に週１回ですか、５年生・７年生以外のところでも、相談したければ対応できるということですよね。","respondent":"矢部教育総合支援センター長","answer":"教育総合支援センターでは、学校のほうは子どもたちのこともありますので、その辺りはバランスを取って進めているところです。思い出づくりのほうは、これまでどおり、学校の工夫を活かしてしっかりと努めていきたいと考えております。","id":"exchange-162"},{"speaker":"大沢委員","kind":"質問・要望","question":"３５３ページ、教育指導というか、受験指導について伺います。そこの取組みについて、今、通告した質問の前に聞かせていただきたい。","respondent":"横山品川図書館長","answer":"コロナ禍で全国の図書館が閉館した際に、青空文庫の読書数というかアクセス数が非常に上がったということで紹介されております。名作を中心に１万６,０００点ほどの、これをまずは、使えるものとしてはご紹介できるかというところでお話をさせていただいたところです。","id":"exchange-163"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこをご披露いただきたいとは思っていたのですけれど、児童・生徒に読んでもらうには、古典なのです。そういう新聞の記事が載っているわけですから、三部作も載っていますので、これは大いに利用していただきたいと思うのですけれどもいかがか尋ねました。","respondent":"横山品川図書館長","answer":"品川区での昔話を、以前に広報紙で紹介したものを一つ一つご紹介するであるとか、「わらべうたであそぼう！それぞれの小さな子どもから取り組めるようなもの、著作権の調整は困難なのですが、電子書籍の振興と併せて取り組んでいきたいと思ってあります。","id":"exchange-164"},{"speaker":"大沢委員","kind":"質問・要望","question":"中学３年生の受験指導について伺いたいと思いますが、一つ一つ伺ったことを、課長の感想なり私見なりを伺いたいと思います。学校対応では難しいから塾の先生にも確認してほしい」というような、またはどのように考えていらっしゃるか、ご披露いただきたい。","respondent":"工藤指導課長","answer":"一部の単元の中で、さらにその一部を除外するという表記といった、東京都教育委員会からの説明です。ですから、指導内容をきちんと定着させるという観点で指導にあたることが重要であると考えて、学校にもそのように丁寧に指導しています。","id":"exchange-165"},{"speaker":"大沢委員","kind":"意見","question":"○○ページ以降除外と明記してほしい」「教育委員会が挙げている除外箇所が、先生は結局、全範囲を急ぎ足で教えることになると言っている。","respondent":"工藤指導課長","answer":"確かにそのようなお声があるということは認識しているところでもあります。指導内容をきちんと定着させるという観点で、生徒に対しても指導して、確実に定着するというところをもって安心していただければと考えています。","id":"exchange-166"},{"speaker":"大沢委員","kind":"質問・要望","question":"塾の先生、都の教育委員会に範囲確認の電話をしてもらちが明かないというようなことなのですが、そこのところを密に取ってほしいと求めました。そして学校というか先生の役割、どのようにお考えになるか、教えていただきたい。","respondent":"工藤指導課長","answer":"そういったことの関連で、やはり児童・生徒のよりよい成長のためにお互い協力して進めていくということが必要であると。そういった役割というのは、やはり子どもを中心にしてお互い協力していくことだと認識しています。","id":"exchange-167"},{"speaker":"大沢委員","kind":"質問","question":"２者が相まってということで、先生というのは技能や知識を育んで、これを子どもたちに。何というのでしょうか、どういうふうに課長は考えられ、説明を求めました。","respondent":"工藤指導課長","answer":"つかず離れず、また、つくときはつくと。やはり干渉する度合いなども必要に応じて助言したりして行っているところです。","id":"exchange-168"},{"speaker":"大沢委員","kind":"意見","question":"近年、つかず離れずが逆に過干渉になって、子どもも先生方も親御さんも疲れ切っているという部分が大いにあるのではなかろうかと私は思っています。","respondent":"工藤指導課長","answer":"そういった先生になれるようにやってほしいということは、常々、私どもが指導してきたところです。誰か一人でもつながることが、その子の未来を開くことになると信じて進めていくことだと思ってあります。","id":"exchange-169"},{"speaker":"大沢委員","kind":"意見","question":"ぜひとも幾らか余裕を持った教育、余裕を持った子どもたちに対する接し方であってほしいし、そういう知識であってほしいと思います。希望で終わらせてもらいますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-170"},{"speaker":"石田（秀）委員","kind":"提案","question":"私は具体的な提案をしたいと思っていますので、ぜひお聞きいただいて、必ずと言っていいほど実現していただきたいと思っています。だけど、そういうところでやれるというのも１つの提案であって、こういうところをぜひ考えてほしいと求めましたが、ご見解を説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"そのような中で、移動教室などの行事はほとんどが中止となっており、６年生の今後の支援は特に大切であると認識しています。現段階では、各学校で記念行事の実施や思い出を振り返るＤＶＤの作成など、それぞれの創意工夫に基づく取組みが企画されているところです。","id":"exchange-171"},{"speaker":"石田（秀）委員","kind":"提案","question":"やってあげたらと言ってやらないと、では提案しろと各学校にみんな言って、「こういうことをやってよ」と言うのか。そこの考え方を変えてくれという質問をしているので、もう一回答弁をお願いしますとの意見を述べました。","respondent":"中島教育長","answer":"例えば一例では、浅草花やしきを１日借り切って、そこでみんなで過ごそうではないかと。しかしながら、それぞれの学校の単位で実施できるものというのは、幾つか出てくるのではないかと考えます。","id":"exchange-172"},{"speaker":"石田（秀）委員","kind":"提案","question":"そういうことで、各学校もそういうメニューがあれば提案できると思いますので、集大成の部分で子どもたちに何かの行事をやれる。それはぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-173"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/964460?Template=document&Id=1494#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":128442,"voices":395}},{"id":"r02-20201016-4","meetingId":"r02-c-settlement","date":"2020年10月16日","dateIso":"2020-10-16","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を115件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"湯澤副委員長","kind":"質問・要望","question":"販路拡大支援助成の再度実現、プレミアム付商品券の再度発行を要望いたしますが、ご見解をお知らせください。併せて、区は今後どういった支援策を行っていくのかも教えてほしいと求めました。","respondent":"久保田地域振興部長","answer":"区内中小企業の経営基盤の下支え支援としまして、今年度末までは継続して実施してまいります。今後につきましても、区が実施する様々な助成メニューや、国や東京都の助成金などを勘案し、本事業も含めまして適宜適切な支援策を進めてまいります。","id":"exchange-001"},{"speaker":"湯澤副委員長","kind":"提案","question":"確かに事業名だけを見ていても、自分が受けたい支援がどういったものなのかを知るのが困難かもしれません。区民により分かりやすいよう、フローチャートやチャットボットの活用を提案いたしますが、ご見解をお知らせくださいとの意見を述べました。","respondent":"久保田地域振興部長","answer":"中小企業支援サイトなどに支援策をまとめて表示し、また、見られる方に分かりやい表示をこころがけてそれぞれ案内をしてきたところです。区の事業でも取入れているものがありますので、引き続き研究してまいりたいと考えているところです。","id":"exchange-002"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"ぜひ支援を必要としている区民に分かりやすく示せるよう努力していただきたいと要望します。会派から要望しておりました品川区ＰＣＲ検査センターが５月１２日に区役所第二駐車場内に設置され、ＰＣＲ検査専門の施設として。","respondent":"福内品川区保健所長","answer":"検査で陰性であっても感染の可能性が否定できないため、新型コロナウイルス感染症の潜伏期間にあたる１４日間の自宅待機をお願いしています。鼻をかんだ後の鼻紙等は袋に入れ、袋の口を縛って捨てるなどの工夫も大切です。","id":"exchange-003"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"今お話しいただいたような新型コロナウイルス感染症への新しい取組みについて、区民はどこで情報を確認すればよいのでしょうか。命を絶ってしまうケースがあると報告されておりますが、心のケアについても対策があれば教えてほしいと求めました。","respondent":"福内品川区保健所長","answer":"机等をアルコールまたは次亜塩素酸ソーダを用いてふき掃除するなど、確実な消毒を学校に指示し、対応していただいています。次に、心のケアについては、自殺対策も含め、日頃の普及啓発を継続的に実施していくことが重要と考えています。","id":"exchange-004"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"収束のめどが立たないような場合には設置の継続を要望したいと思いますが、いかがでしょうか。区民に対する供給量は十分であるとお考えか尋ねました。","respondent":"福内品川区保健所長","answer":"必要な方に必要な検査を迅速に対応できるよう、実施状況等も勘案しつつ、医師会と協議を行ってまいります。昨年度と比較しても約１２％多い十分な量が供給される見込みと聞いております。","id":"exchange-005"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"次に、義務教育過程におけるオンライン教育について、お尋ねいたします。２０２０年度中の配備と大きく前倒しすることとなり、Ｗｉ－Ｆｉ機能の拡充、周辺機器の早期整備を要望してまいりました。","respondent":"齋藤教育次長","answer":"９月、１０月の第３回区議会定例会で上程する区が７つございまして、遅れがあるということはございません。次に、再度の学校休校となった場合でも学びの保障に努めるほか、資質や能力を育成するＧＩＧＡスクール構想の理念を実現するよう取組んでまいります。","id":"exchange-006"},{"speaker":"湯澤副委員長","kind":"質問","question":"推進校や教員同士の会議などで既にＺｏｏｍを活用しているとお聞きしましたが、通信が途切れるなど今後の課題となるような事例はなかったでしょうか。対象となった生徒たちにはオンライン授業を行ったと伺いましたが、授業は不具合なく行えたのでしょうか、お知らせください。","respondent":"齋藤教育次長","answer":"当初６年生・９年生は１２月から、その他の学年は２月中の配付を予定しておりましたが、６年生・９年生の配付が年明けになる可能性もあります。","id":"exchange-007"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"特に要望の強かった受験を控える９年生、そして６年生などに対して優先的に取組んでいただけたことには本当に感謝申し上げます。オンライン環境についてですけれども、事情によって家庭内の通信環境が整えられない世帯に対して、通信費用を含めた支援を要望いたします。","respondent":"齋藤教育次長","answer":"トラブル対応のマニュアルを提供して丁寧にご説明するほか、ＺｏｏｍをＰＴＡ活動でご利用いただけるよう、ＰＴＡとの連携を深めてまいります。","id":"exchange-008"},{"speaker":"湯澤副委員長","kind":"質問","question":"し尿などの不衛生なごみはどこに廃棄すればよいのでしょうか。そして、新型コロナウイルス感染症陽性者や経過観察中の方は、避難所に避難をしてよいのか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"基本的には指定された区民避難所において、物資等を配給する予定となっております。し尿などの不衛生なごみについてですけれども、現在災害ごみの処理要領について、組織的にどのようにすべきかということを検討しております。","id":"exchange-009"},{"speaker":"湯澤副委員長","kind":"質問","question":"品川区においてそのような心配はないでしょうか。災害時には避難所として活用させてもらうことも、ウィズコロナ時代の避難所の在り方ではないかと考えますが、区の見解をお知らせください。","respondent":"滝澤災害対策担当部長","answer":"当然、大規模震災等が発生した場合には、先ほどの４割の許容ですので、約７万人が避難できない状況になり、かなり不足することが予想されております。併せまして、引き続き避難所の拡大について検討してまいりたいと思います。","id":"exchange-010"},{"speaker":"湯澤副委員長","kind":"質問","question":"区民の生命を守る避難所、避難場所の充実に前向きな検討をお願いいたしまして、私からの質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私からは、まず、長期基本計画についてお伺いします。今後の区政課題について、改めてお伺いをいたします。","respondent":"堀越企画部長","answer":"安全の３つを掲げ、それぞれ連携して取組むことで、多様化する課題に対応していくということにしています。人口の増加、高齢化の進行ですとか情報技術の進展、ライフスタイルの多様化などへの対応が課題と認識しています。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今、実施計画を策定していくという方針を示されておりますけれども、現在の検討状況と策定の考え方についてお聞きしたいと考えています。実施計画がまだできていない中で、来年度予算に向けてはどのように編成していくのか、その点についてもお聞きしたいと思います。","respondent":"堀越企画部長","answer":"長期基本計画の実現に向けて、重点的に実施する事業を示すものとして策定したいと考えてございまして、内容については。このコロナ禍の収束を見通せない状況で歳入の大幅な減少も見込まれるということで、区民の生活、区内経済についてしっかり施策として対応していく。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"お話しいただきましたように、もちろん区内の皆様の生活の安定、この辺を強調した予算を作っていっていただきたいと考えています。その辺について、両面でのお考えを説明を求めました。","respondent":"堀越企画部長","answer":"予定といたしましては、その事業を中心に行政評価を実施する方向で、内部での検討を進めているところです。行政評価が目的化というか、手段としてしっかりと活用できるような形でできるように工夫をしていきたいと考えているところです。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"一方で、今お話しいただきましたように長期基本計画に基づいた今後を見据えた区政運営を行っていくことが最重要項目だと考えています。長期基本計画に関する質問の最後にあたりまして、今後の区政運営に向けて区長のお考えをお聞きしたいと思いますが、いかがか尋ねました。","respondent":"濱野区長","answer":"にも限りある財源を最大限に有効活用して、区民が求めておられる大切なサービスを実施していくことが求められていると考えています。そのことのために努力をし続けてまいりたいと考えているところです。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"次の質問に移っていきますが、その施策の中で、まず障害者施策についてお伺いしていきたいと考えています。改めて障害者施策についての区のお考えと、品川児童学園を障害児者総合支援施設とした目的について、お伺いをいたします。","respondent":"伊崎福祉部長","answer":"に、障害者の方のライフステージを通して総合的・継続的な支援を実施し、施策を進めているところです。旧品川児童学園を障害児者総合支援施設とした目的ですが、児童から大人まで総合的・継続的な支援を実施できるよう、機能の強化を図ったものです。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その辺につきまして、区のお考えをお聞きしたいと思っています。障害者施策を推進する上で、担当者の方というのはどのように現場を体験しているのか、その点についてもお聞きしたいと思います。","respondent":"伊崎福祉部長","answer":"区内の事業所との連携を密にして、地域全体の福祉サービスの向上を図ることが重要だと考えております。ほかの職員も施設に足を運んで事業者から現場の声をお聞きするなど、障害者支援の実情について理解を深めているところです。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"障害児者総合支援施設は、地域生活支援拠点に求められる機能についての整備・充実を図っていくということで今までお話しいただいております。区が求める地域生活支援拠点としての事業内容と、現在の支援体制をどのように評価しているか、その点につきましてお答えをお願いいたします。","respondent":"伊崎福祉部長","answer":"それから医療的ケアへの対応、親亡き後を見据えた相談支援の充実、緊急時の受入れ対応。現在の支援体制については、これらの拠点機能の段階的な準備段階でございまして、引き続き取組んでいく必要があると考えております。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、全く新しい法人に変わってしまう、新しい事業者に変わってしまうわけですね。選定にあたりましては、その辺の区としてのお考えについてお聞きしたいと思いますが、いかがか尋ねました。","respondent":"伊崎福祉部長","answer":"現在の障害児者総合支援施設は３つの法人がそれぞれ指定管理を受け、区は建物を管理しているという形になっておりまして、様々課題を持っております。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"障害者施設の拠点として、例えばボランティアの育成などにも努めていっていただきたいと思うのですが、その辺についてのお考えはいかがでしょうか。この点につきましても強く求めてまいりますが、医療面の充実も図ってほしいと求めましたが、この点についてもお考えをお聞きしたいと思います。","respondent":"伊崎福祉部長","answer":"引き続き地域交流を進めながら、ボランティアの育成につながるよう取組んでまいります。さらに医療的ケアの充実につきましても、施設において医療的ケアの対応ができるよう、運営事業者の支援をしてまいります。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この施設を活用していただいて、障害者施策をどんどん進めていってほしいと求めましたので、その点も要望させてほしいと求めました。品川区の中で障害者の解雇という問題が出ているかどうか、その点についてまず１点説明を求めました。","respondent":"伊崎福祉部長、榎本総務部長","answer":"就労を目指していた障害者の方が企業から面接試験を保留されたため、就労支援移行事業所での訓練期間を延長して対応している状況ではあります。障害特性に応じた多様な就労形態を検討するとともに、障害者理解の促進を進めていく… 今、２３区の中での共同選考を昭和の時代からずっとしておりまして、障害者の雇用を進めているものです。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その中で今、やはりどうしても試験という問題があるからそうなってくるのかどうか、試験制度の問題をどう考えているのかお聞きしたいと考えています。それと、品川区でチャレンジした３年間を越えた後の就労先の確保についてのお考えについて、もう一度お答えをお願いしたいと思います。","respondent":"榎本総務部長","answer":"区も１事業所として民間事業所と同じような立場になりますので、そういったものをどのようにできるのかということをやりたいということが一つです。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"３点目、最後に広町地区のまちづくりについてお伺いしていきたいと考えています。特にＪＲ東日本の建築計画に関するスケジュールなども可能な範囲でお答えほしいと求めましたが、。","respondent":"末元都市整備推進担当部長","answer":"委員ご指摘のとおり土地区画整理事業による土地再編を行う予定でございまして、令和３年度内に都市計画手続きに着手していく予定です。都市計画手続きに必要な地元説明会の開催に加え、建築物の規模によっては環境アセスメントの調査計画書の縦覧や説明会の実施など。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ＪＲ東日本の問題もありますので、その辺は了解しますが、なるべく早く皆様に周知できるような形をとっていただきたいということを要望しておきます。これと広町地区の整備推進の関係、その推進とともに他の地区のまちづくりへの影響についてもお考えを説明を求めました。","respondent":"末元都市整備推進担当部長","answer":"区では、大井町駅周辺における今後のまちづくりの方向性をまとめた、委員ご指摘の大井町駅周辺地域まちづくり方針の策定作業に着手しています。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"意見","question":"最後に、広場にはバス停も作っていくということですが、その役割分担、大井町駅の東口、西口の関係についてお答えをお願いしたいと思いますとの意見を述べました。","respondent":"末元都市整備推進担当部長","answer":"現在バス路線が大井町駅に入っておりますが、具体的なバス事業者との調整については、今後事業の進捗に応じて協議を進めていく予定です。既存バスの乗り入れですとか、大崎駅からの長距離バス乗り場の可能性も含めて協議してまいります。","id":"exchange-025"},{"speaker":"せお委員","kind":"質問","question":"テーマは新型出生前診断における支援について、児童発達支援センターについて、就学相談について、３点を順次伺います。現在カウンセリングなどを実施していない営利目的のＮＩＰＴ無認可施設が約１３０カ所あると言われているという現状を伺いました。","respondent":"福内品川区保健所長","answer":"保健センターでは、子どもを安心して産み、育てるために、妊婦全員を対象として、妊娠期のネウボラ相談事業を実施しています。適切に専門機関へつなげております。","id":"exchange-026"},{"speaker":"せお委員","kind":"質問","question":"これらを知る機会は現在区で設けているでしょうか。ですから、妊娠中から子育てまで継続した支援が大切となってきますが、区ではどのように取組んでいくのか、見解を伺います。","respondent":"福内品川区保健所長","answer":"支援者として知っておくべき出生前診断の実際に関する研修を実施しておりまして、今後も様々な機会を活用し、スキルアップを図ってまいります。実際には妊娠期の精神面や産後の生活についての支援、連携して訪問看護など必要なサービスの導入調整等を行っております。","id":"exchange-027"},{"speaker":"せお委員","kind":"質問・要望","question":"ですので、現状を確認させていただきたく質問いたします。さらに、子ども発達相談室の５か月待ちを解消するために、新しく改善を図った点はありますか尋ねました。","respondent":"伊崎福祉部長","answer":"お待ちいただく際の対応として、電話で相談を受ける際にまず困っていることをお伺いし、ご自宅で対応できそうなことをアドバイスしております。困ったときにはいつでも電話で対応する旨をお伝えしております。","id":"exchange-028"},{"speaker":"せお委員","kind":"質問","question":"現在、基本的な通園の基準は何でしょうか。ふだんは幼稚園・保育園に通って、つまり並行通園が一般的であるべきですが、品川区の見解を説明を求めました。","respondent":"伊崎福祉部長","answer":"並行通園につきましては、幼稚園や保育園に通っている児童が品川児童学園を利用できるという形の並行通園においては、現在実施できておりません。","id":"exchange-029"},{"speaker":"せお委員","kind":"質問","question":"この一連の流れは果たして相談なのでしょうか。さらに、就学相談とはそもそも何をする場所かという説明は、いつどのように行っているのか尋ねました。","respondent":"齋藤教育次長","answer":"就学相談の説明につきましては、通級指導学級の利用や特別支援学級の在籍、または都立特別支援学校への入学を検討したいご家族に対して。都立特別支援学校の詳しい説明はしておりませんが、就学相談の機会にかかわらず、特別支援学校につないでいるところです。","id":"exchange-030"},{"speaker":"せお委員","kind":"質問","question":"就学先を決定する上での適切な情報提供やご案内はどのようにされていますでしょうか。お子さんの日常を見られる場所に専門家が訪れてご意見を頂くと、効果的な就学相談になるのではないかと思いますが、見解を説明を求めました。","respondent":"齋藤教育次長","answer":"ご提案の体験の時期につきましては、学校の受入れ態勢を確認し、体験授業の方法等について今後検討してまいります。今後、保育課等とも連携して、保護者からの了解を頂いた上で状況を把握し、就学相談がより効果的になるよう努めてまいります。","id":"exchange-031"},{"speaker":"せお委員","kind":"質問","question":"約３５％の方が「悩みや不安が全く解消されなかった」、約１５％の方が「悩みや不安について話をする機会がなかった」と答えています。どこで悩んでいるのか、どのような未来を望んでいるのかなどを丁寧に聞く機会をその都度設けることが必要かと思いますが、見解を説明を求めました。","respondent":"齋藤教育次長","answer":"相談の結果や理由を書面で連絡することはしておりませんでしたが、今後もお子さんやご家族に寄り添った対応の在り方について検討してまいります。","id":"exchange-032"},{"speaker":"せお委員","kind":"意見","question":"だから悩むのです。状況に寄り添い、子どもが幸せに過ごせる場所を一緒に考えていただけるような就学相談となり、そのような品川区となることを望みますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"渡部副委員長","kind":"質問","question":"初めに、本年実施の国勢調査について伺います。住基人口と国勢調査によって得た結果を比べての違いについても説明を求めました。","respondent":"久保田地域振興部長","answer":"１０月１日現在、ふだん住んでいる場所で調査を行うため、住民票の届出場所と実際に住んでいる場所が一致しない場合などがあるからです。例えばですが、進学のために上京した学生が、様々な事情により住民票を移していないといったことが考えられるところです。","id":"exchange-034"},{"speaker":"渡部副委員長","kind":"確認","question":"それ以外はどのような方々に調査員を依頼されたのでしょうか。調査開始時の実数としてはそれぞれどのような数字だったのか尋ねました。","respondent":"久保田地域振興部長","answer":"調査開始時の実数につきましては、公募が４２人となり、このほかに業務委託契約などが１８人いらっしゃいました。町会・自治会から推薦がなかった場合につきましては、調査に慣れている区登録調査員の受け持ち調査区を増やすなどして対応しています。","id":"exchange-035"},{"speaker":"渡部副委員長","kind":"質問","question":"前回調査と比較し大きく変わった点や、区として工夫を凝らした点は何かございましたでしょうか。新型コロナウイルス感染症対策で調査員の負担軽減策も大変重要であったと考えますが、どのような対策を取られましたでしょうか、説明を求めました。","respondent":"久保田地域振興部長","answer":"新型コロナウイルス感染症への対応も含めまして、それぞれのご家庭世帯と調査員とが直接対面しない非接触の調査方法を基本として行ったところです。調査員への説明会につきましても工夫をいたしました。","id":"exchange-036"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"調査票による回答数、インターネットによる回答数、未回答数はどのようになっておりますでしょうか。未回答者へのアプローチはどのようになさっているでしょうか、説明を求めました。","respondent":"久保田地域振興部長","answer":"回答がお済みでない方は調査票のご提出をお願いしますといったチラシを各調査区の全世帯に配布いたしまして、回答への協力をお願いしています。広報しながわ１０月２１日号や区ホームページにおいても、回答への協力をお願いしたところです。","id":"exchange-037"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"時代の流れでしょうか、インターネット回答というのも前回と比較して伸びているし、次回以降の調査ではさらなる伸びがあるのかと考えています。最後に、区としてこの国勢調査の大切さや重要な点について教えてほしいと求めました。","respondent":"久保田地域振興部長","answer":"国勢調査は、基幹統計調査の中でも最も重要な調査であると考えているところです。は今回の国勢調査を着実に実施するとともに、国勢調査を含めました各種統計調査を正確かつ確実に進めてまいりたいと考えているところです。","id":"exchange-038"},{"speaker":"渡部副委員長","kind":"質問","question":"１点目は、地方公共団体のデジタル化で示された、システム等の共同利用の推進の観点から伺います。ここで質問しますが、これらの説明は区でいつ頃国からどのように受けましたか尋ねました。","respondent":"堀越企画部長","answer":"国のほうで全体の目安として２０２５年度という形を掲げてありますので、既に内部の検討には着手している状況です。報道発表資料等によりますと、業務集中ですとか、これも併せて情報収集をしてしっかりと対応していきたいと思ってあります。","id":"exchange-039"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"２つ目は、行政手続のオンライン化の推進について伺います。区からは、４０万人の人口に見合った台数の登録機を区として設置するよう強く要望いたします。","respondent":"堀越企画部長","answer":"次に、コンビニ交付は住民票等を平成２８年度から開始していますが、当時戸籍システムのリプレイスが近い将来で予定されておりまして。来年の１月より、コンビニ等で設置されたマルチコピー機において戸籍証明書の取得が可能になるような形で、鋭意準備を進めているところです。","id":"exchange-040"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"それで仕事をお休みされた場合はどのような扱いになっていたのでしょうか。区役所は急激に業務負担が発生した際の応援体制が組まれているかと思いますが、どのような対応がされましたでしょうか、説明を求めました。","respondent":"榎本総務部長","answer":"一番多かったのは４月です。その場合の応援態勢ですけれども、そういったところで施設を閉じたりとか、そういうところから適宜応援を求めるという形で対応したところです。","id":"exchange-041"},{"speaker":"渡部副委員長","kind":"提案","question":"２つ提案します。この２つを提案しますが、お考えをお聞きするとともに、説明を求めました。","respondent":"久保田地域振興部長","answer":"これらのＰＲをもっと積極的に打っていかなければいけないと考えてございまして、こうした取組みを進めまして利用を促していきたいと考えています。ＬＩＮＥによる事前入力、自動発行機なども取入れまして、これらの混雑解消への取組みを進めてまいりたいと考えております。","id":"exchange-042"},{"speaker":"渡部副委員長","kind":"質問","question":"その結果、一人で抱え込んでしまう方もいらっしゃるのではないでしょうか。ここで乳幼児家庭に対する現在の児童センターの利用状況を伺います。","respondent":"柏原子ども未来部長","answer":"昨年９月が２万２,０００人、９月ひと月で利用されていますので、大体今は半数近くぐらいまで来ているといった状況です。そういった制限をかけさせていただいてありますので、その利用については、通常の利用よりかなり少ない状況です。","id":"exchange-043"},{"speaker":"渡部副委員長","kind":"質問","question":"感染症対策を何とか講じた上で、多くの家庭や児童・生徒が気軽に訪れて活動ができるよう、何か新たなお考え等はないでしょうか。私自身は、広げていくなどの必要があるかと考えるのですが、その辺のお考えを説明を求めました。","respondent":"柏原子ども未来部長","answer":"そういった中で、今ご指摘がございました外での活動というのは考え方としてひとつあると考えてございまして、今検討しているといった状況です。","id":"exchange-044"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"今、子育てサークルというようなことでございましたが、このようなボランティア団体の方々についての支援を伺います。子育て支援において、団体とボランティアセンターとの連携事例やその効果などがもしあるようでしたら、説明を求めました。","respondent":"柏原子ども未来部長","answer":"食材の仕分け、ボランティアセンターが間に入っていることによって、こういったマッチングもやっていただいているというところがあります。","id":"exchange-045"},{"speaker":"渡部副委員長","kind":"提案","question":"ここからちょっと提案といいますか要望の形になるのですけれども、在宅子育て支援もそうですが、進めていただきたいと望みます。今後区として社会福祉協議会とともにやっていただきたいと、ここは最後、要望で終わりますとの意見を述べました。","respondent":"齋藤教育次長","answer":"学校休校中の特徴的なことのお尋ねですが、１つ目は、区では入学式、始業式をソーシャルディスタンスを確保しながら実施したことです。今後はこうした取組みを各学校に紹介し、再び学校が休校となった場合でも、授業と同様の教育効果が得られるよう、準備を進めてまいります。","id":"exchange-046"},{"speaker":"渡部副委員長","kind":"確認","question":"各家庭での取組みに学校が介入することはなかなかできませんが、実際の状況はいかがだったのでしょうか。学校再開後、学力低下が確認できた児童・生徒に対しては、何かしらのアクションが学校でなされていたのかどうか、教えていただけますか。","respondent":"齋藤教育次長","answer":"保護者が日中お仕事をされている、保護者が仕事でパソコンを使用するため、オンライン学習に参加できないといった課題が見られました。放課後で個別に指導したり、品川地域未来塾で学習支援をするなど、きめ細かく対応したところです。","id":"exchange-047"},{"speaker":"渡部副委員長","kind":"質問","question":"今後ガイドライン等を作成して運用につかれると思いますが、幾つか伺います。この間のＩＣＴの推進校での取組みを全校で継続すべきと考えますが、教育委員会としてのお考えを説明を求めました。","respondent":"齋藤教育次長","answer":"ルール、トラブル対応のマニュアルを提供するほか、連絡帳機能やＰＴＡ活動でご利用いただけるよう丁寧に説明いたします。あるいはリモートでＰＴＡ活動を行うなどＰＴＡとの連携を深め、さらなる活用を図ってまいります。","id":"exchange-048"},{"speaker":"新妻委員","kind":"質問","question":"大きく防災とワンストップ窓口について伺います。初めに、風水害と地震がコロナ禍で発生した場合の避難について伺います。","respondent":"滝澤災害対策担当部長","answer":"避難施設などの違いについて、災害に伴い開設される避難施設などを時系列に説明いたします。昨年度の防災会議において、区ホームページや広報しながわなどを活用して、避難要領に係る周知・啓発を実施してまいりました。","id":"exchange-049"},{"speaker":"新妻委員","kind":"質問・要望","question":"ただいま３つの避難所があるということのご説明がありました。避難所とは何かを分かりやすく掲載した冊子やリーフレットなどを作成し、配布することを要望いたしますが、見解を伺います。","respondent":"滝澤災害対策担当部長","answer":"避難施設の設置をしておりましたが、できる限り簡明で区民目線で分かりやすい避難要領、避難施設の設置はいかにあるべきかについて検討しております。検討内容が整い次第、変更を伴う際は、冊子の作成を含めてあらゆる手段を講じて区民に対し周知徹底を図ってまいります。","id":"exchange-050"},{"speaker":"新妻委員","kind":"提案","question":"先日の款別審査の土木費でも会派から確認いたしましたが、昨年は１８７万円、本年は４８０万円を予算化しています。公明党が平成３０年第３回定例会の一般質問で提案している、土砂災害を想定した避難訓練の実施を改めて提案いたしますが、それぞれ見解を伺いますとの意見を述べました。","respondent":"滝澤災害対策担当部長","answer":"風水害時の要支援者避難のための訓練は、共助、公助の観点から極めて重要でありますので、引き続き同種訓練の実施に努めてまいります。先ほど説明をしました区民目線で分かりやすい避難要領の研究と併せて、その実施要領を具体化してまいります。","id":"exchange-051"},{"speaker":"新妻委員","kind":"提案","question":"新たな生活様式の中でもマイ・タイムラインの周知啓発に努めていただきたいと要望します。見解を伺いますとの意見を述べました。","respondent":"滝澤災害対策担当部長","answer":"今年度、風水害対応における家庭・区民コースにおいて、マイ・タイムラインの作成を実施予定でありましたが。現在、風水害対応におけるマイ・タイムラインの作成要領についてもコンテンツに取上げることとしております。","id":"exchange-052"},{"speaker":"新妻委員","kind":"質問","question":"次に、避難所について伺います。ウィズコロナ時代の新たな避難所運営を行う地域の声をどう受止め、対応しているのか伺います。","respondent":"滝澤災害対策担当部長","answer":"次に、より多くの事項を避難所の運営者となる防災区民組織の方々に実施していただくことから、マニュアルに基づくゾーニングなどの具体的な実施要領。","id":"exchange-053"},{"speaker":"新妻委員","kind":"提案","question":"品川区においても、しながわ防災体験館で３密を避けるための避難所のイメージを展示するなどの検討をされてはいかがでしょうか。併せて見解を伺いますとの意見を述べました。","respondent":"滝澤災害対策担当部長","answer":"次に、新型コロナウイルス感染症に対応する避難所訓練を１２月の区内一斉防災訓練で区民避難所において実施する予定でありますので。次に、双方向の情報発信やしながわ防災学校のオンライン講座の普及などについても実施してまいりたいと思います。","id":"exchange-054"},{"speaker":"新妻委員","kind":"意見","question":"東京都も本年６月にコロナ禍での複合災害を見越して、全日本シティホテル連盟関東支部などと協定を締結しています。品川区はホテルを避難所として利用する際、どのような場合を想定しているのかお知らせくださいとの意見を述べました。","respondent":"滝澤災害対策担当部長","answer":"区が具体的な宿泊や食事支援の協定を締結する一方、都は利用可能なホテル情報の提供や利用のための相互調整支援を実施するものであります。次に、コロナ禍において避難施設が不足し補完的に避難施設が必要な場合に協定を活用するものと考えております。","id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"ここ数年のそれぞれの利用実績をお知らせいただき、それぞれの利用状況の課題をどう捉えているのか伺います。家具転倒防止器具取付助成の対象者拡充や、希望する方へ食器類の飛び出しを防止する器具などの無償提供を求めますが、いかがか尋ねました。","respondent":"中村都市環境部長、伊崎福祉部長、滝澤災害対策担当部長","answer":"一層のＰＲが課題であると認識しています。しながわパパママ応援アプリ、子育て世帯に対するＰＲ、こういったものなどでさらに周知を広げられるよう考えて… 障害者世帯などに準ずる世帯に対して行っている支援でございまして、平成３０年度は５４件、平成２９年度は３０件となっております。… 私からは、家具転倒防止器具の無償提供についてご説明いたします。","id":"exchange-056"},{"speaker":"新妻委員","kind":"質問","question":"款別審査でも伺いましたが、証明交付窓口のリニューアルをした目的と評価、そして課題をお知らせください。このことによって区民の利便性の向上と負担軽減がどのようにされるのか伺います。","respondent":"久保田地域振興部長","answer":"課題としましては、知られていないということがありまして、利用頻度が１日に数件程度ということで、さらなる周知が必要であると考えています。区役所で署名のみお書きいただければ申請が完了するということで、窓口での滞在時間が短くなるということがあります。","id":"exchange-057"},{"speaker":"新妻委員","kind":"意見","question":"ＬＩＮＥのサービスがこれから始まると思います。周知も課題ですが、このＬＩＮＥの事業が始まるにあたっての周知、何かお考えがありましたらお知らせくださいとの意見を述べました。","respondent":"久保田地域振興部長","answer":"このＬＩＮＥアプリを使ったサービスの周知ですけれども、ＬＩＮＥ公式アカウントにメニューボタンを新設するということが挙げられます。","id":"exchange-058"},{"speaker":"新妻委員","kind":"提案","question":"平成２９年予算特別委員会の総括質疑で、品川区でも導入をと提案した経緯がありますが、書かない窓口の設置を要望いたします。それぞれ見解を伺いますとの意見を述べました。","respondent":"堀越企画部長","answer":"現庁舎における書かない窓口の設置等についてですが、品川区への転入に伴う、窓口ではなく郵送でも対応を可能にすることを検討しています。今後、現庁舎で対応できる部分というような形にはなりますけれども、具体的な方法について様々検討していきたいと考えているところです。","id":"exchange-059"},{"speaker":"新妻委員","kind":"質問・要望","question":"現庁舎での行政サービスの向上をもう一歩要望いたしまして、私の総括質疑を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"塚本委員","kind":"質問","question":"９月２４日に成立した補正予算で、区内の高齢者、障害者の入所・通所施設従事者を対象としたＰＣＲ検査を実施することになりました。加えて、感染拡大を最小化するために、それぞれの検査をどのような方針で実施することが効果的であると考えているか伺います。","respondent":"福内品川区保健所長","answer":"感染の可能性がある対象者に行政検査を迅速に実施するとともに、積極的に検査を実施することで重症化を防ぐといったことが重要と考えております。スクリーニング検査につきましても、地域や施設の感染状況も踏まえ実施することが効果的と考えております。","id":"exchange-061"},{"speaker":"塚本委員","kind":"質問・要望","question":"東京都への要請や各種医療機関への働きかけなど、あらゆる手を尽くして医師免許を持つ職員を確保するよう求めます。区の見解を伺います。","respondent":"福内品川区保健所長、榎本総務部長","answer":"検査体制ですが、通常、保健所の医師１名、保健師１名、事務職１名の計３名で、施設に出向くなどして実施しています。保健所の所長以外の医師は保健予防課長１名のため、管理職業務等の合間や休日に対応しており… 品川区における医師不足につきましては、十分認識しており、これまでも東京都へ要望してきたところです。今回、新型コロナウイルス感染症への対応にあたり、その必要性をこれまで以上に認識したところであります。","id":"exchange-062"},{"speaker":"塚本委員","kind":"質問・要望","question":"１２番目ですか、しっかりとした体制は何よりも求められるというふうに思いますので、よろしくお願いしたいと思います。認知症施策の中の重要なものの１つとして、早期に発見することがあると考えますが、区の見解を伺います。","respondent":"伊崎福祉部長","answer":"高齢者人口が増えるとともに、認知症高齢者の増加が見込まれており、認知症対策はますます重要な課題と考えております。さらに、家族、地域へのフォロー体制としましては、認知症カフェをご案内するなど、適切な対応に努めてまいります。","id":"exchange-063"},{"speaker":"塚本委員","kind":"意見","question":"地域密着型サービス施設等整備費助成は１億４,４７９万円余の決算となっていて、着実に整備を進めていると、このように認識しております。認知症に関わる施設整備の今後の見通しについてと、希望しても施設入所がかなわない方についての対応をどのように考えているのか説明を求めました。","respondent":"伊崎福祉部長","answer":"区立の指定管理施設としても予定しておりまして、小山台住宅跡地に地域密着型施設の整備を検討しています。認知症デイサービスなどをご利用いただくなど、認知症になっても在宅生活を継続できるよう、サービスの提供に努めてまいります。","id":"exchange-064"},{"speaker":"塚本委員","kind":"提案","question":"今後、認知症にまつわる様々な問題が顕在化するであろうと予測しますが、区の認知症に対する問題意識について伺います。そして支える家族同士の情報交換や悩みを共有するコミュニティの構築、こういったことを提案いたしますが、区の見解を伺いますとの意見を述べました。","respondent":"伊崎福祉部長","answer":"複雑化、在宅介護支援センターや支え愛・ほっとステーションなど、重層的な支援体制整備に向けて総合的な相談窓口機能の検討を進めてまいります。このような試みを参考といたしまして、今後、様々な活用を検討していきたいと考えております。","id":"exchange-065"},{"speaker":"塚本委員","kind":"質問・要望","question":"新型コロナウイルス感染症を想定した新しい生活様式が求められる中、日本社会のデジタル化の後れが顕在化しました。区は、ポストコロナを見据えた商店街のにぎわい創出や運営効率化について、デジタル活用による施策をどのように展開するのか見解を伺います。","respondent":"久保田地域振興部長","answer":"そのほかにも商店街エリアサポーターと連携いたしまして、ＩＴ活用に向けたアドバイスなどを実施しているところであります。ＩＴツールの試験導入や、また五反田バレーとの連携も進めまして、様々な支援を進めていく必要があると考えているところであります。","id":"exchange-066"},{"speaker":"塚本委員","kind":"質問・要望","question":"区は、ＩＣＴ推進教員が学校内で指導的役割を担うために十分なスキルを身につけられるよう、教育委員会がしっかりと支援することを求めます。区の見解を伺います。","respondent":"齋藤教育次長","answer":"ＩＣＴ推進教員への支援についてのお尋ねですが、各学校では、ＩＣＴ推進教員と学年主任を中心に活用検討組織を立ち上げ。教育委員会では、ＩＣＴ推進教員に向けた研修として、ＩＣＴ推進教員が自分の学校の教員へ伝達できるよう丁寧に計画的に進めてまいります。","id":"exchange-067"},{"speaker":"塚本委員","kind":"質問・要望","question":"区は、医療のオンライン化についてどのように考えているのか、見解を伺います。さらに、医療のオンライン化について、区内の医療機関から要望などがあった場合、区として支援の考えがあるか伺います。","respondent":"福内健康推進部長","answer":"初回診療時からのオンライン診療の恒久化について検討が進められており、医師と患者の面識があることを前提にすべきとの考えが示されております。","id":"exchange-068"},{"speaker":"塚本委員","kind":"質問・要望","question":"今後、行政機関の個人認証システムは、マイナンバーカードに集約するべきと考えますが、区の認識を伺います。区として今後の行政サービスのデジタル化に伴い、マイナンバーカードと東京電子自治体共同運営サービスをどのように整理していくのか伺います。","respondent":"堀越企画部長","answer":"個人認証の関係等ですけれども、区も行政手続のオンライン化は積極的に進めていきたいというふうに考えているところです。マイナンバーカードを活用した公的個人認証の利便性、安全性を活かして、しっかりとこれを活用しきたいというふうに思っているところです。","id":"exchange-069"},{"speaker":"塚本委員","kind":"質問・要望","question":"情報弱者の立場に合わせたインターネット環境の提供など、思い切った施策を検討していただきたいのですが、区の見解を伺います。区の見解を伺います。","respondent":"堀越企画部長","answer":"区の全世帯数の８割の状況ですが、いわゆるモデムの設置が必要になってきますので、なかなか難しいというような課題があると考えています。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問","question":"コロナ禍を乗り越えた先に品川区が先進的なオンライン・シティとなることを願い、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"おくの委員","kind":"質問","question":"これもいかがでしょうか。伺います。","respondent":"中村都市環境部長","answer":"現在までに電話やメールなど様々な方法で区民の皆様から影響についてご意見をいただいておりまして、これも国に伝えているところです。引き続き、区としまして、区民の皆さんの意見をしっかりと聞き、区民の立場に立って国に対し必要な対応を求めてまいるという考えです。","id":"exchange-072"},{"speaker":"おくの委員","kind":"質問・要望","question":"出すべきではないでしょうか。伺います。","respondent":"中村都市環境部長","answer":"ただ、Ｌｄｅｎにつきましても、今後、年間Ｌｄｅｎについて公表を予定しております。当然のことながら、国に対しても遵守を求めてまいります。","id":"exchange-073"},{"speaker":"おくの委員","kind":"質問・要望","question":"区も区民も全く知らされてこなかった重大な事実が新たに判明したわけですから、国に即刻運用中止と、いかがでしょうか。伺います。","respondent":"中村都市環境部長","answer":"自衛隊輸送機が飛行したですけれども、新飛行ルートの事前の説明では、飛ぶとも飛ばないとも説明はなかったという認識です。国防に関する任務の遂行の是非を区で判断することはできませんので、可能な限りの情報提供をもらうということを国に申し入れていくという考えです。","id":"exchange-074"},{"speaker":"おくの委員","kind":"質問","question":"民間機と自衛隊機は全く違うものを運びますし、違う飛行機が飛ぶわけです。全く新しい事態が展開した以上、新しい事態の展開として少なくとも説明の場は設けさせるべきだと考えますけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"おくの委員","kind":"質問・要望","question":"３番目、やはり中止またはルートの変更を国に求めるべきだと思うのですが、いかがでしょうか。以上３点、伺います。","respondent":"中村都市環境部長","answer":"そういった検討途中における国の発言に対して、区の考えを述べることは差し控えるべきと考えております。ただ、この国が行う検討については、区としてぶれずに結果を注視していきたいというふうに考えております。","id":"exchange-076"},{"speaker":"おくの委員","kind":"質問・要望","question":"それからもう１つ、最後に伺います。伺います。","respondent":"中村都市環境部長","answer":"品川区内におきましては、区の要望に対しまして、区内全域を対象として、合わせて１３回の教室型説明会が開催されております。自治法上も認められた権利ですので、区としましても法令に基づき厳正に対応してまいりたいと考えております。","id":"exchange-077"},{"speaker":"おくの委員","kind":"質問・要望","question":"区民がこのような被害を受けるいわれは全くありません。新ルートの中止、撤回、強く求めて私の総括質疑を終えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"感染拡大を抑えるためのＰＣＲ等検査の抜本拡充と、深刻な経済危機から区民の暮らしを守る対策を求めて質問します。なぜ２０代、３０代に多いのかなど、明らかになっていることは何か説明を求めました。","respondent":"福内品川区保健所長","answer":"なぜ２０代、３０代に多いかということにつきましては、やはり活動が活発というようなことが挙げられます。学校などでマスクなしで接触をされている、また、それらの方からの家庭内感染が多く見られております。","id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さらに、９月１５日、厚生労働省からインフルエンザの流行に備え、検査体制の拡充に向けた指針が出され、検査体制の点検と強化が求められています。１日何件まで引き上げる計画か、そのための体制整備をどうつくっていくのか、相談体制はどう拡充するのか伺います。","respondent":"福内品川区保健所長","answer":"今後も増加の見込みがありますので、先ほど申し上げました１日で３２６件程度の検査は可能ではないかというふうに考えてあります。今後、現在のところは東京都が一括して対応して発熱患者を診ていただける医療機関を案内するというような役割分担が示されておりまして。","id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いかがでしょうか。新型コロナウイルス感染症地方創生臨時交付金は、品川区に幾ら出されているのか、どう活用されているのか、今述べた対策に活用できるのか伺います。","respondent":"品川財政課長、伊崎福祉部長、福内品川区保健所長","answer":"現在、品川区に対しての地方創生臨時交付金の交付金額の合計は１４億円余となっています。なお、地方創生臨時交付金の対象におおむねなるというふうには考… 委員ご指摘の介護サービス事業者等のＰＣＲ検査の実施に向けて、今、安心して介護サービスをご利用いただけるように努めてまいります。… 高齢者施設や医療機関で感染者が複数発生するなどした場合は、現在でも対象を広げ、感染状況により複数回検査を実施しております。","id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１か月前に出ているものに対して、１か月間、このことに対して検討してこなかったのでしょうか。大変意味のあることだと思いますが、区は、この高齢者と基礎疾患のある人への検査に対して、必要な検査とは考えないのか伺います。","respondent":"福内品川区保健所長","answer":"高齢者や基礎疾患を持っている方は重症化のリスクがあるということは、そのとおりです。検査を実施するにあたっては、やはり効果的に実施する、感染の疑いがある方たちからきちんと検査を行い。","id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、この６５歳以上の高齢者と、基礎疾患を有する者に国庫補助を行うと、ここまで出しているわけですから、この検査をやっていただきたい。これを検討しなかったのか、そしてこれを必要だと思わないのかを伺ったので、そのことについて答弁をお願いします。","respondent":"福内品川区保健所長","answer":"当然これは国が支援するというふうになってありますけれども、また感染者がどのようなところから出ているのか等々、非常に差があります。は家族の中で、先ほどのご質問の検査につきましては、現時点では実施をする考えはございません。","id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もともと保健師は、人口対比の定数が２３区で最低の人数であり、共産党は定員増を求め続けてきました。区として保健師の正規職員の大幅増員を求めますが、いかがか尋ねました。","respondent":"榎本総務部長","answer":"９月に全職員に実施しておりまして、検診機関のほうで集計をしているところで、１１月には各個人に報告書を通知する予定です。今後も採用に努めてまいります。","id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"さらに区独自の収入が５割減、また３割減が３か月という厳しい要件を緩和することを求めますが、いかがでしょうか。１回限りの給付ではなく、持続的支援を国に求めていただきたいが、いかがか尋ねました。","respondent":"榎本総務部長、久保田地域振興部長","answer":"そのほかいろいろな業務量を考えて、この間、増員をしてきているところです。今後も適正な仕事の執行ができるように人員をきちんと配分しながら仕事を進めていきたいと考えています。融資あっ旋をはじめとした資金繰り支援、また家賃支援給付金、多面的な支援を積極的に実施していきたいと考えております。","id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"港区のように、品川区でも大学生、専門学生に対する給付型奨学金制度の創設を改めて求めます。いかがか尋ねました。","respondent":"伊崎福祉部長、柏原子ども未来部長","answer":"緊急小口資金・総合支援資金につきましては、総合支援資金は２,４５６件、総合支援資金の延長が５６３件と聞いております。住宅確保給付金および緊急小口資金・総合支援資金の期間の延長につきましては… 品川区におきましては、平成３０年度から高校生のための奨学金返還免除制度を導入して行ってきているといった状況があります。","id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ＰＣＲ検査、医療体制の拡充、暮らし、営業を守る支援の取組みを求めます。８００億円もの税金を投入する巨大道路づくり、コロナ禍から区民の命と暮らしを守るために充てるよう求め、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"須貝委員","kind":"質問","question":"１つ目、区内の中小・零細企業の経営の現状をどのように把握していますか。そして、倒産、廃業、休業、解散などをした企業数を把握していたら説明を求めました。","respondent":"久保田地域振興部長","answer":"区内中小企業の現状ですけれども、このコロナ禍の中で経営は大変厳しい状況になっているというふうに私どもも認識しています。倒産につきましては、８月末までで２５件というふうに報告を受けているところです。","id":"exchange-088"},{"speaker":"須貝委員","kind":"質問","question":"ならば、区内産業の経営状況を、調査、把握するべきだと思いますが、再度教えてください。もう一度ご見解を説明を求めました。","respondent":"久保田地域振興部長","answer":"廃業につきましての数値ですけれども、品川区ということではございませんが、全国の場合ですと、昨年が約４万件ほど、それに対して今年は、たしか５万件を超えて６万件近くいくのではないかという見込みが出ているということは把握しています。","id":"exchange-089"},{"speaker":"須貝委員","kind":"質問","question":"そして、何か対策をお考えですか。そして失業者が増え、貧困層が増えると思いますが、説明を求めました。","respondent":"久保田地域振興部長","answer":"企業の支援ですけれども、やはり私どもとしましては、こうしたことによりまして経営活動の継続をしていければというふうに考えているところです。社労士等を活用した相談窓口の設置、また、そういった企業や雇用を維持できるような形の支援も継続的に進めているところです。","id":"exchange-090"},{"speaker":"須貝委員","kind":"質問","question":"今、相談ではないのではないですか。商品やサービスに対して、２割引券などの発行をして消費の底上げを図るべきではないかと思うのですが、その辺についても、答えるよう求めました。","respondent":"久保田地域振興部長","answer":"長期的に企業の経済的な活動を継続的にやっていくという上では大事なことですので、短期的な支援、また長期的な支援といったことも踏まえながら。屋形船等の支援に加えて、状況等を見ながら、必要に応じて他の業種等につきましても検討を進めていきたいと考えております。","id":"exchange-091"},{"speaker":"須貝委員","kind":"提案","question":"第二には、今もう難しいなら転業を考えられたらどうですかとか、そういうことも１つの提案だと思います。そして、今後、区はどのような対応をお考えなのか説明を求めました。","respondent":"品川財政課長","answer":"国や都の補助金等も、やはり動向をしっかりと見ていかなければいけないというふうに考えております。既存事業の見直しも進めまして、必要な事業をしっかりと進めていきまして、計画的で健全な財政運営を行ってまいりたいと考えております。","id":"exchange-092"},{"speaker":"須貝委員","kind":"質問・要望","question":"今では約２４億円の税収減で、渋谷区のように返礼品競争を本格的にやるべきではないかと思います。今後、渋谷区では、現在の状況にも対応できる返礼品の拡充、拡大を図っていくというふうにありますが、これについて品川区の見解を説明を求めました。","respondent":"藤田防災まちづくり部長、榎本総務部長","answer":"昭和５０年代に埋立て等がかなり進んでいく中で、昭和６０年代に入りまして、議会からの提案により水族館としての計画の検討が進んできたものです。今後も引き続き、効率的、効果的な運営は必要かと思いますが… その中で品川区は、平成２７年度から返礼品を考えてふるさと納税に着手してまいりました。そういった意味で、今回も新型コロナウイルス感染症に対する寄附ということで、返礼品はなく、そういう寄附を求めてきた経過があります。","id":"exchange-093"},{"speaker":"須貝委員","kind":"質問","question":"でも、今はそれは終わったのではないですか。現に来場者が少しずつ減っているならば、もう転換する時期だと思いますが、もう一度ご見解を説明を求めました。","respondent":"榎本総務部長、藤田防災まちづくり部長","answer":"税を多く納めている方に対しての控除が大きくなるという仕組みですので、税を納めていない方に関しては控除を受けられないという形です。その部分の区の税金が外へ流れるという、そういう仕組みになっていますので… 現在、私どもも顧客満足度満点プロジェクトということで、来てもらえるお客様にぜひとも満足をしていただけるような仕組みも改めて検討しています。","id":"exchange-094"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから、高齢者には社会活動に参加していただき、心身ともに元気な生活を続けていただきたいものと思いますが、ご見解を教えてください。カラオケやマージャンなどの教室や様々なサークルなどがありますが、感染対策を工夫した上で、使用制限を解除したらどうか尋ねました。","respondent":"伊崎福祉部長","answer":"現在のところは、３密回避、あるいは飛沫の感染予防というところから考えまして再開できておりません。しかしながら、そういったものを参考にしながら、区の中でどうやって活かしていったらいいのか検討してまいりたいと思います。","id":"exchange-095"},{"speaker":"須貝委員","kind":"質問・要望","question":"混乱時ですが対応できるのですか。狭いところに大勢入るわけですから、二次感染、三次感染を防ぐことは可能なのか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"我々が一番懸念しておりますのは、一般の避難者エリアで新型コロナウイルス感染症が発生することが一番対応が困難だというふうに考えております。","id":"exchange-096"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回、避難計画の見直しと避難所の見直しをしていただきたいと思うのですが、そこら辺はご検討しているのでしょうか。お知らせください。","respondent":"滝澤災害対策担当部長","answer":"現在、新型コロナウイルス感染症に伴いまして、避難所のマニュアルの改定を行いながら、いかに避難所の運営を支援するかについては検討しております。最終的に、新型コロナウイルス感染症に伴う災害対策計画の修正についてまでは検討している範囲ではございません。","id":"exchange-097"},{"speaker":"須貝委員","kind":"質問","question":"そして、今ご答弁がありましたが、学校は感染拡大を防止するより、風評被害を優先するということですか。説明を求めました。","respondent":"齋藤教育次長","answer":"保健予防課長に先頭に立っていただき、日曜や平日、夜間にも最も精度の高いＰＣＲ検査を実施していただきました。保健所と連携を図って情報発信を図る考えでございまして、外部にいたずらに情報提供を隠す、こういったことではございません。","id":"exchange-098"},{"speaker":"須貝委員","kind":"質問","question":"校庭を使用している、校庭内で練習等を見学することを禁止されている学校がありますが、感染リスクが少ない校庭での見学はなぜ駄目なのですか。見学を了承している学校もありますが、なぜ対応が分かれているのか尋ねました。","respondent":"齋藤教育次長","answer":"こういった疫学的判断は保健所の知見によることが重要であると考えておりますので、保健所と連携を図りつつ情報提供を図ってまいります。学校の校庭での見学について、今のお話は詳細を承知しておりませんので、学校が必要に応じて判断しているものと考えております。","id":"exchange-099"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり教育委員会として、学校を束ねている、指導しているのですから、私はやはり１つの指針が必要だと思います。教室とか体育館、校舎内は分かりますが、やはりその辺はしっかりとしたご見解をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"吉田委員","kind":"質問","question":"この編集の所管は障害者福祉課になっているので、改訂の都度、障害者福祉課から発信、配付がされていると考えてよろしいでしょうか。活用の方法を徹底しているのか、研修などもあったほうがいいと思うのですけれども、その辺の活用について伺います。","respondent":"伊崎福祉部長","answer":"全職員を対象として、各自が障害者差別解消法の再認識と、自分の仕事での日頃の取組みを振り返ることができるよう、意識調査も行っています。","id":"exchange-101"},{"speaker":"吉田委員","kind":"確認","question":"款別審査のときには、たしか５０台用意されていると伺いましたが、貸出システムについて伺います。窓口でタブレットが使えることの表示、案内はどのようにあるのか、それぞれの所管について伺います。","respondent":"伊崎福祉部長、堀越企画部長","answer":"全庁的な障害者差別解消推進本部会議をもって全庁に共有して、それぞれの部署がそれぞれの事業の内容に応じて合理的配慮を行っているところです。常に障害者福祉課として見直しを行っておりますので… 総合窓口のほうでもタブレットの貸出対応を行ってありますので、それについての区民からのお問合せについては対応できているところでございまして。","id":"exchange-102"},{"speaker":"吉田委員","kind":"質問・要望","question":"必要ないと判断したように読み取れてしまうのですが、見解を伺います。この点について見解を伺います。","respondent":"伊崎福祉部長、堀越企画部長","answer":"その事業を行うにあたり、その意思が過重でない場合において対応するものとされており、ハンドブックにもその内容に沿って記載をしております。しかしながら、個々の内容によりましては、一律的な対応が難しいというところもあります。今、税務課等の窓口職場などを含めて合計５０台でございまして、貸出用で総合窓口と情報推進課に複数台持っているという意味で答弁を申し上げました。","id":"exchange-103"},{"speaker":"吉田委員","kind":"質問・要望","question":"これらの配慮も今後実施してほしいと思いますが、見解を伺います。事前広報への明記も同様に考えますが、見解を伺います。","respondent":"伊崎福祉部長","answer":"そういった方たちのお声をいただきまして、合理的配慮につなげていきたいと考えます。合理的配慮の考え方として、お申し出いただくということができるように、そのご案内はしていきたいと考えております。","id":"exchange-104"},{"speaker":"吉田委員","kind":"質問・要望","question":"あらかじめ想定しておきたいと考えるのは当然ではないでしょうか。障害者福祉課だけの判断では難しいと考えますが、しかるべき担当部署としてお答えほしいと求めました。","respondent":"伊崎福祉部長、福内品川区保健所長","answer":"検査につきましては……。〔「検査で陽性になったとき」と呼ぶ者あり〕 失礼しました。障害のある方それぞれの特性がありますので、その特性に応じて通常の疫学上必要な隔離をしていく必要があるとは考えております。委員お話のとおり、陽性者の場合は、医療が必要な方については病院に入院していただく。","id":"exchange-105"},{"speaker":"吉田委員","kind":"質問・要望","question":"国はどう回答しているのか伺います。国が動くまで区民を守る立場から区が実施すべきと考えますが、見解を伺います。","respondent":"中村都市環境部長","answer":"区としましても、まずはこうした事象について国への連絡等をして伝え、適切な対応が行われるよう求めてまいりたいというふうに考えております。","id":"exchange-106"},{"speaker":"吉田委員","kind":"質問・要望","question":"被害が出なくても落下物があったと認定されたら、事業者は何らかの責任をとるべきと考えますが、見解を伺います。落下物の目撃情報があったときは、少なくとも国としてきちんと調査はされるべきと考えますが、区としての見解を伺います。","respondent":"中村都市環境部長","answer":"緊急対応が終了した後、事後の措置として、国により適切に行われるというふうに区としても考えているところです。これらの説明がきっちりと行われるように、区民の側から国に求めてまいる、そういった考えです。","id":"exchange-107"},{"speaker":"吉田委員","kind":"質問・要望","question":"この点も区として国に求めるべきと考えます。そのようなプレッシャーをかけるようなことはないと信じておりますので、区民の立場に立って国に求めていただきたいと考えますが、見解を伺います。","respondent":"中村都市環境部長","answer":"万が一、落下物が発生した場合の調査、これは公平な立場から厳正に行われるべきと、区としてもそのように考えております。こうした役割を担う国土交通省が厳正に行うべきと考えておりますので、それをしっかりと注視して、適切な措置が行われるように求めてまいります。","id":"exchange-108"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ公正に行ってほしいと求めました。ぜひ区民の立場に立っていただきたいと主張して、私の総括質疑を終了します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"コロナ禍の中ではありますが、引き続き、区民の福祉・生活の維持向上に努められることを要望いたします。令和３年度の品川区予算・事務事業に反映され、実現していただくことをお願いし、品川区議会自民党の意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"大沢委員","kind":"提案","question":"経常収支比率は７５.７％、人件費比率は１３.６％であり、引き続き健全財政が維持された区政運営が行われている、以上の状況を確認いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"若林委員","kind":"提案","question":"区民サービスにおいては、公明党の提案を含めた取組みを積極的に展開しました。提案など、これまでの緊急要望や予算要望を十分に検討され、今後の区政運営および来年度予算へ反映されるよう求めますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"},{"speaker":"安藤委員","kind":"提案","question":"その実現へ加配教員の活用や、教室、学校増設などを進め、１日も早い実現を求めます。区民の声を真摯に受止め、国に新ルートの中止と変更を求めるべきですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"},{"speaker":"須貝委員","kind":"質問・要望","question":"そして、羽田飛行ルートの固定化を避けるために、これからも国に働きかけていただきたい。以上が、品川改革連合の令和元年度決算に対する意見表明です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"田中委員","kind":"提案","question":"園と区教委、学校との連携で、子どもたちがスムーズに学校生活を始められるよう求めます。各款別審査で指摘、提案させていただいた意見を予算編成に活かしていただくことを要望して、品川・生活者ネットワークの意見表明を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-115"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/964460?Template=document&Id=1496#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":108517,"voices":267}},{"id":"r02-20201021-10","meetingId":"r02-cm10","date":"2020年10月21日","dateIso":"2020-10-21","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"議会報告会等準備会議からの報告事項","agenda":"議会報告会等準備会議からの報告事項","exchanges":[{"speaker":"こんの委員","kind":"意見","question":"議会報告会等準備会議のメンバー１３名と中学１年生５クラスからの代表の生徒と６つのテーマに分かれ、それぞれ意見交換会を行います。５つ目に通学時の荷物の重さ解決、最後６つ目は、自己紹介についてというテーマですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"議長からの報告について","agenda":"議長からの報告について","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"そういったことはどういうふうにされたのかなというのと、そうした方々も含めて判断してもいいのではないかという件については、議長のご意見をとの意見を述べました。","respondent":"渡辺議長","answer":"昨年正副議長で対応して、質疑の時間から、経験をもとにまず適正な人数を想定しました。段階的に考えたときに人数的なものと、意見集約が現在のところしやすいベストな形として、議会運営委員会がふさわしいという判断をいたしました。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういったところを使いながら、場を活かしながら、丁寧な対応については今後議論をしていただければという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5380#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":8817,"voices":37}},{"id":"r02-20201109-6","meetingId":"r02-cm11","date":"2020年11月9日","dateIso":"2020-11-09","committee":"区民委員会","time":"午後 １時００分～午後 １時５３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"マイナンバーカード予約受付制の開始","agenda":"マイナンバーカード予約受付制の開始","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"予約制ということに関して、電話の予約も受け付けていただけるということで、電話を受ける体制というのはどうなっているのですか。３０分以上待ったらとか、そういうふうにならないでもらいたいという思いがあるのですけれども、電話受付の体制について教えていただけますか。","respondent":"木村戸籍住民課長","answer":"実際、もう人間対応です。その場でお伺いをして、その場で入れるというような形で、お待たせしないような形で対応するということで考えております。","id":"exchange-001"},{"speaker":"藤原委員","kind":"確認","question":"そうすると、コール、１０コールぐらいで必ず出るということの意味で、お待たせしませんよということですか。ですから、お待たせしないというのは１０コールぐらいで必ず出ますよということか、そこの確認。","respondent":"木村戸籍住民課長","answer":"今、状況としては、お待たせしてしまうというような形ですね。コールをずっと待っていただくという形ですけれども、今のご提案含めまして、考えていきたいと思います。","id":"exchange-002"},{"speaker":"くにば委員","kind":"質問","question":"１点伺いたいのが、これは当日の予約もできるのか尋ねました。","respondent":"木村戸籍住民課長","answer":"可能です。","id":"exchange-003"},{"speaker":"くにば委員","kind":"質問","question":"庁舎内でどういったところにこれを、マイナンバーカードの予約、ホームページと電話で受付開始しましたというのを掲示予定ですか。掲示予定の箇所。","respondent":"木村戸籍住民課長","answer":"現在に関しましては、今、本課と特設会場とあるので、そちらのほうでお知らせを、現地の掲示としてお知らせをするような形を考えておりますけれども、今、ご提案のあったモニターに関しても検討してまいりたいと思います。","id":"exchange-004"},{"speaker":"くにば委員","kind":"質問","question":"利用者の方の動線がどういったところで、予約をしようというモチベーションがあるかどうか、利用率も上がるのかなというふうに思っています。周知に関してもう１点なのですけれども、これは通常どおり、しなメールやツイッターでも告知するというふうに考えてよろしいのか尋ねました。","respondent":"木村戸籍住民課長","answer":"ＳＮＳを活用したような形も考えているところです。","id":"exchange-005"},{"speaker":"くにば委員","kind":"質問","question":"従来の方法、しなメールとかツイッターのほうが入っていないのかと思って、お伺いしました。今後、何かご報告の際には、ぜひその周知方法をもろもろ記載していただけるとありがたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"公益財団法人十四世六平太記念財団との連携に関する協定書調印式","agenda":"公益財団法人十四世六平太記念財団との連携に関する協定書調印式","exchanges":[{"speaker":"松本委員","kind":"意見","question":"私からなのですけれども、協力事項は書かれているのですが、今後、何がしか予算が必要になってくるものが出てくるのが、どの程度、出てくるとしたらどの程度の規模感を考えてらっしゃるのか、お願いいたしますとの意見を述べました。","respondent":"古巻文化観光課長","answer":"そういったものを予定をいたしておりますけれども、それから、品川区は本当に支援という意味で言うと広報の支援ぐらいですので。教育委員会のほうの事業でありますとか、今のところ、文化観光課といたしましてはその程度の内容で進めることを考えております。","id":"exchange-007"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"このチラシは、まず、品川区が作ったのでしょうか。そして、どこにどう配るのか尋ねました。","respondent":"古巻文化観光課長","answer":"実際の申込みの手順でありますとか、そういったところについては各業者さんにご案内いただくような、そのような流れになっております。そこが分かりづらかったと言えば分かりづらかったのかもしれませんが、状況としてはそのようなことでご理解いただければと思うのですけれども。","id":"exchange-008"},{"speaker":"藤原委員","kind":"確認","question":"必ず確認してくださいとか、そういうのを私は書くべきだと思って、行きやすくという思いがあるのですよね。と思うのですけれども、いかがか尋ねました。","respondent":"古巻文化観光課長","answer":"そうですね。このチラシについてはもう作ってあるものということで、ご了承いただいた上で、さらに分かりやすい周知を進めていきたいというふうに思います。","id":"exchange-009"},{"speaker":"くにば委員","kind":"質問・要望","question":"そもそもどういう料金体系のものなのかということが伝わるような形で告知をしていただきたいなというふうに思いましたというのが１点と、また。屋形船について、もう少し入っていたほうがいいかなと思うのですけれども、その辺についてご答弁をお願いします。","respondent":"古巻文化観光課長","answer":"作ったときの様々な検討の中での、今後また、周知する中でしっかり伝えられるようにしていきたいというふうに思います。それがなかなか、改めてしっかり受け止めて、今後周知をしっかりやっていきたいというふうに思います。","id":"exchange-010"},{"speaker":"くにば委員","kind":"質問・要望","question":"この１０の船宿のトータルの申込み数が１万人に達した時点で終了なのかと思っていましたが、この書き方を見ると、ちょっとこれは確認です。１社当たり１,０００人の枠で１０社みたいな感じなのか尋ねました。","respondent":"古巻文化観光課長","answer":"事業者との合意事項において、ひとまず１万人を１０社で均等に割って、１,０００人ずつという形の枠を設けているというふうに聞いております。","id":"exchange-011"},{"speaker":"くにば委員","kind":"提案","question":"これを、キャンペーンを適用しますということを、まず最初に言わないと教えてもらえないのですかね。今こういうキャンペーンをやっておりますので、このキャンペーンを適用しますかみたいな形で、船宿のほうから提案していただけるものか尋ねました。","respondent":"古巻文化観光課長","answer":"ご案内につきましては、各事業者の考え方と言いましょうか、スタイルでやっていただいているというのが実情です。１,０００人ずつの方に関しましてはキャンペーン対象ということになりますので、一定、そのような状況だというふうに認識をしております。","id":"exchange-012"},{"speaker":"くにば委員","kind":"質問","question":"その点を私が伺った一番の大きな理由というのが、これは、船宿にとって積極的にやりたいキャンペーンなのかどうかというのが１つあるのですね。これ、同じく半額補助という形で、残りの半額は、区はいつ、それぞれの事業者さんにお支払いする予定か尋ねました。","respondent":"古巻文化観光課長","answer":"毎月月末締めでご報告いただいて、その月の月末の翌月までには、翌月末までには入金をすると、そのような流れで考えております。","id":"exchange-013"},{"speaker":"くにば委員","kind":"確認","question":"３か月後とかになると、少しネガティブな形のキャンペーンになってしまっていたのであればもったいないなと思ったので、そこに関して伺いました。最後にもう１点が、これは確認なのですけれども、これは事務局機能のみか尋ねました。","respondent":"古巻文化観光課長","answer":"キャナルサイド活性化協会につきましては、共催という形になっておりますけれども、事務局機能を担っていただいているというような状況です。水辺の様々なこういった活動に対して、積極的に取り組んでいただいているこちらに事務局をお願いしている、そういう状況です。","id":"exchange-014"},{"speaker":"松本委員","kind":"確認","question":"２点ぐらいお伺いしたいのですけれども、私も今、場合によっては正規の料金でそのまま取られてしまうということがあるということでいいのでしょうか。お願いします。","respondent":"古巻文化観光課長","answer":"基本的には、枠が埋まるまではキャンペーンの対象とするという流れになるというふうな認識をしておりますので、基本的にはキャンペーンをやっていますのでというご案内をしていただいているという認識をしております。","id":"exchange-015"},{"speaker":"松本委員","kind":"確認","question":"これ適用されないですけれども実際に乗られるのですかと、その場合はどうしても正規料金がかかりますよというふうな周知がきちんとできるのかなと。一応、行政としても確認しておいたほうがいいのではないかと思いますが、そのあたりはどうか尋ねました。","respondent":"古巻文化観光課長","answer":"そこについても、改めてまた今日のご意見を踏まえまして、確認をしていくようにしたいというふうに思います。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"税金が入っている関係上、どういう方たちがこのキャンペーンを利用したのかというようなところというのは、きちんと把握していったほうがいいのかな。どういう、今後の観光にも役立てていったほうがいいのではないかと思うのですが、そのあたりの取組の状況はいかがか尋ねました。","respondent":"古巻文化観光課長","answer":"今後のまた周知、屋形船の振興に資するような形で、データのほうは取っていきたいというふうに思います。","id":"exchange-017"},{"speaker":"小芝委員","kind":"質問","question":"今日、９日で、既に始まって９日たっているわけですけれども、これまで事業者のサイドから、また、実際に屋形船に乗られた方から、そういった反響といったものは区のほうには届いているのか尋ねました。","respondent":"古巻文化観光課長","answer":"早々にいっぱいになってしまっている事業者もありますので、いっぱいになりそうだというようなお話とかというのは、先週ぐらいですかね。聞いてはいるところですので、今後いろいろな、多分、反響が区のほうにも寄せられるのかなというふうに考えております。","id":"exchange-018"},{"speaker":"小芝委員","kind":"質問・要望","question":"せっかく１万人上限で、ぜひ、結果というものを周知していただきたいなと思います。述べさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"大倉委員","kind":"確認","question":"すみません。確認なのですが、この５,０００円上限のキャンペーンが受けられるという認識でいいのか、改めて説明を求めました。","respondent":"古巻文化観光課長","answer":"基本的には、枠内であれば、そのような扱いになるというふうに、区としては認識をしています。","id":"exchange-020"},{"speaker":"大倉委員","kind":"質問・要望","question":"その辺はしっかり確認していただきたいのと、ぜひ、その辺は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"つる副委員長","kind":"質問","question":"その他で長くなってしまって申し訳ありません。それともどこかに、デザイン会社か何かに依頼して作ってもらったのか、そのところが分かれば説明を求めました。","respondent":"古巻文化観光課長","answer":"区の予算が入っていますけれども、デザインについては事務局のほうでデザイン専門家と言うのですか、デザイン会社のほうに委託というか、お願いをして作っていただいたというふうに認識しております。","id":"exchange-022"},{"speaker":"つる副委員長","kind":"提案","question":"今回、この事業周知啓発費、経費等で１５５万円ですかね。この議会からも提案があったと思うのだけれども、そういうデザイン枠採用というのですかねとの意見を述べました。","respondent":"山崎文化スポーツ振興部長","answer":"今後の私どもの観光、あるいは文化なども含めて、しっかりその辺は取り組んでまいりたいなというふうに考えております。上手に事業継続も果たしながら、区の魅力の一部を高めていただく事業者と、しっかり取り組んでまいりたいなというふうに考えております。","id":"exchange-023"},{"speaker":"つる副委員長","kind":"質問・要望","question":"だから、その思いを伝えるというところでお金１５５万円をかけるのだったら、かけないと、それはもったいない。今回をきっかけにしてやっていただきたいなと、ぜひ思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2882#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":19044,"voices":60}},{"id":"r02-20201109-7","meetingId":"r02-cm11","date":"2020年11月9日","dateIso":"2020-11-09","committee":"厚生委員会","time":"午後 １時００分～午後 ２時３７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"それから、今の避難訓練においては、この５名の車椅子利用者ということで行っているのかということを伺いたいと思います。いつ頃からどんな体制で重度の方を受入れていく計画なのか、そういうことが具体化されているのか、これをまず伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"それから、避難訓練の実施につきましては、５名を対象としたものというわけではありませんが、事業所として実施しているものです。特別支援学校等の卒後の方の状況等々ありますので、何名までと具体的にお答えはできませんが、ハードとしては定員２０名で設定しています。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"施設を整備した上で受入れを進めるよう求めてくださいとあるのですが、区ではどんな施設整備が考えられるのか、その点も伺いたいと思います。そういうことを伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"担架等で避難するのも状況によっては難しい場合もあるかと思いますので、消防と連携した対応が必要になってくるだろうと考えているところです。それから、訓練の状況ですが、実際に消防が来て一緒に行う避難訓練は、今年は２月に実施しております。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"今の質問に関わってなのですが、実際に大井消防署の人が来て非常用エレベーターを動かすことになっているのですか。それからもう１つ、今のお答えは、具体的な施設整備としてはまだそれほど考えていないということなのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"動かしているところで救助をしたという訓練は特段行っておりません。整備につきましては、これも冒頭にご説明させていただきましたが、ハードの大規模な改修の予定はしておりません。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"重度障害者の受入れについて、公募要領に特段書かれていないのですが、区としてはどう求めていくのか。区としては重度障害者の方の受入れをどうしようと考えているのか、この陳情に関わってお伺いしておきたいのですが、いかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"地域生活支援拠点では、重度の方の受入れ等も対象とした機能を考えておりますので。必要な費用につきましては、指定管理料としてお支払いしていく考えです。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"現在、車椅子の方が５名ということで、これから重度の方を生活介護でもショートステイでも受入れていくという方向ではないのでしょうか。スペースの問題とか、そういうところから、何人くらいまでだったら受入れが可能かという想定を区としてされていないのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"医療的ケアを含めた方々の受入れ可能総数ということですが、４階が強度行動障害、５階が重症心身障害者対象のエリアということで整備をしております。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"生活介護が２０名、それから短期入所が６名、それの全てが重度ということではないと思うのです。その中で重度の方が何人くらいかという想定を区として持っていないのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"重度の定義というのがはっきり決まっているわけではございません。定義をどう持っていくかによってまた回答の仕方も変わってきますが、体制は整っておりませんが、まずは５名からと想定しております。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"実際の訓練の中にも非常用エレベーターを使った訓練を入れていくべきではないかと思うのですが、なぜそれは、それはどうでしょうか。そういうスペースは実際、実際に一時避難エリアをエレベーターの前でできるのかという辺りについては、どうなのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"なかなか１回の消防訓練であらゆるパターン全てに対応するというのは難しいところです。避難誘導用エレベーターを設置というところになりますと、スペースがないわけではないので、迅速な救助活動ができるよう対応したいと考えております。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこら辺のところを教えていただきたいのと、生活介護で５名、合わせて１０名以上の車椅子利用者に増えていくことになるわけですよね。施設を整備した上で受入れを進めるよう求めてくださいということで、施設整備をするとしたら、その点についてもお聞かせいただけたらと思います。","respondent":"築山障害者施策推進担当課長","answer":"現時点では考えてはおりませんが、もし将来的に対応するのであれば、なくすといったことを取らざるを得ないのかなと考えております。それから、安定した避難ですが、これは冒頭の説明のとおり、利用者の状態に合わせた対応が必要かと考えております。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう１つ、施設を整備した上で受入れを進めるよう求めてくださいというところで、現在ある機能を潰すという答弁は取消すということですか。その点、もう１回、はっきりとお願いしたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"それから、機能を潰すといった発言については訂正します。機能の変更の必要が出てくるだろうという発言に変えします。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"例えば生活介護では５名程度を受入れます、これからの公募ではそこら辺も含めた形での提案ということでお求めになるということでいいのでしょうか。その確認もお願いしますとの意見を述べました。","respondent":"築山障害者施策推進担当課長","answer":"機能変更ですが、今ある設置場所を変更することになりますので、機能を変更するというふうに先ほど回答させていただいたものです。それから、公募での提案につきましては、地域生活支援拠点として必要な機能を満たしてもらいたいと考えているところです。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"本来であればもっとこういうふうな安全な施設を造れればよかったということなのでしょうか。安全な施設にというところであるべきだったと考えられているのか、その点、お願いいたします。","respondent":"築山障害者施策推進担当課長","answer":"先ほどお答えしました機能変更の例につきましては、私のほうで具体例をご説明したものですが、現時点で大きな改修等は考えておりません。安全対策を取っている施設ですので、引き続き災害時に備えて災害対策に取組んでいきたいと考えております。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"建築基準法の基準を満たさなければ建築することができないので。ただ、これから求められるということで出されてきている陳情だと思うのですが、守れるようにという形でぜひ取組みを進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。生活介護含めて、重度心身障害者の方の受入れを進めていただいていることを理解しましたので、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"渡部委員","kind":"意見","question":"どういう形で避難というのも、担いで避難していただくのか、しっかり訓練を重ねてほしいと求めました。今回の件については不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"消防による非常用エレベーターということもありましたが、やっぱり最後はその場の状況に応じた避難ということが求められると思います。そういったこともしっかりと訓練の中でやっていただきたいという要望を含めまして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"おくの委員","kind":"意見","question":"基準は満たしておりますが、まだまだ積み重ねてやっていかなければいけないことが、今の審議の中でもいろいろ明らかになってきたことと思います。そういう意味で、採択でいきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"そして今回の説明を伺って、どうしても人の手で行かなければいけないということなので、その対応を中心に考えているということも分かりました。消防関係の協力で、現状でき得るベストの避難の方法をぜひ構築していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-02","title":"第６期品川区障害福祉計画・第２期品川区障害児福祉計画の策定期間の延期","agenda":"第６期品川区障害福祉計画・第２期品川区障害児福祉計画の策定期間の延期","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"私は必要だと思うのですが、いつするのか、しないのか、すべきではないかと思うのですが、その点についてお伺いしたいと思います。それからもう１つ、なぜこれがなくなったのかというか、そういう意味で必要ではないか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"障害者団体へのヒアリングを、昨年度、基礎調査を実施する際に実施しており、また、今年度も実施する予定です。当事者の意向を反映しやすい状況を今年度整えておりますので、そういったところから今回のような形になっているです。","id":"exchange-018"},{"speaker":"おくの委員","kind":"質問","question":"前回やっているのですから、現場の意見ということでも大事な意見だと思うのですが、やられるべきではないでしょうか。いかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"委員会へご報告するのは、策定委員会の中で素案がおおむね固まった段階が適していると考えております。先ほどと同じ説明になるところがありますが、それからヒアリング等の実施なども含んでおり、丁寧に実施しているものと考えております。","id":"exchange-019"},{"speaker":"おくの委員","kind":"質問","question":"私には適していないと反論する以外ないのですが、どこがどう適しているのか、伺います。〔「適しているよ」「そんなの感覚の問題じゃないですか」「前回と仕組みが変わっているんだから。","respondent":"築山障害者施策推進担当課長","answer":"１点目ですが、先ほどご説明しましたように、素案の段階が良いと考えております。それから、当事者の意見がより直接的に反映されやすい体制を整えておりますので、前回よりもよい策定体制ができているものと考えております。","id":"exchange-020"},{"speaker":"渡部委員","kind":"確認","question":"その方々と一緒に作っているのですから、７団体の人がいるのだから、すごく丁寧な進め方をされているなというのは率直に感じます。１点だけ確認しますが、２カ月ぐらい延ばすというのは、２カ月後ろにずらすという意味合いの報告と受けてよろしいのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"委員がおっしゃるとおり、２カ月遅れたので、その分遅れるという報告になります。２カ月の遅れで済むかどうかというと、ちょっと難しいかなと考えていますので、順調にいけば３カ月程度の遅れかなと考えております。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"日程的な確認ですが、議会への素案の報告というのはいつになるのかということを１点お聞かせいただきたいのと、その点について説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"素案のご報告ですが、パブリックコメントを実施する前の段階になります。ヒアリングの対象団体ですが、区で把握しております１３の団体となっています。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１３の団体の、７団体は分かるのですが、それ以外の団体名を教えていただけますか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"１３団体ですが、基礎調査をやったときに障害者団体にヒアリングを実施しております。その時と同じ団体になっております。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"その基礎調査というのは、報告書に出ていますか。こちらで調べれば分かるのかどうかだけ、説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"調査結果のほうに出ております。","id":"exchange-024"}]},{"id":"topic-03","title":"冒頭申し上げましたとおり、取上げる順番を変更し、報告事項(4)から先に行います。 それでは、(4)旧第一日野小学校跡地を活用した荏原保健センター・荏原健康セン…","agenda":"冒頭申し上げましたとおり、取上げる順番を変更し、報告事項(4)から先に行います。 それでは、(4)旧第一日野小学校跡地を活用した荏原保健センター・荏原健康セン…","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"令和２年度、今の時点で分かっている大規模改修の主な中身を教えていただきたいのと、中身そのものは変わらないと考えていいのか。基本的に中身は変わらない改修なのか、その中身について教えてほしいと求めました。","respondent":"榎本荏原保健センター所長、宮尾高齢者福祉課長","answer":"階数や内容等を維持して実施できるような体制を取りたいと考えていますので、基本設計の大枠が決まったということで、今詳しい中身についてはまだ決まっていない状況です。 特別養護老人ホーム部分につきましては、今回の大規模改修によって、特に機能を変更するとか、そういったことは今のところ予定しておりません。","id":"exchange-025"}]},{"id":"topic-04","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"それをいつ実施するのかということをお伺いしておきたいのが第１点。それに対して品川区はどのように申込んだのか、申請しているのか、その点をお伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"保健所が直接実施するものについては東京都の検査センターに出しますので、その費用は全て東京都が負担しておりまして、区の持出しはないところです。保健所の方針は現状、特段変更しておりませんが、保健所として現状把握してございません。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それに対して区はどう対策を取っていこうという考えなのか、その点について１点、伺いたいと思います。本来であれば、品川区でそういうものの検討はどういうふうにされているのか、そこら辺についての考え方も併せてお聞かせほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"こちらについては本部で検討するという形ではありませんが、それから必要がある場合には複数回検査をするという方針で進めています。高齢者施設、あるいは重症化する可能性がある障害者施設等については、それぞれの部署で適宜検討されていると伺っております。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"やっぱりこれを活用して、高齢者のＰＣＲ検査を拡大していくということが必要なことではないかと思うのですが、そこの考え方はいかがでしょうか。これは保健所だ、保健所からの働きかけも必要なのではないかと思うのですが、その点についてもいかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"要は広く浅く何度も検査という考えはもともと持っておりませんので、そこのところは変わっておりません。適切な時期になるべく広い対象に確実に検査を実施し、何か新たな検討が必要というふうには、現状では考えておりません。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、東京都がこういう補助金を出しますよということで予算を組まれましたが、これに対して、区としては必要だと捉えていないので、申請はしないということか尋ねました。","respondent":"鷹箸保健予防課長","answer":"今後、もちろん福祉部門として今回の補助金を活用して何らかの新たな方針を立てられる可能性はあると思いますが、広げる可能性はあるかと思います。今後、この補助金を活用して、福祉部門で新たな方針を検討されているのではないかと考えているところです。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"やるべきだからやったほうがいいのではないかという保健所からの発信は、今までの考え方を踏襲すると、ないという方針で確認させていただいていいか尋ねました。","respondent":"鷹箸保健予防課長","answer":"事前に検討され始めたときにご相談がありまして、保健所のこれまでの考え方とは違いますので、なるほどなと理解したところです。相当考えた上で、何か新たな方針を出される場合にはご相談があろうかと思いますが、今後も感染拡大防止のために進めていきたいと考えております。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"質問・要望","question":"確認させてほしいと求めました。その３点、お伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"ＣＯＣＯＡ通知で検査をしたから陽性なのか、もともと症状があって陽性なのかというのは、なかなか判断が難しいところかなと考えています。次の報告でＣＯＣＯＡについてはご説明したいと思います。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3580#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":22993,"voices":94}},{"id":"r02-20201109-8","meetingId":"r02-cm11","date":"2020年11月9日","dateIso":"2020-11-09","committee":"建設委員会","time":"午後 １時００分～午後 ５時０１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を90件整理しています。","topics":[{"id":"topic-01","title":"（仮称）旗の台六丁目公園整備に向けた都市計画決定","agenda":"（仮称）旗の台六丁目公園整備に向けた都市計画決定","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"ワークショップを２回実施されたということですけれども、このワークショップでのやり取り、今の状況をお聞かせいただけたらと思います。このワークショップは何人くらいでやられているのか、伺いたいと思います。","respondent":"高梨公園課長","answer":"ご説明させていただいたとおり、都市計画の手続きを行って、都市計画公園として区として定めていこうということで進めようというものです。どうしても予定が合わなくて欠席という方も何人かいらっしゃるのですけれども、現在のところ２回開催しています。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"公園の違いについては、広域的な見方と地域での見方というところでの違いというお話だったと思うのですが、規模とかによる違いというのは特にないのか尋ねました。","respondent":"高梨公園課長","answer":"なかなか品川区ではそういった規定に基づく大きな公園の設置は難しいといったところもありまして、品川区の中で見て、特段。このように区としては考えているところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、ワークショップをやられて、地域の方といろいろ様々な意見を聞きながら進めていらっしゃるということですので、そういった住民の声を反映させて造っていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"今回のお知らせには、事前に地域に配布されていたものには、当日の手話通訳についての記載がなかったですよね。こうした手話通訳についての記載を求めたいのですけれども、そこのところはいかがでしょうかというのが１点と、多分。","respondent":"高梨公園課長","answer":"やはり多くの方がいらっしゃる説明会等につきましては、基本的には手話通訳をつけていくような形で進めていければいいと思っているところです。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"視覚障害の方に向けた説明会の実施についてのお知らせというのはどのようにされているのか。そういった周知についても伺いたいというのと、実施してほしいと求めましたが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"お知らせの周知につきましては、ホームページの読み上げ機能等での対応が、今現在、行われているといったところにとどまっていると思います。説明会等での、どのような対応が現実的に可能かといったところにつきましては、今後の検討課題とさせていただきたいと思います。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"それと、補助金というのが、都市計画公園にはどういう関係が発生してくるのでしょうか。それと、ワークショップを２５人という形で２回ほどされたということなのですけれども、この２５人というのは公募か尋ねました。","respondent":"高梨公園課長","answer":"都市計画公園としてはしっかりと手続きを進めるとともに、東京都からの補助金もしっかりと獲得していきたいと考えているところです。周辺町会を中心に声をかけさせていただいて、ご応募いただいたという形で、募らせていただいております。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"上位計画があれば、その関係がどうなのだろうと思ってお聞きしましたので、もう少し教えてほしいと思います。それと、この土地を取得した経緯というか、どういう経緯でこの土地を品川区として得ることができたのかということを説明を求めました。","respondent":"高梨公園課長","answer":"やはり東京都の都市計画審議会等での説明もなかなか難しくなるところだと想定をしておりますので、今回、このように考えているところです。今、進めている大井坂下公園以外にも展開をしていきたいと、遊具については考えているところです。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"たまたま今回は教えていただいたというきっかけがあったとは思うのですけれども、今後、そういうものも検討してほしいと求めました。親御さんたちも本当に楽しんでいる公園もあるので、そこら辺を参考にしていただいて、決めつけないでほしいというのが意見としてはあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"水辺のライトアップ整備工事（アイル橋）","agenda":"水辺のライトアップ整備工事（アイル橋）","exchanges":[{"speaker":"西本委員","kind":"質問","question":"契約金額などは今総務委員会で話されていると思うのですけれども、ランニングコストとかというのはどのくらいかかるものなのでしょうか。文化観光課とかといろいろと共同で何かやろうとしているのか、どういうことを想定されているのか、お聞きしたいと思います。","respondent":"松本河川下水道課長","answer":"ご質問、２点あったと認識しております。文化観光課とも連携をして、いろいろなイベント等の中で、こういったライトアップを活用していきたいと考えているところです。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"１橋７５万円と言っていたのですけれども、このアイル橋で７５万円ということですか。それはどういう意味になっているのか尋ねました。","respondent":"松本河川下水道課長","answer":"７５万円というのは、１つの橋当たり７５万円ということになってあります。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"今日はこのアイル橋になりますけれども、この１３橋は既にかかっている部分があって、これは何番目なのですか。それとも、もうこれで最後、１３橋が全部ライトアップされていますということなのか尋ねました。","respondent":"松本河川下水道課長","answer":"今年度、残りの５橋をやる予定でございまして、今、要津橋のライトアップと、今回のアイル橋のライトアップ工事が進んでいるところです。残り３橋につきましては、今後、契約をしていく予定です。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"橋もいろいろと観光資源という形になるかと、もちろん期待はしておりますけれども、これは意見として、ぜひ文化観光課のほうと協力体制を取っていただいて、これも一つの大きな目玉になるように工夫してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"田中委員","kind":"意見","question":"そこでもＬＥＤのやつで幾らとか。〔「契約案件だから総務（委員会）だと言っている」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"私が伺いたかったのが、この１つの橋でかかる金額だったのですけれども、ＬＥＤがどのくらい使われて幾ら、ＬＥＤの設置代に幾らとか、そういった内訳があると思うのですけれども……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"のだて委員","kind":"意見","question":"ランニングコストが７５万円ということで、コロナ禍でもあるので、そうした中でこのライトアップが本当に必要なのかという疑問があるのです。ライトアップの予算というのが６億１,３５７万円ということで出ていたのですけれども、いかがかということと、あと……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"予算を要望するのはここの課だと思うので、そこの考え方を伺いたいと思ったのですが、お答えできたら答えていただきたいのと、あと、橋のライトアップが、先ほど少しありましたけれども、水辺の観光とか交流の軸にしていくということに、どのように寄与していくのかというところを伺いたいと思います。","respondent":"松本河川下水道課長","answer":"当初はにぎわう観光・交流の軸ということで進めて、観光だとか、そういうものが重要だと考えているところです。やはり水辺は品川区の特徴であるところですので、舟運をはじめとして、そういったところでアピールしていきたいと考えているところです。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"最後に１点、事務事業概要にアウェアネスカラーというのが書いてありましたけれども、区としてはどういったことをやっていくのか。ピンクリボンデーというのは１つ書いてありましたが、ほかのものはどういったことをやっていくのか、伺いたいと思います。","respondent":"松本河川下水道課長","answer":"それと合わせたような形の連携をした対応といたしまして、自閉症の理解・支援をする応援メッセージということを、こちらも色はブルーです。エイズの理解・支援ということで赤色にするとか、全部で約１０のアウェアネスカラーをしていくように今考えているところです。","id":"exchange-017"},{"speaker":"大沢委員","kind":"質問","question":"この委員会と違うといえば違うのですが、委員長にご指摘いただければ。今、課長の答弁の中で、観光という話の中で、経済も戻りつつあるというお話をいただいたのですが、何を根拠におっしゃっているのか、説明を求めました。","respondent":"松本河川下水道課長","answer":"戻りつつというか、申し訳ございません。そこは発言を撤回させていただきたいと思うのですが、経済が戻るように努力していくです。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけお伺いしたいのですが、簡単に言うと、これは人道橋ですよね。そういうことはお考えの中になかったのかということをお伺いしたい。","respondent":"松本河川下水道課長","answer":"今お話がありましたのは、天王洲ふれあい橋のことだと思います。天王洲のほうで実施していただいたという経緯がございまして、特段、私たちの計画の中にはそこの中には入れていなかったです。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問","question":"車が走っているところだと、なかなか上にかけるということができないではないですか。ライトアップするのであれば、そういうチャレンジ的な部分もあってもいいと思うのだけれども、そこら辺はどうお考えですかということです。","respondent":"松本河川下水道課長、藤田防災まちづくり部長","answer":"質問を勘違いしてございました。ここの所管が分かっていないところがありますが、このライトアップについてはしっかりとやっていきたいと考えているところです。今回、ライトアップということで、電気屋のほうに発注する工事の分としてやらせていただいてあります。","id":"exchange-020"}]},{"id":"topic-03","title":"令和３年度からの不燃化特区支援制度","agenda":"令和３年度からの不燃化特区支援制度","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"共産党区議団としても、この支援制度の延長を要望していたので、よかったと考えています。いかがでしょうかということと、申請するにあたっての条件というのはどういったものがあるのか、伺います。","respondent":"佐藤木密整備推進課長","answer":"３点、１つ目の老朽家屋の解体助成というのが前提になってまいりますので、老朽建築物に該当するということが前提になります。そちらに該当した上で、以降の移転、建て替えの助成につながってまいります。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"どういう優先度が高いのか、お伺いしたいと思うのと、必要な条件というのがあるのかどうか。どういった条件があるのかということで伺いたいと思います。","respondent":"佐藤木密整備推進課長","answer":"１つ目の、特区の現在行っております事業実施地区を除きますと、こちらが低い地域となっております。冒頭ご説明したとおりなのですが、木密連担地域改善事業としまして、地区の防災性の向上を図る事業を行っている地域です。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"優先度が高いということで今回３地区ということですけれども、やはりほかのところでも、建て替えにあたって進めていく必要があるところというのはあると思うので、こういった支援をしていただいて、建て替えを進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"新たに３地区が加わったことの選定基準は分かりました。そのほかに、この３地区以外でここもどうかと挙がった地区がもしあったら、その地区も何地区あったのかというのをお知らせほしいと求めました。","respondent":"佐藤木密整備推進課長","answer":"先ほどからご説明しておりますけれども、大井二丁目と西中延三丁目という地域ですので、ここのところは優先してということで入れております。不燃領域率７０％になると、今回、地域を選定しているところです。","id":"exchange-024"},{"speaker":"田中委員","kind":"意見","question":"この３地区以外にも、ここの３地区ほどはいかなかったけれども、候補に挙がった地区が何地区かあったということだったのですけれども、大体何地区ぐらいというのをお知らせほしいと求めました。","respondent":"佐藤木密整備推進課長","answer":"新しく令和３年度から事業を行ってまいりますけれども、その上で事業が継続するということであれば、再度検討していきたいと考えております。","id":"exchange-025"}]},{"id":"topic-04","title":"大井町駅周辺地域のまちづくり","agenda":"大井町駅周辺地域のまちづくり","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"まちづくり方針の策定のほうで伺いたいのですけれども、１２７名の方が参加をしたということで、その説明会での区の受け止めを伺いたいと思います。住民の意見を聞いていくということで修正をされておりますが、具体的にはどのように意見を聞いてやっていくのかというところを伺いたいと思います。","respondent":"多並都市開発課長","answer":"説明会でも広町地区に関するご意見で、2)と3)も含めてですけれども、加えしています。地域の方が主体でまちづくりを進めるという観点からいえば、今回、ご意見を踏まえて修正したというところで取り組んだところです。","id":"exchange-026"},{"speaker":"のだて委員","kind":"確認","question":"地域の方からは意見を聞いてほしいという声がたくさん出たという受け止めということでよろしいということか、その確認と、そこを伺ったので。","respondent":"多並都市開発課長","answer":"都市計画の手続きを来年度予定しているということでこの間もご説明させていただきましたが、地域説明会、法令に基づいた手続きも含めてしっかりとご説明しながら進めていくということで。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"いかがでしょうかというところと、資料のところで伺いたいのですが、これが実際的にどういうことなのか。Ｃ地区のところに緑色の丸がついているのがなぜかというお話だったのですが、私もそれはなぜかと思ったので、そのご説明をほしいと求めました。","respondent":"多並都市開発課長","answer":"１点目の、それをしっかりと皆さんで考えていただくということを、区としては支援させていただきたいというところが今現在のところです。補助２６号線が開通した後の動線であったり、実際の段階で、そういう考え方を今回の方針の中で示させていただいているです。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"一応、イメージということですけれども、想定している場所がありましたら、伺いたいと思います。１２ページの資料で、歩行者広場というのが２か所追加されましたけれども、お願いしたいと思います。","respondent":"多並都市開発課長","answer":"１２ページの歩行者広場につきましては２つありまして、駅から出たところの、人のたまりの空間という意味で書かせていただいております。先ほどの１１ページのイメージ図の右上の2)になりますけれども、そのようなことで想定して書かせていただいたところになります。","id":"exchange-029"},{"speaker":"のだて委員","kind":"確認","question":"新庁舎のほうはアセスメントの対象ではないということでいいのかという確認と、今回、ＪＲの建築計画がどういったものになるのか。そこを伺いたいと思います。","respondent":"多並都市開発課長","answer":"上側が一番上の層で、駅からの動線で、真ん中が補助２６号線との段差を解消していくような考え方ということで。詳細につきましては、１２月１日のこの計画書の中で公表するということで聞いているところです。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問","question":"幾つかお伺いしたいのですけれども、まず、１枚目の広町地区のまちづくりについての、今ご説明があったところなのですけれども、縦覧期間について、この周知方法をまず聞きたいのと、あと、ここでは意見書の募集というのはないのかというところを伺いたいのですけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"周知としましては、１２月１日号の広報しながわでお知らせする予定としております。意見書については、この縦覧と合わせていただけるようにということで、そのように予定しているということで聞いているところです。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"ほかのところでも、縦覧期間の周知が本当に分かりづらくて、なかなか意見を出せなかったということがあるので、ぜひ広報しながわだけにとどまらず、ホームページであったりとか、お知らせをしてほしいと思うのですけれども、そこのところを伺いたいと思います。","respondent":"提坂環境課長","answer":"今、周知方法としては、確かに広報しながわだけにとどまっているかと思いますが、その辺、今後検討する余地がありますので、ホームページに載せられるかどうか、検討してまいりたいと考えています。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"これは要望で終わります。１３ページにも、地域とはどこまでを指すのかということを伺いたいのですけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"地域というのは、このタイトルにあります大井町駅周辺地域というところを捉えているところです。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"別添２の４ページの広町地区のところに書いてあるとおり、広町地区は品川区浸水ハザードマップに載っているというご説明があるではないですか。貯水槽を造るようなイメージとか、そういったことは考えられているのかといったことを伺いたいのですけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"庁舎に関わるところということですので、庁舎につきましては、そこと連携しながら進めていくということで考えているところです。これにつきましても、どのような機能が必要かということは検討していくところになりますので、併せて連携しながら進めていくべきと考えるところです。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"決算特別委員会でもこのことについて伺ったのですけれども、広く区民の方からもアイデアとかを募ってほしいと思うのですけれども、そこのところを伺えればと思います。","respondent":"多並都市開発課長","answer":"ＪＲ東日本は今日お話しさせていただいたところで進めながら、新庁舎についても、区の利用区分の中で計画していくところになります。しっかりと検討していく必要があるということですので、そこの中で今のご意見も踏まえながら検討していくことと考えているところです。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"勝手にやるのはいいのかもしれないのですけれども、ただ、誤解されるような状況はすべきではないし、そういうことはやめていただきたいと。注意するであるとか、していただきたいと考えていますが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"１３ページでも、まちづくりの進め方ということで左上に「段階的なまちづくり」と書かせていただいておりまして、書かせていただいたものであります。説明会の案内につきましては、より適切な方法があるのであれば、それは皆さんと話していきたいと思っているところです。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"地域住民が、しっかりと自分たちの地域をどうしていくのだというところの発生から、歩み寄りながらというところが一番いいのかなと思っているのです。ご理解を求めながら、しっかりとした態度を取ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"８ページの3)の交通広場なのですけれども、ごめんなさい、先ほどご説明があったかもしれないのですけれども、素案のときにはこの矢印は出ていたと思うのですが、今回このように文言を長く書かれて、交通広場と位置づけられた理由というか、その辺をお知らせいただきたいのですけれども。","respondent":"多並都市開発課長","answer":"先ほど広町地区の中でも少しご説明、歩行者広場というのを設置するということと、交通広場が連携するというところをご説明したいということで。利用がスムーズに上下の移動でできるというところをこの中で示したかったので、そういう意味の示しだと思っていただければと思います。","id":"exchange-038"}]},{"id":"topic-05","title":"区内の魅力的な建築物を楽しむイベント「オープンしなけん」","agenda":"区内の魅力的な建築物を楽しむイベント「オープンしなけん」","exchanges":[{"speaker":"西本委員","kind":"質問","question":"参加の申込み期限が１１月６日金曜日で、もう終わってしまっているのです。今、大体どのくらいかというのは分かっているのか尋ねました。","respondent":"長尾建築課長","answer":"参加の申込み期限は１１月６日ということで、先週の金曜日に締め切っております。参加の申込みの状況としまして、４日時点の情報になりますけれども、応募の延べ人数としては約４００人弱の方に申し込んでいただいている状況です。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"４００人ということですが、今年はコロナ感染のこともあるので４００人程度がいいということなのか、もう少し余裕がある状況なのか。いかがか尋ねました。","respondent":"長尾建築課長","answer":"今回、１０本の街歩きツアーを企画しておりまして、各ツアーの定員は８名となっております。４００人ほど延べでお申込みいただいていまして、各ツアーとも抽選で８名にこれから決定していく予定となっております。","id":"exchange-040"}]},{"id":"topic-06","title":"東京港大井ふ頭（都有地内）において確認された「ヒアリ」","agenda":"東京港大井ふ頭（都有地内）において確認された「ヒアリ」","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"要望してほしいと求めましたが、いかがでしょうかということと、そこを伺いたいと思います。前回が７月１０日で、３か月に１回くらいのペースで実施したほうがよいのではないかと考えるのですけれども、いかがか尋ねました。","respondent":"提坂環境課長","answer":"前回の７月とは別ルートで侵入したものと考えるとご説明いたしまして、環境省の主催で港湾事業者向けのヒアリの講習会を実施、先方の。年間２回ということでございまして、その辺、国の動向を注視してまいりたいと考えています。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"出荷元の対策がどうか分からないというお話もありましたけれども、今年度あと１回くらいはやっていただくように、国に要望してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"若林委員","kind":"確認","question":"ここで正式に確認したというか、こういう国の確認、専門家の確認の前に殺虫餌を設置するということは。国がどういう説明をしているかというのが１つ確認と、２の区の対応状況の一番最後の、この６か所の具体的な場所を説明を求めました。","respondent":"提坂環境課長","answer":"その中で、ヒアリと疑わしい個体を発見したときは、拡散を防ぐために即座に殺虫餌を設置してということで内容が盛り込まれているはずです。６か所ということで、東品川清掃作業所、こちらの６か所です。","id":"exchange-043"}]},{"id":"topic-07","title":"令和２年度 ウォームビズキャンペーンの実施","agenda":"令和２年度 ウォームビズキャンペーンの実施","exchanges":[{"speaker":"田中委員","kind":"質問","question":"実施内容の（１）で、ただ、換気をしていく中で室温が下がってしまう。感染症対策もやはり入れていかなければいけないのだろうと思うのですけれども、どのようにお考えなのか、伺いたいと思います。","respondent":"提坂環境課長","answer":"自動的に換気の機能というか、排気の機能があるということなので、その辺をうまく利用しながら室温を保つような工夫をいたしたいと思います。その辺は、経理課の庁舎管理の担当と連携してやっていきたいと考えています。","id":"exchange-044"}]},{"id":"topic-08","title":"特定整備路線放射２号線沿道の都市計画変更に伴う説明会の実施","agenda":"特定整備路線放射２号線沿道の都市計画変更に伴う説明会の実施","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"資料について伺いたいのですが、特別工業地区というのが、「地場産業の保護育成と公害の防止を図る地区」と資料に書かれていますけれども、今回、商業地域に変わるところがありますけれども、つまりは、地場産業の保護は必要ない、なくなったということなのか、伺います。","respondent":"鈴木都市計画課長","answer":"それに合わせて３０ｍ広がる部分について、この変更に合わせて、詳細な調査を現地でかけてあります。変更をかけるところで工場が操業されていて何か影響があるとか、そうしたところがないということで、今回の変更に至っているというような状況です。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"この道路がまだできないうちに都市計画変更を行っていく、手続きを進めていくというのはすべきではないと思うのですけれども、いかがでしょうか。この放射２号線によって分断されてしまうということになりますけれども、どういった状況になっているのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"最低限高度７ｍですとか、防火地域の変更をかけるというやり方よりも、決定を進めるべきだというのが区の考えです。やはり個別の案件ですので、それは個別に東京都のほうでしっかりと説明が行われて、交渉が行われているという区としての理解です。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問","question":"できた後よりも今進めていくというお話でしたけれども、それが万が一、万が一というか、私たちは中止にするために頑張っておりますが、放射２号線が廃止になった場合に、その沿道で高い建物が建っていくとすると、こうした建物は、どうなってしまうのか尋ねました。","respondent":"鈴木都市計画課長","answer":"今進められている、積極的に東京都が進めている事業に対して、耐震化も含めて一生懸命取り組んでいきたいです。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問","question":"中止すべきだと思いますけれども、補助２６号線もまだ開通していないというもとで、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"都市計画道路の整備につきましては、東京都が鋭意、地域へしっかりと説明しながら、現在進めているところです。さらにはソフト的な取組も含めて総合的、重層的に、やはり地域の防災性の向上に資する取組を今後もしっかりと進めていきたいです。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったことを強化していく、後押ししていくということのほうが、今住んでいる人たちも協力しやすいということになります。そのほうが早く防災性が向上していくのではないかと思いますので、この手続きは進めるべきではないと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"この４０ｍ以内という根拠をお知らせいただきたいというのと、あと、区立学校とかも近くにありますよね。学校へのお知らせ、保護者へ向けたお知らせというのもされるのかといったところも知りたくて、お伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"保護者へどうご説明していくかというのは、教育委員会と相談ということになりますが、学校のほうでしていただくということになろうかと思います。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"１２月上旬とあるのですが、具体的なものを教えていただきたいということと、縦覧の周知についてどのようにお考えなのか。多くの方が縦覧をして意見が出せるように、区民全体に周知するような方法をしてほしいのですけれども、そこについて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"保護者への説明が必要なのではないかですが、最低限度高度地区の考え方は、この変更によって何かが変わるわけではございません。不安をお持ちの方への説明というのは当然、その辺は以前は区の窓口のみの縦覧でしたが、その辺でしっかりと周知をしていきたいです。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"求められればといっても、会場が第一日野小学校と荏原第一中学校なので、学校のお知らせとかは外に向かって貼りつけてあったりするではないですか。そういったところで、この説明会が開催されることというのが貼り出されるのかどうかというところを、確認もさせてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"説明を求められればと私は先ほどお話ししましたが、説明会に来ていただいてご説明しますので、そうした形でしっかりと対応していきたいです。それともう一つは、計画の掲示でしたでしょうか。","id":"exchange-052"},{"speaker":"田中委員","kind":"質問","question":"説明会の掲示を学校でされるのか。学校に掲示板というのがあるではないか尋ねました。","respondent":"鈴木都市計画課長","answer":"当日ということではなくて、従前からということですか。例えば、１週間前とか２週前から学校の掲示板に、いつ説明会を行いますというお知らせを掲示していただくということは考えてございません。","id":"exchange-053"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもも保護者も、学校に関わることなので、そこに通う方たちも関係することだと思うのです。その程度だけでもいいので、周知方法の一つとしてしてほしいと要望したいのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"これは学校の周辺の用途地域、建蔽率・容積率の従前・従後の変更はございませんので、この変更によっての影響はないです。先ほどからご説明しているように、この変更の対象となる必要な方々に直接お知らせをしていくということで、今、考えているところです。","id":"exchange-054"},{"speaker":"田中委員","kind":"質問・要望","question":"今ご説明いただいたことを保護者の方に説明していただきたいのです。だから、学校の……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"田中委員","kind":"質問・要望","question":"そこに通う子どもたちも、そこに住んでいなかったとしても、学校に通っているところで関係するではないですか。ですので、ぜひそういったお知らせをしてほしいと言っているのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"そこに学校のほうで必要に応じて保護者の方に説明する必要があるのであれば、利用者含めて外側、必要があるかどうかについても判断をしていくのは。","id":"exchange-056"},{"speaker":"田中委員","kind":"質問・要望","question":"では、気になる保護者の方が学校のほうに求めればいいということですよね。説明を求めていただきたいということもあったので、確認と要望をさせていただきたいのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"重みづけみたいなところもあるでしょうけれども、当然ながら、できるだけ分かりやすくそこに入っていただけるような工夫はしたいと考えています。","id":"exchange-057"}]},{"id":"topic-09","title":"航空機騒音の常時測定結果","agenda":"航空機騒音の常時測定結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"６月を見ますと、６月が一番うるさかったのかなと私は受け止めましたけれども、どうなっていますでしょうか。今回、Ｌｄｅｎの数値が書いていないと思うのですが、そのＬｄｅｎについても伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"９月が３０件、１０月が１７件、本格開始以降これまで１８７件の電話等のお問合せをいただいてあります。基本的なＬｄｅｎの考え方というのは、一定程度データが集積されて、年間のＬｄｅｎの公表を考えているです。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、実際の区のＬｄｅｎという指標での評価というのは、今度の３月を過ぎた後になってしまうということなのでしょうか。こうしたことについて国から説明を受けたり、あるいは抗議をしたりということをしたのかどうか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"４月より測定を開始していますので、来年の３月までのデータを取りまとめて、年間Ｌｄｅｎとして公表していくというものとなろうかと思います。抗議や説明をしているのかというところがございましたが、数は少ないものの、今後確認をしていきたいです。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"は確認ということですが、やはり８４ｄＢというのは、立会小学校、台場小学校どちらも１回だけなのか。区の受け止めというのですか、この結果をどう見ているのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"先ほどご説明したとおり、６月でそれぞれ１回程度ということで、確認が必要だです。あるいは７０台後半だから想定内ですとか、それに基づいての判断ができるわけですが、区民生活に影響が出ているという受け止めです。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"羽田新飛行ルートの中止を求めていくという立場に立ってほしいと求めましたけれども、いかがでしょうか。立会小学校では７回ありますし、台場小学校では４回という状況ですので、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"今ご紹介いただいたように、区民の方からも、区に直接電話等で騒音または落下物に対する不安の声というのはいろいろと寄せられて、承知しています。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"最後に１点伺いたいと思います。この騒音の区民への影響を問題だとは思っていないのか、伺います。","respondent":"鈴木都市計画課長","answer":"そうした声が区に届いているというところを受け止めて、区のほうは、先ほどご答弁申し上げたように、しっかりと国に届けて、取組を求めているです。","id":"exchange-062"},{"speaker":"田中委員","kind":"確認","question":"お伺いしたいのですけれども、そういった確認というのを今後してほしいのですが、そこのお考えを伺いたいと思います。学校については、養護教諭の記録などと照らし合わせることもできるのではないのかと思うので、そこのところをまず確認させてください。","respondent":"鈴木都市計画課長","answer":"回数を何百回ですとかとご説明しましたが、発生回数が２回、３回と。検討、実施は、区としてもしっかりと国には求めていきたいと考えています。","id":"exchange-063"},{"speaker":"田中委員","kind":"質問・要望","question":"８０ｄＢを超えたか超えていないかとか、自治体としてきちんとそれはやっていくべきだと思うので、そこのお考えをもう一回伺いたいと思います。今回も、その現状を区のほうで把握されていたらお知らせいただきたいと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"必要があれば、国のほうで調査をかけていただくというところが、これが区の基本的な考え、スタンスです。固定化回避に向けた第２回目の検討会の開催状況ですが、３回目の開催の予定については、その検討を進めて準備は進めているとは聞いているのですが。","id":"exchange-064"},{"speaker":"田中委員","kind":"質問","question":"どうですかと。そこに照らし合わせて、体調の変化とかを見ていこうと思うのですけれどもいかがですかといったような呼びかけがあってもいいと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"田中委員","kind":"質問・要望","question":"以前、区としては品川区の上空を飛ばないように求めた検討会、それ以外のルートを飛行するために求めた検討会だというお話でしたよね。あったそうなのですけれども、そこについて区として把握しているのか伺いたいのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"見込みとして使えそうな技術がないかというところを、国としてもしっかりと検討していただいているという受け止めですので、ルートの変更もできない。ただ、発言として、今現状の発着の滑走路を前提として検討していますというのは承知しています。","id":"exchange-066"},{"speaker":"田中委員","kind":"質問・要望","question":"今、検討会第２回目を実施することを求めているのもそうなのですけれども、それも口頭ですよね。文書でのやり取りとかというのは、きちんと根拠に残るようなやり取りをされているのかというのを伺いたいのと……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"田中委員","kind":"質問・要望","question":"区としても、検討会は自分たちが実施させたといったこともあるので、もっと強く求めてほしいと思うのですけれども、そこら辺も伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"本年５月の、これはまさに品川区のみが昨年の８月の段階では求めてきた内容ですので、引き続き強く国に対して求めていきたいです。","id":"exchange-068"},{"speaker":"田中委員","kind":"質問・要望","question":"多分毎回私、言っていると思うのですけれども、航空機騒音の測定結果の報告も含めて、次回から、区への騒音に対する問合せの件数と、測定の結果と、あと、検討会の状況、国とのやり取りの状況をきちんと報告してほしいというのを強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり品川区独自で調査していくということは本当に大切なことですから、それは評価をして、このデータの見方というのはどのように見ればよいか。先ほどもコロナ禍があって、私はこのデータは３分の１以下の結果ではないかと思っているのですけれども、それはどう考えられますか。","respondent":"鈴木都市計画課長","answer":"Ｃ滑走路が６３％減ですので、単純に考えれば、実際の飛行は倍近い数の飛行機が飛ぶということになろうかと思います。先ほど８４ｄＢというのもありましたが、その辺は変化はあるのかないのかというところも含めて、これはしっかりと測定しながら注視していきたいです。","id":"exchange-070"},{"speaker":"西本委員","kind":"質問・要望","question":"区の見解はどうなのでしょう。品川区の強さといいますか、どこまで言える状況にあるのか、教えていただけますか。","respondent":"鈴木都市計画課長","answer":"コンサルを通して確認していますので、事実として実態としてあるということはしっかりと受け止めておりますし、認識しています。５分、すべて伝えるということはできませんが、対面のときでも区民の声というのはしっかりと届けさせていただいている状況です。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区の立場というのがあるので、なかなか国と対峙するというのは難しい部分があるかと思うのです。やっていただきたいのは、やはりそこを品川区の立場としてしっかりと国のほうに伝えていただきたいということを強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは国策なのだから、そこら辺のことをしっかりと国にも伝えて、いろいろな状況の中でどういう判断をしたのだというのを改めて聞いてほしいと思う。これが表に出るなら、きちんと分かるようにしてほしいと思っていますので、そこら辺の答弁をお願いします。","respondent":"鈴木都市計画課長","answer":"本格運用前も実施後も変わっていないのですが、この３０分の範囲で実際に飛んだというのは、実際にあるです。当初説明の中で、様々な場面で再度説明を求めるですとか、必要なところは区としても説明を求めていくというところは。","id":"exchange-073"},{"speaker":"石田（秀）委員","kind":"質問","question":"表の見方がきちんと分かるようにしてほしいというのと、あと、今言ったように、３時。これもどこかでそれは分かるようにしてほしいということがあるので、これはお願いだけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"大沢委員","kind":"質問・要望","question":"途中ですから、そのような問題意識を持っていただきながら、国の方と接するなりお話をしていただきたいと考えています。これは要望ですので、答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"}]},{"id":"topic-10","title":"令和２年陳情第５２号、西大井地域に西大井駅経由区役所に通じるコミュニティバス運用を求める陳情","agenda":"令和２年陳情第５２号、西大井地域に西大井駅経由区役所に通じるコミュニティバス運用を求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それについて伺いたいのですけれども、４丁目」と書かれておりますが、どんな意見が出たのでしょうか。それと併せて、これまで開催してきたほかの地域の状況も報告ほしいと求めました。","respondent":"鈴木都市計画課長","answer":"この補助２６号線の開通は考慮しているのかしていないのかとか、これ、通勤・通学についても対応しなくてもいいのではないかと。なかなか３ルートとも赤字になるような設定、収支についても説明を差し上げたのですが、ご意見は様々いただいているところです。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"高齢者の方も多いということで、気軽に出歩けるようにコミュニティバスを通してほしいということでした。そうした外出を促進することにもなると思いますので、ぜひ考えていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"当委員会のほうでもご説明しておりますし、昨年度の学識経験者を交えた検討会の中で区の考えとしてもお示ししていますが、区としても事前から調査。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"伺いたいと思います。３０分くらいかかってしまうということで言われておりますので、ぜひ検討をお願いしたいのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"いろいろと検討を重ねて、通したい、通すべきところはしっかりと警察とも調整を図っていきたいという考えは先ほどご説明したとおりです。乗り継ぎ券の考え方ですとか、あるいは工夫した提案をしていただけるかどうかも含めて、いただいた声は検討していきたいです。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、滝王子通りをそんなに通らなくても行けるのかというところもありますので、その辺をぜひもう少し検討ほしいと求めました。は問題はなかったということですので、ぜひ前向きに進めてほしいと求めましたが、最後に伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"足を生んでいくかですので、そうしたところでは、もともと当初からこれについてはしっかりと検討していかなければいけないと。ただ、車両制限令という大きなハードルがありますので、そこは警察のほうとしっかりと今後も協議をしていきたいです。","id":"exchange-079"},{"speaker":"石田（秀）委員","kind":"提案","question":"試乗したというか、そのときは警察の方もいたと聞いたのだけれども、そこはどう捉えているのですか。だけれども、それはそれで回って来られないことはなかったと聞いたのだけれども、そこら辺のところはどう捉えていらっしゃるのか尋ねました。","respondent":"鈴木都市計画課長","answer":"まず職員が本当に曲がれないところ、何回も切り返さないとできないところはないかどうか確認したいというところで。今後進めていく中でもう一回、おそらくそういう場、そうした意味での試走を今回行ったです。","id":"exchange-080"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"地域の方から伺っていて、地域の方はあれで大変期待感を持ったみたいであります。この結論は後でしっかりと言いますが、ぜひそれでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"田中委員","kind":"質問","question":"いろいろと区が検討した結果、町会の方にもぜひそこに参加させてほしいと言って区民の方が声を上げたのですけれども断られてしまったという声が。これからでも意見を聞く場というのを設けてほしいと思うのですが、その辺りについて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"そうすると、あるいはこちらの地域の参加が全くなかったりということも考えられましたので、出たいという形で参加いただいた方もいらっしゃいます。","id":"exchange-082"},{"speaker":"田中委員","kind":"質問・要望","question":"そして、各地域の状況が分かるような聞き方とか、周知の仕方をしてほしいと要望いたします。陳情審査だよ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"田中委員","kind":"意見","question":"荏原地域に障害者施設がないので、荏原ルートが心身障害者福祉会館を経由していればよかったなど、様々な声があったのです。このように反映されるようにしてほしいと思うのですけれども、今後の地域の声の聞き方をもう少し具体的にお知らせほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"結論としては、不採択。個々のそういうご要望については、私どもがするべきではないと思っておりまして、陳情については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"若林委員","kind":"質問","question":"西大井、いわゆる大井ルートのさらなる拡充については、今るる質疑があったとおりだと思います。そういう声を地域からお聞きしているので、大井地域の方が喜ぶルートを、皆さんの声をもとに実現していただければということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"のだて委員","kind":"意見","question":"この西大井地域は坂道が多かったり、あと、高齢者が多く、移動の保障をしていくという意味でも、コミュニティバスは力を発揮すると思いますし、やはりそうした地域の声を議会として受け止めていくということが必要だと思いますので、本日結論を出すということで、採択を主張しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"田中委員","kind":"質問・要望","question":"何度も申し上げますが、やはり各地域での必要性とかを、各地域の方たちが話し合える場や理解できる方法というのが必要だと思います。区民、本当にきちんと聞いてほしい、限定せずに広く聞いていただきたいと強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出してほしいと求めました。安心もいたしましたし、このまま進めていただいて、結果を出していただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"のだて委員","kind":"意見","question":"共産党としては、区民の声を受け止める議員が多くなるということも大事だと思いますので、態度をそろえるということもやぶさかではありません。趣旨採択ということでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/733618?Template=document&Id=4304#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":68195,"voices":241}},{"id":"r02-20201109-9","meetingId":"r02-cm11","date":"2020年11月9日","dateIso":"2020-11-09","committee":"文教委員会","time":"午後 １時００分～午後 ４時０６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を74件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"改めて今回の工事の目的を伺いたいのと、主に直さなくてはいけない部分は、今の第一日野小学校側のほうですね。それとも放射２号線をどうしても進めたいので、この道路をやってくれと言ったわけですから、この道路を進めたいわけです。","respondent":"小林学校施設担当課長","answer":"安全確保をするためには改修工事を行う必要があると判断して、今回、工事を進めているところです。擁壁とか、そういう工作物につきましても、そこの用地につきましては後退して工事を行うという判断をしたものです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"それだけなのですかということと、あと、道路を進めたいという区の全体の意思があるわけではないですか。今回、やっぱり売ってしまえみたいな感じになったのではないのかというところに対してもしっかりと説明をしてほしいと求めました。","respondent":"小林学校施設担当課長","answer":"４周擁壁があって、４周ともひび割れ等がありましたというところで、後退をしたです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"二重投資は避けるべきだという発言もあったので、そういう意味だけなのではないですかと私は言っているので、もう１回お答えいただきたい。伺います。","respondent":"小林学校施設担当課長、東野経理課長","answer":"１点目のほうの道路につきましては、補修ではなくて、やり替えを判断しました。これはひび割れが生じているというところで危険性があるという判断をして、補修ではなくて、やり替えをすべきという判断をとったところです。 道路用地部分の売却ですが、本年６月１８日付で売却を行っております。その上にありますトイレ、樹木等の移転に係る物件移転補償契約につきましても、同日付で締結をしています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"教育関係整備が教育委員会の仕事なわけですけれども、教育委員会としては、２割減ってしまうことの評価はどういうふうに考えているのか伺います。これは必要な措置はすべきだと思うのですけれども、そこについてお伺いします。","respondent":"東野経理課長、小林学校施設担当課長、有馬庶務課長","answer":"物件移転補償契約が、樹木、それからトイレの移転期限を令和３年３月というふうに設定しています。この時点までに更地化して都へ引き渡すということで… そちらの築造はできないということになりますので、教育委員会としては、後退をとったです。次の校庭は何を予定しているのかということで、人工芝を考えていますということもお伝えしまして、それは歓迎されているです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"意見","question":"あえてそういうところに、しかも２割もグラウンドが減るということもあって、教育環境も悪くなるわけです。補修という形でしっかりと安全性も確保しながら整備するということは私はできると思うので、ぜひそういうふうにやるべきだというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"これは、このグラウンドを内側に削る形で新たな擁壁を造るわけですけれども、そこで生まれた空地は、空地のままになるのですか。それともすぐに道路にしていくのか尋ねました。","respondent":"鈴木都市計画課長","answer":"今回の敷地も含めて、民間の方の土地の売買で提供があったところにつきましては、基本的には、東京都のほうで最終的に一括して道路状に整備をする。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"公有地から公有地ですから、最後まで子どもたちに使わせてあげたほうがメリットが大きいというのは当然のことで、そういう発想は全く出てこなかったのか尋ねました。","respondent":"小林学校施設担当課長","answer":"それを確認して調査を行い、放射２号の部分につきましては、平成３０年７月３１日に都市計画道路として指定されました。教育委員会としては、やり替え、改修工事を進めるべきと総合的に判断して後退をしたところです。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"都市計画道路内での建築物は、東京都はたしか建物で言えば、３階建てまではオーケーという緩和もされているのです。グラウンドの擁壁といった比較的小規模で、これは交渉の余地があったのではないかと思いますけれども、そういうお話は東京都とされたのか尋ねました。","respondent":"小林学校施設担当課長、鈴木都市計画課長","answer":"今のお話でいきますと、今の敷地の中で全てを解決できるのではないかというお話です。これらを考えますと、そういうところも総合的に検討はしましたが、まずはそこを重視して後退したところです。 小規模な、ご紹介いただいた３階までは、第５３条の許可という形で建築ができるです。建築基準法上の１項４号という基準法でいう道路の網もかかっているですから、検討して、こういう経緯に至ったです。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"この道路側の擁壁というのは、どの程度の危険度、どのぐらいのひび割れでしたか。それがどのくらいたくさんあったのか尋ねました。","respondent":"小林学校施設担当課長","answer":"調査をして安全性を確保するには、やり替えしかないと。そういうものも検討して、その中で総合的に判断した結果、やり替えしかないというところで判断したものです。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"この部分を何とかすれば、もう少し子どもたちに長く使ってもらえるかもしれないということで、何らかの工夫や交渉をした事実はあるのでしょうか。そういうことは何もしないままここに至っているのか尋ねました。","respondent":"小林学校施設担当課長","answer":"ただ当然、なければ、そういうところも１つの考え方としてあったのかもしれません。先ほど都市計画課長からも説明があったところですけれども、指定がされなければ、そういうところも考えられる１つの手法とは思いますが。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"そうした発想はないのでしょうか。いかがか尋ねました。","respondent":"小林学校施設担当課長","answer":"電話対応なり、出向いてお会いして説明するというところで、丁寧な説明をしたところです。その中でも近隣の住民の方から、説明会で日程が決まってしまうよりは、今回はそういう個別の対応をとったです。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"２３２世帯の中で２３件問合せがあった、こうしたものの中で１割の方から問合せがあるというのは、いかがでしょうか。なぜこういうことをしていて、どういう工事なのかということを改めて、私は行政として損はないと思うのですけれどもいかがか尋ねました。","respondent":"小林学校施設担当課長","answer":"説明会、説明会の中に大勢の人がいて、非常に勇気が要るという逆なお言葉も頂戴しています。何回も行ってご説明をしていますので、今回はそういう個別の対応をとったというところでよかったのかなと考えている所存です。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"個別の２３２世帯にビラをまいて、これからでも構いませんので、やっていったらいかがでしょうか。やるデメリットがあるのだったら説明を求めました。","respondent":"小林学校施設担当課長","answer":"そして、その中で２３２世帯にお知らせを配って、そこで問合せがありましたら対応していく。ある程度質問も来る、そういうところもやっておりますので、今回の個別対応というのは妥当だったと思っています。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"でも、いろいろなやり方があるのではないですかというお話をしているのですけれども、そんなに説明するのは嫌ですか。前向きな何かはないのか尋ねました。","respondent":"小林学校施設担当課長","answer":"予定ではこれだけですという話で、逆に、話しやすい場をつくったのかなと思っているところです。それの工事説明会を行うか行わないか、今後、いろいろなところで頑張っていきたいと考えています。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問・要望","question":"少年サッカーなどの要望も出てきておりますけれども、そして、ご理解は得ているのかということをまず確認したいと思います。","respondent":"有馬庶務課長","answer":"学校の利用団体の方、特に少年野球、サッカーの方からは、グラウンドが使えなくなるということで、学校のほうから説明をしています。こういう状況があるので、空いているところをできるだけ、近隣のほかの学校で使っていただくように調整をしています。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。その際、特にこうした工事に反対だとか、そうした強い否定のご意見とかというのはなかったということか尋ねました。","respondent":"有馬庶務課長","answer":"率直な意見として、一定期間使用できなくなるということで、困ったなというところでのご意見は承っております。もう１つは、特にそれで反対だとか何とかだという話ではなくて、そういう話が出たです。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。騒音とかで実際に被害を感じられている方のための相談窓口というか、問合せ先というのは、工事中に表示はされているのか尋ねました。","respondent":"小林学校施設担当課長","answer":"現場の道路面に、事業者の連絡先ならびに１週間の工程表等を掲示しております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"確認をしたいのですが、公有地を同じ公共団体に売るときのルールといいますか、そこら辺がどうなっているのか確認させていただきたいです。","respondent":"東野経理課長","answer":"工作物の物件移転補償契約で、こちらは２,９２０万５,６２０円となっています。物件移転という形で上に工作物等がある場合は、移転をした上で引き渡すというような形をとっているものです。","id":"exchange-018"},{"speaker":"芹澤副委員長","kind":"質問","question":"本日、結論を出すで、内容としては不採択でお願いします。子どもたちの安全性のために改修が必要で、そういったことではなくて、法的にしっかりと適切に安全性は確保してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"せお委員","kind":"意見","question":"今、お話にもあったように、既に危険であるほどのひび割れがあるということで、子どもの安全性を考えてのことであるということです。法律の縛りがあるということで、こういった陳情の内容は難しいと考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"たけうち委員","kind":"意見","question":"お考え、お気持ちは分からない部分、分かる部分もあるのですが、先ほどからお話があるとおり、安全性の確保の課題を解決しなければならない。法的な位置づけをどうするかという判断の中で、致し方ないのかと思いますので、この陳情については不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"意見","question":"売却そのものをすべきではないと思うのですけれども、売却しないでほしいという思い、趣旨採択ということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"横山委員","kind":"意見","question":"法律の部分の兼ね合いのところで判断していただいたというご答弁の中で理解いたしました。先ほど丁寧にご説明いただいているということでしたので、引き続き、丁寧なご説明を心がけていただくようにお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"芹澤副委員長","kind":"質問","question":"まず１点目に、本日の議論の中でも様々な区民に情報を伝達してほしいという話はそのとおりであると思うのですが、２３０軒近い方々へのご案内等。不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"せお委員","kind":"質問・要望","question":"どれを開くかという判断はすごく難しいと思いますので、個別に対応するということの中で、その中でもやっぱり丁寧な説明は大切だと思います。そこのところをしっかりとやっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問","question":"では、その部分を変えていくのかということになると思うのですけれども、今回についてはそこまで考える必要はないのか。個別の説明会も丁寧にやられているという状況も伺いましたので、いずれにしてもお気持ちは分かりますけれども、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択です。とりわけこの件については、周辺地域住民への丁寧な説明や説明会の開催が私は当然あるべきだと思いますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"ただし、今後もお願いしたいところでありまして、事案によっては住民説明会を開くなどもやっていただきたいと考えております。今回、説明会を開くまでの事案ではないのかと考えていますので、そうした理由で不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問・要望","question":"もう少し説明の手段ですとか、対象ですとか、もう少し広げてもいいのではないかと思います。少なくともこの件１つとっても、より広く、多くの方が工事について知られるようなことをスタンダードにしていただきたいという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]},{"id":"topic-02","title":"教育委員会に関わる報告を先に受け、子ども未来部","agenda":"教育委員会に関わる報告を先に受け、子ども未来部","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"１番の６月２９日から７月３１日というのと、２番の令和２年４月という、これはどう関わるのですか。この４月というのは何をしたのか尋ねました。","respondent":"工藤指導課長","answer":"令和２年４月以降のいわゆる月例給等給与がありますので、その給与水準は本年のものという意味で記載があるというふうに考えてあります。こういったところの調査内容を指し示すのが令和２年４月に行われたというふうに私どもは把握しているところではあります。","id":"exchange-030"},{"speaker":"あべ委員","kind":"質問","question":"ちょっとまだ理解できていないものですから、月例給については８月から９月にかけてというのは妥当な時期で、８月からという……。分かっている方にお答えいただくのが……。","respondent":"齋藤教育次長","answer":"民間との比較ということでありまして、この２に書いてあるとおり、どういった企業と比較するかの対象企業は、民間給与実態調査の内容のとおりです。","id":"exchange-031"},{"speaker":"あべ委員","kind":"確認","question":"１番のほうを詳しく教えていただいて、２番の(1)、対象企業を確定するのが４月ということなのでしょうか。今後どうなるかという情報、それともこれは年１回、その辺の見通しを説明を求めました。","respondent":"工藤指導課長","answer":"年に１回ですので、現状は年１回のものというところで、そのように認識しています。先ほどありました令和２年４月という記載は、情報がないところですので、また分かり次第ご案内させていただければというふうに思うところです。","id":"exchange-032"},{"speaker":"あべ委員","kind":"質問","question":"事業者を選定したものなのかどうかを聞きたいのではなくて、１番と２番の時期のずれ、この４月が何を意味しているのかということが知りたいのです。今はちょっと分からないということでしたら、また後ほど教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問","question":"２番の(2)の比較でいくと、民間との差が０.０８月なので、０.１０月分引下げとなっています。特別区人事委員会のほうは２３区での企業の比較、だから、こういうことでよろしいのか尋ねました。","respondent":"工藤指導課長","answer":"やはり特別区の場合は２３区だけの事業所で行っているものと、その事業所も選定されているものが違うものですから、そういった差が出ているです。これが妥結した場合に右側の０.１０月が適用されますので、本区でいきますと、固有教員と都費の教員では違っているです。","id":"exchange-034"},{"speaker":"安藤委員","kind":"確認","question":"労使の交渉状況というのはどのような感じなのかということをそれぞれ伺いたいのと、２回に分けてということで、月例のほうがまだ出ていないからということなのかという確認をしたいのが２点目です。","respondent":"工藤指導課長","answer":"昨年でいきますと、１１月２２日の未明に妥結したということがありますので、目下、来週も含めて交渉しているものというふうには認識しています。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"私は教師の専門性を向上できる環境づくりが必要だと思うのですけれども、いろいろな要素がある中で、１つがやっぱり待遇なのではないかと思うのです。教師の給料は、下げている場合ではないのではないかと思うのですけれども、そこら辺に関しては教育委員会のお考えはどうか尋ねました。","respondent":"工藤指導課長","answer":"学校教育に燃えながらしっかりと教員は勤務していますが、給与に関しましては、この仕組みによって決まっていくというところに従っていくです。","id":"exchange-036"},{"speaker":"横山委員","kind":"質問","question":"４番の給与制度における課題というところですけれども、これはどういった見直しをする必要があるということで課題として挙がっているのかを教えていただけないか尋ねました。","respondent":"工藤指導課長","answer":"東京都は現在、年２回の支給ですが、特別区におきましては３月分がありますので年３回支給されてあります。それによって東京都は２回ですので、配分もちょうど２分の１ですが、そういった見直しをする必要があるというふうに課題として指摘されているです。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"先ほどおっしゃっていましたけれども、とはいえ、やっぱりモチベーションを維持するにはなかなか現場として厳しいものもあると思います。何かフォローをする、別にお金ということだけではなくて、その必要性は感じられていないのか尋ねました。","respondent":"工藤指導課長","answer":"できるだけライフを充実させるようなというところは考えているところ、いわゆる在園時間が勤務時間を超えて長くなるようなところがないようにしていかなければいけないという認識のもと、働き方改革は進めなければいけないというふうに思ってあります。","id":"exchange-038"},{"speaker":"あべ委員","kind":"意見","question":"給与というのも１つの大きなメッセージではあると思いますけれども、それ以外に、この状況なので、なかなか公務員の社会からの見え方というのもいろいろとあるとは思いますが、声かけも含めて、様々な形で現場のモチベーションが下がらないように努力してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"その部分は、どういう形でこれまで進めてこられたのか、もう少し説明していただけますでしょうか。授業がどう変わるのだというようなところの取組みは、どういうふうに進めてきて、今どのくらいの段階に来ているのか尋ねました。","respondent":"工藤指導課長","answer":"今、研修の説明をさせていただいたところですが、これら全てが実は授業改善、授業の中での活用の部分です。今そういった説明の中では、集める、スタートカリキュラムに当たるようなものも示しながらと思っているところです。","id":"exchange-040"},{"speaker":"あべ委員","kind":"質問・要望","question":"には教育委員会としても相当な学びといいますか、準備といいますか、そこは教育委員会としてどのように考えていらっしゃいますか。体制みたいなものをつくっていらっしゃるのか尋ねました。","respondent":"工藤指導課長","answer":"優れた実践であるとか、また教員、そういったことをやはり教員のほうには情報共有も含めて進めていきたいというふうに考えているところです。","id":"exchange-041"},{"speaker":"あべ委員","kind":"質問","question":"子どもたちが家に持って帰って、家でも使って、学校でも使ってということをイメージしているのかということを１つ教えてください。それともう１つは、そこのシステムといったらいいのですか、そこのところは何か準備されているのか尋ねました。","respondent":"工藤指導課長","answer":"そういった意味では、いわゆる置き勉という学校に置いていいものという形で対応できるかというところも併せて検討していきたいところですが。","id":"exchange-042"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれども、今後、電子黒板とタブレットはどのように関連してくるのか。簡単に今後の関連のイメージをお伝えほしいと求めました。","respondent":"篠田学務課長","answer":"それから特別教室も、最終的に今年度中には全て入る予定であると、特別支援学級の教室にも全部配備が終わる予定です。タブレットが入れば、子どもたちから集めた中の良い回答を電子黒板に映すとか、引き続き活用させてほしいといったような声もいただいています。","id":"exchange-043"},{"speaker":"安藤委員","kind":"意見","question":"やっぱりそういう負担をかなりやわらげてほしいというか、どれぐらいサポートできるような体制になるのかということがまず１点です。そこら辺を知りたいと思いますとの意見を述べました。","respondent":"篠田学務課長、工藤指導課長","answer":"新たに全ての学校に１人１台の形で配備をしますので、そちらの導入に関しての支援を、調整をしています。週１回ぐらい回れればいいなということで、検討をしているところで、予算要求もしているという状況です。学校教員は進めているところですが、やはり教員一人ひとりはそういったものを授業づくりの目標にしていただきたいと思っています。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"やっぱりどうしても指摘されるのですけれども、あるいは方策というか、検討みたいなものはあるのでしょうかというのが１つです。それも伺います。","respondent":"篠田学務課長、工藤指導課長","answer":"直接的には、これから配備する予定の機械に全てブルーライトのカットフィルターを設置するというようなことで。それを今、検討していますけれども、そういったことで健康面で負担にならないような形での運用を考えているところです。家庭での活用ですけれども、ご指摘いただいたように、宿題あるいは課題が増えるというふうに考えているところは特にはございません。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこについて品川区はどういうふうに、個別最適化した学びを個々の孤立した学びにさせない視点はお持ちなのでしょうか。伺いたいと思います。","respondent":"工藤指導課長","answer":"ああいう考えもあるのかということを自分たちのグループの話し合いに活用して、先ほど来ありますように、そういった授業が可能になっていく。","id":"exchange-046"},{"speaker":"たけうち委員","kind":"質問","question":"１点、ＩＣＴ推進教員について、役割は何となく分かるのですが、役割ですとか、あと、もう全部の学校で１人とかが決まっているのかとか、人選はどういうふうにしているのかとか、あと先ほども言ったＩＣＴ研修員の方との関連、例えば連携をどうとっていくのかとか、その辺のことを説明を求めました。","respondent":"工藤指導課長","answer":"あるいは教材用パソコンを使った活用を進めていた人、あるいは、その中心となる方ということでご指名いただいているところです。ＩＣＴ支援員等との連携につきましては、ｉＰａｄが配備されたところでは、そういった連携は進めていきたいというふうに思ってあります。","id":"exchange-047"},{"speaker":"たけうち委員","kind":"質問","question":"この方が教えていくような立場になるわけなので、その辺のところで、非常に負担が重くなっていくようなことも考えられるのかと。今後、そういう方たちに対するフォローとか、そういうものはどのように教育委員会として考えているのかを説明を求めました。","respondent":"工藤指導課長","answer":"やはり活用を図るという観点で今年度指名させていただいて、今、進めているところです。推進教員の人たちが学校の中で進める上で必要な情報を常にやり取りしながら、教育委員会でしっかりと支援していきたいというふうに考えてあります。","id":"exchange-048"},{"speaker":"横山委員","kind":"質問","question":"ＩＣＴ推進教員とＩＣＴ推進リーダーという２種類が出てくるのですが、推進教員の中でリーダーがいらっしゃるというようなことなのでしょうか。２ページのところですけれども、何か現在の状況、Ｗｉ－Ｆｉの設置状況などが分かりましたら説明を求めました。","respondent":"工藤指導課長、篠田学務課長","answer":"校長会を通じまして、推進教員というのは各校１名、ＩＣＴ推進を進めるためのプロジェクトチームを校長会で教育委員会と併せて設置したところです。基本的に各学習の中では必ず使うというふうに考えておりますので、そういった意味では… さいかち学級等のＷｉ－Ｆｉの設備等に関してのお話です。基本的に今考えているのは、Ｗｉ－Ｆｉの環境整備がなかなか難しくなってまいりますので、今考えているところです。","id":"exchange-049"},{"speaker":"せお委員","kind":"質問","question":"１点お聞きしたいのですが、なかなかそこら辺、どうやって判断していくのかというところがあったのでお聞きしたいです。","respondent":"工藤指導課長","answer":"その子に合った教材であるとか、タブレットの活用は進めていければと思いますので、そういったものは今後の研修の中でも計画していきたいと考えているところです。","id":"exchange-050"},{"speaker":"芹澤副委員長","kind":"質問","question":"この３枚目のＳＮＳ学校ルール研修というもので、どの場面で教えていかれるのかということと、アプリ等はご自身で勝手に入れられるというような設定になっているのかを説明を求めました。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"５・６・７年で指導、家庭ルールということで、使用時間とか内容等のルールを決めております。学校によってはセーフティ教室、また親子スマホ教室でＳＮＳの指導をしています。個別の機械へのアプリのインストールの関係ですけれども、基本的に個々人が好き勝手に入れるような形のものは想定しておりません。","id":"exchange-051"},{"speaker":"芹澤副委員長","kind":"質問","question":"もう１点、先ほど、全ての教科で使っていくというようなお話があったと思うのですけれども、例えば体育とかでも使われるご予定があるのですか。今回、体育はちょっと別の話かもしれませんが、そういったところでもこのタブレットの活用は学校でご検討されていらっしゃるのかを説明を求めました。","respondent":"篠田学務課長、工藤指導課長","answer":"１点目のアプリのインストールに関してですけれども、児童・生徒ですとか、それはお受けしないということで考えております。あくまで学校として何かの教科でこういったものが必要だということで… そういったことはこれまで推進校のタブレットの活用の中でも行われていますし、今後それがより活用できるかと思っているところです。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問","question":"年度途中ということで、来年度以降も時数など、持ち時間を減らさずにＩＣＴ推進教員はこの業務に当たっていくということなのでしょうか。あえて聞きますけれども、手当の対象などになるかどうかということも教えてほしいと求めました。","respondent":"工藤指導課長","answer":"いわゆる校務分掌の１つというふうに私どもは考えてありますので、次年度以降につきましては、校務分掌の適正配分を学校のほうで考えていただければと思っているところです。","id":"exchange-053"},{"speaker":"あべ委員","kind":"質問","question":"そこのところの業務量の管理、あるいは推進教員だけではない推進チームとしての動かし方も必要だと思うのですが、そうした推進教員の方の負担のマネジメントはどのようにされていくのか尋ねました。","respondent":"工藤指導課長","answer":"ですので、学校の中の活用を検討する組織、いわゆるチームを学校の中に設置していただいておりますので、あくまでもその中心であるという扱い。その教員だけに任せるようなことがないように、学校のほうには指導していきたいと思いますし、私どもも支援したいと考えています。","id":"exchange-054"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"すごくいい試みだと思うのですけれども、やはりご自宅で自由に見られない環境の方も少数ですがいらっしゃると思うのです。例えば、この期間中に視聴できるとか、何かそういう見られない環境の方をフォローするアイデアみたいなものはありますか尋ねました。","respondent":"有馬庶務課長","answer":"希望者があれば、１１月２０日の収録日に講堂でも、各ＰＴＡの会長を中心に数名なら大丈夫ですということで意見を伺っているです。ＵＲＬを一斉メールしますので、それで見ていただく方は増えるのではないかと思いますので、今回はこれでやらせていただきます。","id":"exchange-055"},{"speaker":"あべ委員","kind":"意見","question":"各校何人と割当が来て、交通費をもらって行くというような感じだったと思いますので、これはオンライン開催というだけでもかなり前進だと思います。いろいろと工夫をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"横山委員","kind":"質問","question":"これの所要時間はどのくらいなのでしょうか。質問ですとか、アンケートですとか、そういったところはどういうふうな運用でやられるのかを説明を求めました。","respondent":"有馬庶務課長","answer":"基本的に時間はいつもは１時間半とか、おおむね、７０分程度お話ししていただける予定です。うまくすれば、あとで配信するときには速度を少し変えて１.２５倍とか、見る方はちょっと工夫していただければというふうに考えております。","id":"exchange-057"},{"speaker":"芹澤副委員長","kind":"質問","question":"細かいところなのですが、「手話通訳があります」と一番下に書いてあって、必要だと思うのですけれども、ＹｏｕＴｕｂｅは、変な設定をしなければ、基本的に字幕もついているようなイメージがあるのですが、字幕も併用して使っていただけるような動画になる予定なのか尋ねました。","respondent":"有馬庶務課長","answer":"字幕は最終の確認はとれておりません。","id":"exchange-058"}]},{"id":"topic-05","title":"に戻りまして、(2)旧第一日野小学校跡地を活用した区立保育園・児童センター等の改築","agenda":"に戻りまして、(2)旧第一日野小学校跡地を活用した区立保育園・児童センター等の改築","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"１３年間、住民要望のために使用するのが基本なのではないかというふうに考えているところですが、一方で。伺いますけれども、機会を逃すとかなり困難になるというご説明もありましたけれども、検討をしたのかどうか伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"保育園の建て替えにつきましては、この近辺の保育園の建て替えの元として使えないかということで検討してきたところです。現在、この間の検討の中で、第一日野小学校跡地が、暫定活用の中で使えるという話になったことから、こちらを使わせていただく次第です。","id":"exchange-059"},{"speaker":"安藤委員","kind":"確認","question":"分かれば、これは資料には２０２６年以後に「解体」という文字がないのですけれども、これはさらに使い続けるというお考えなのでしょうか。それも伺います。","respondent":"吉田保育施設調整担当課長、若生保育支援課長","answer":"ここ以外の施設を建て替えについて検討したかですが、保育園の建替用地がないと、建て替えのための用地が出てこないと建て替えはできません。それから２０２８年以降ですが、暫定活用期間までしか現在検討しておりません。 オアシスルーム・ポップンルームのほうです。今後の全庁的な検討も含めた動向については、まだ検討中ですので、私のほうからの答弁は差し控えします。","id":"exchange-060"},{"speaker":"安藤委員","kind":"確認","question":"それは現時点でどのようなものを考えていらっしゃるのでしょうか。それぞれの平米数、それぞれの建物の敷地面積の平米数、あるいは延べ床面積、どれぐらいと考えているのか伺います。","respondent":"吉田保育施設調整担当課長","answer":"２０２８年以降の保育園のというお話ですけれども、暫定活用後につきましては、保育園の利用については決まっていないです。それから、施設の平米数についてということですけれども、まだ基本設計の段階ですので、細かいところは決まっていないところです。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"「解体」という文字が間違いなのかどうか、そこら辺がちょっと分かりませんので、もう一度お伺いします。伺います。","respondent":"吉田保育施設調整担当課長","answer":"その間で建て替える予定としては２年の改築を予定しておりますので、２年の改築後は解体するというところまで考えているところです。それから、こちらの用地の全体の使用方法につきましては、私からの答弁は差し控えします。","id":"exchange-062"},{"speaker":"あべ委員","kind":"質問","question":"まず１つ、このオアシスルームの立地がこちらに移ってくることによって、荏原地域のバランスがどうなるのかというのを教えてほしいと求めました。それから保育園ですけれども、現状と同じ規模しかあり得ないのか、それとも少し定員を増やすようなことも検討されるのか説明を求めました。","respondent":"若生保育支援課長、吉田保育施設調整担当課長","answer":"荏原地区は、現在、荏原保健センター内オアシスルーム以外には、２年前に開設した平塚ゆうゆうプラザのオアシスルームがあります。若干遠くなるのですが、旧第一日野小学校跡地に確保いたしまして… 保育園の建て替え後の規模ですけれども、来年度から基本設計を進めていく予定です。そのため、その中でどのぐらいの建物が建てられるのかとか、その辺の検討をした上で、また考えてまいるところです。","id":"exchange-063"},{"speaker":"あべ委員","kind":"質問・要望","question":"今の定員にとらわれることなく、移転後の定員に合わせた形でこの規模をつくってほしいと求めましたが、その考えについてお伺いしたいと思います。この２つの、つまり複合施設のほうと、保育園の建物、それを除いた敷地的な余裕はどの程度あるかというのは把握されていますか。","respondent":"吉田保育施設調整担当課長","answer":"建て替えで戻ってきた際に定員を増やすということにつきましては、また保育需要等を鑑みながら検討していくところだと考えております。ちょっとまだ検討としては早いというところと、現在の敷地の面積で、建て替えのための土地を確保することを検討してきたところです。","id":"exchange-064"},{"speaker":"あべ委員","kind":"質問","question":"１つお願いしたいのが、やはり保育園について、距離が遠くなってしまうご家庭がかなり出るのではないかと思います。いかがか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"今後の基本設計を進めていく中で、検討して、どの辺までできるのかは、また調整、検討をしてまいりたいと思います。","id":"exchange-065"},{"speaker":"たけうち委員","kind":"質問","question":"大体東五反田と同じぐらい、数百ｍ、１１分ぐらいと考えていればいいのですか。抜けているのか、あえて抜いているのかちょっと分からないですけれども、分かりますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"せお委員","kind":"質問","question":"２点お聞きしたいのですけれども、貸付が令和４年９月に終了するとあるのですけれども、これが早まることはあるのですかというのが１点です。今いらっしゃる方と、これから２０２１年に入られる方への説明は、どのような感じになっているのか尋ねました。","respondent":"吉田保育施設調整担当課長、立木保育課長","answer":"そのために、１１月４日に在園児の保護者向けに、１１月２５日に中原保育園で保護者説明会を行う旨は周知したところです。東五反田保育園の説明会につきましては、１１月２７日を予定しています。 これから入園を希望される方に関しましては、窓口のほうで、今後こういった計画がありますということで、別紙で用意いたしまして、ご希望されて入った後に知らなかったということがないように説明をしています。","id":"exchange-067"},{"speaker":"せお委員","kind":"意見","question":"失礼しました。対応した職員で言うことが異ならないように、一貫した説明をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"}]},{"id":"topic-06","title":"医師・看護師の保育園入園選考における調整指数加点","agenda":"医師・看護師の保育園入園選考における調整指数加点","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"何かそういうものが出たりとかというような状況はあるのでしょうかということと、ほかの自治体の状況とか、分かる範囲でいいですけれども説明を求めました。","respondent":"立木保育課長","answer":"国からの通知は、その後も特に出ておりませんので、前と状況は変わってございません。平塚市で優先利用という形でやっているということで、特別区、東京都下には今のところ話を聞いているところはございません。","id":"exchange-069"},{"speaker":"あべ委員","kind":"確認","question":"一応確認ですけれども、その医師の配偶者の職業は問わないということですね。もちろん保育園ですから、加点ですし、必ずということではないと思いますけれども、１点そこを確認します。","respondent":"立木保育課長","answer":"委員おっしゃるとおり、どちらかが医療従事者であれば１点加点という形をとらせていただきます。","id":"exchange-070"},{"speaker":"あべ委員","kind":"質問","question":"このことについて、なぜ対象にならないのかと、自分たちは相対的に入りにくくなってしまうのではないかというご相談をいただいております。とりあえずはこの４月だけということなのか、どういう形でご判断をされる考えなのか、その辺はどのように考えていらっしゃいますか尋ねました。","respondent":"立木保育課長","answer":"医療提供体制の逼迫というところを１つキーワードにいたしまして、接触するというところで、医師・看護師に注目をさせていただいたという次第です。","id":"exchange-071"},{"speaker":"あべ委員","kind":"意見","question":"となると、やっぱりある程度の期間になるかというふうに思います。推移を見ながら、また状況が変われば、これについては改めて見直しも考えてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"},{"speaker":"たけうち委員","kind":"質問","question":"その１点の効果というか、１点ぐらいではと思う部分もある中で、１点でこれぐらいということが分かれば説明を求めました。","respondent":"立木保育課長","answer":"もう既に制度として保育士は１点加点ということでやっておりますが、今回、令和２年４月の申込みで保育士加点になった方が５５名いらっしゃいました。","id":"exchange-073"},{"speaker":"たけうち委員","kind":"質問・要望","question":"医療提供体制を確保するという観点で絞ったのだということを丁寧にお答えいただきたいのと、いわゆる１点が活きて逆転して内定したというところまでは多分つかめていないのだと思いますので、ありがとうあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=5016#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":54020,"voices":190}},{"id":"r02-20201109-5","meetingId":"r02-cm11","date":"2020年11月9日","dateIso":"2020-11-09","committee":"総務委員会","time":"午後 １時００分～午後 ２時４０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"議事運営の関係上、取り上げる順番を変更し、初めに(3)ふるさと納税（寄附金）に係る体験型返礼品の追加","agenda":"議事運営の関係上、取り上げる順番を変更し、初めに(3)ふるさと納税（寄附金）に係る体験型返礼品の追加","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"資料にも５番目として書いてありますけれども、５万円以上で、どうなのでしょうか。対策として可能なのか尋ねました。","respondent":"伊東税務課長","answer":"銘板ですとか、品物、ふるさと納税という中での何かということはなかなか難しいものがあるのかなと考えています。この制度下では、ちょっと難しいかなと考えています。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問・要望","question":"まして、これから１年半後、品川区もより厳しい状況を迎えてくるようならば、何か抜本的な対策をしていただきたいと私は思います。これについて答弁してくれとか、そういうのではなくて、意見として検討していただきたいということを申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"それなりにお値段というのですか、そういうメニューの中で違いがあるのかが１点と、まず説明を求めました。","respondent":"伊東税務課長","answer":"１５分から１２０分という形になっていまして、今回想定したのが３０分というところで、一般的には１万２,０００円かかるです。６,０００円から１８万円までのコースが用意されていると聞いております。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"５万円の寄附を頂いた場合、これぐらいの支出をしても、５万円の寄附金額に対する妥当の支出だと判断されたということでよろしいのでしょうか。ここまで行くのにどういう手段がありますとか、そういうご案内とかは、これを選ばれた方には別途ご案内があるのか尋ねました。","respondent":"伊東税務課長","answer":"品川駅もしくは大崎駅から徒歩１０分、１５分程度と記載されておりますので、そんなに不便ではないのかと。その辺は当然周知していきます。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"区役所の隣のスポル品川のサーフィンですか、スポル品川自体がなくなってしまう施設なので、私は個人的に貴重なのかなという感じなのです。そういった中で、品川区にはどういう体験型があるのかという、何かそういう経緯がもし分かれば教えていただけますか。","respondent":"伊東税務課長","answer":"さっきもちょっとお話ししたとおり、珍しい施設がたまたま区内にあったというところで、返礼品としたところです。そういうのも考えていたところですけれども、来年以降と考えていたところでございまして、そういう人的な部分も含めまして選定させていただいたです。","id":"exchange-005"},{"speaker":"湯澤委員","kind":"質問・要望","question":"その中で、こちらは何名、１人ということなのでしょうか。万が一、自分がどうしても急遽行けなくなってしまったとき、日程の変更とかができるかというのがもし分かれば教えてほしいと求めました。","respondent":"伊東税務課長","answer":"第一希望を取れないこともあろうかと思いますので、変更も可能で、それは直接やり取りしていただくことになります。そういうことで東急側のＰＲ媒体がいろいろあるということもありまして、今、ふるさとチョイスと東急ふるさとパレットと２つ契約している状況です。","id":"exchange-006"},{"speaker":"湯澤委員","kind":"質問","question":"ご質問させていただきましたけれども、１人だけなら１人でいいけれども、そういったことは多分気になると思います。日程変更も常識の範疇で可とか、そういう感じで、返礼品として載せるときには、そういうことも一言添えるといいのかなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"再度確認させてほしいと求めました。優先的に取ることが、品川区と事業者の中でそういうところまで契約の中にあるのかというところを教えてほしいと求めました。","respondent":"伊東税務課長","answer":"それと、優先予約という形までは交渉できていないという状況です。先着ではないですけれども、一般予約と同じように、お客さんと会社の間でやっていただくものです。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"不動産屋だったら徒歩１０分と当然書きますが、やはり、ちょっと不便なのです。それについては意見でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"１件だけなのですけれども、特にふるさと納税に対する対応策とか、そういうことを考えるチームを企画や財政の部署で作るお考えはないのですか。それとも今後、そういうチームを作ろうというお考えはあるのか尋ねました。","respondent":"佐藤企画調整課長","answer":"企画調整課内で、ネーミングライツも含めて、様々な形の歳入確保については常日頃から検討して、調査・分析しています。歳入は二十数億円、ふるさと納税に持っていかれている現状もありますので、またさらに積極的に検討を進めていきたいと考えております。","id":"exchange-010"}]},{"id":"topic-02","title":"ＥＳＧ債購入に伴う投資表明","agenda":"ＥＳＧ債購入に伴う投資表明","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"新たな債券を購入したいという報告でありますが、運用方針にもある安全性を最優先にというところを確認させてほしいと求めました。つまり、元本の保証はあるのか、元本割れの危険はないのか、安全性についてご説明を頂きたいと思います。","respondent":"中山会計管理者","answer":"安全性についてのご質問です。ムーディーズとかの投資格付でもＡプラスということで、国債と同様の格付がされているものです。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"ということは、今、中塚委員が質問したように、債券ですから、預貯金とはちょっと訳が違うので必ずしも安全とは言い切れないわけです。１０月に発行しているこの債券ですけれども、債券なので危険がある以上は慎重にやってほしいと私は思うのですが、ご見解を説明を求めました。","respondent":"中山会計管理者","answer":"品川区公金管理運用方針には、購入できる債券としまして、国債、政府保証債、政府関係機関債、そして地方債ということになっております。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"繰り返しますけれども、東京都とは切り離されているとしか考えられないのです。いろいろな意味で、経済状況が不安定なときなので、私は慎重に対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"特別区、他区はどういう状況になっているのか分かれば教えていただきたいのと、ホームページで公表すると説明がありました。環境というのは結構大きく公表するのかどうか、分かりやすく公表するのかどうかということがどうなっているのか、教えてほしいと求めました。","respondent":"中山会計管理者","answer":"今回は、５年物が１００億円、３０年物が１００億円ということになっていますが、２３区が購入する場合、５年物のほうにどの区もなろうかと思います。運用効率を第一に考えながらも、ＳＤＧｓ債、ＥＳＧ債を活用していくという簡単なコメントみたいなものになってあります。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"できたら、もう少し具体的にどんなものに対して充当するというのが分かるといいと思うのですが、それは公表されていないのでしょうか。説明を求めました。","respondent":"中山会計管理者","answer":"東京都のホームページの中にグリーンボンドの発行方針というのがあります。なので、東京都のリンクを張るかどうかということになろうかと思いますが、ちょっと考えさせていただければと思います。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区として独自に情報を出すのかはご判断ほしいと求めましたが、本当にそれが環境対策になっているのかということまで追求したいと思うのです。これは要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"２点お伺いいたします。本当であればＳＤＧｓの取組というような１つのコンテンツがあって、今後、そこもぜひご検討ほしいと求めました。","respondent":"中山会計管理者、佐藤企画調整課長","answer":"私のほうは、２点頂いたうちの最初の資金の件についてご説明いたします。今回、東京都のグリーンボンドはすごく人気が高かったので、実際のところはやっと１億円購入できたというところが現状です。ＳＤＧｓの達成にも資するものと考えています」と書いておりますので、区としてはそういった考え方で今後取り組んでいくところです。","id":"exchange-017"}]},{"id":"topic-03","title":"所管事務調査、シビックテック","agenda":"所管事務調査、シビックテック","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"今回のシビックテックを使ってその人たちをカバーできるような仕組みとか対策とか、そういうのはお考えなのでしょうか。どうしても今、問題点を現地に行って確認するというのが基本の考え方だと思うのですが、その辺についてどのようにお考えか尋ねました。","respondent":"山本情報推進課長","answer":"要望等も聞きながら、いろいろお答えするということは、これからも継続して行うというところです。その分、デジタル技術を活用できない高齢者の方への対応等を充実していく、そういった形で進めていければいいなと考えているところです。","id":"exchange-018"},{"speaker":"須貝委員","kind":"確認","question":"接触確認アプリＣＯＣＯＡというアプリが出て、これが普及すればいいのですけれども、思ったより普及しないという問題も生まれていると思うのです。問題点も多いのかなと思うのですが、もう一度、その辺についてのお考えを説明を求めました。","respondent":"山本情報推進課長","answer":"それに限らず、もちろんサービス自体が区民視点に立って使いやすいものではなければならないというのが１点あると思っています。安定して継続して運用していくためには様々な課題があるというところで、どういった支援ができるか、考えていきたいと思っています。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後ですが、やはり弱者といいますか、どうしても手助けしなければいけないというところ、それは区だけの問題ではなくて、周りの地域の支援も必要かと思うのですが、その辺も十分加味しながら、慎重に進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、町会の若手に声を下ろさないといけないのですけれども、町会には若手がなかなか集まっていないという現状があります。区として、なかなか町会と触れ合わない方にこのシビックテックを周知する方法というかやり方というか、何かお考えはあるのか尋ねました。","respondent":"山本情報推進課長","answer":"町会との関係というところで、その取り込むためにシビックテックをどう活用していくかというような議論もあったりするところになっています。町会にどうアプローチしていくのか、また、区もどう入っていくのかというところは検討していく必要があるかなと考えているところです。","id":"exchange-021"},{"speaker":"湯澤委員","kind":"質問・要望","question":"どうしても人数があまり集まらないとか、１００種類ぐらいの情報を公開して、その多くを一般公開していただきたいなと考えています。これは意見として出したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"品川区も今、コロナ禍でイベントは当然できないのですけれども、来年、次年度とか、もしあるのだったら、いろいろイベントがあるではないですか。五反田バレーの人たちもどういう考え方で、五反田バレーの人との意見交換の中でどういう意見が出たのかということだけ教えてほしいと求めました。","respondent":"山本情報推進課長","answer":"今、様々な事業面でシビックテックとの連携をどう図っていくことができるかというのは考えていきたいと考えているところです。実際、それぞれどういった活動をしているのかとか、具体的にどう進めていけばいいかというところまではまだ話合いができていないところです。","id":"exchange-023"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"特に五反田バレーの人たちというのは、すごく若い、いろいろな発想があると思うのです。そういうところの意見も取り入れながら、また観光面でもこれから活用方法をいろいろ検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"１１月２０日にリニューアルされるということですけれども、具体的に夜中の１２時前後に切り替わるのか、もちろん真っ昼間ということはないとは思うのだけれども、その辺について、補足で説明していただけますかとの意見を述べました。","respondent":"大澤広報広聴課長","answer":"朝の８時半から９時の間に新しいページに切り替わります。","id":"exchange-025"}]},{"id":"topic-05","title":"では次に、(2)水辺のライトアップ整備工事（アイル橋）請負契約","agenda":"では次に、(2)水辺のライトアップ整備工事（アイル橋）請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"２社が辞退ということで、「辞退理由：３」のほうは、配置予定技術者の配置ができなくなった具体的な理由をご存じだったら教えてほしいと求めました。","respondent":"東野経理課長","answer":"応募いただいた３社につきましては、これらの配置について、申込み時点では配置が可能だったと思われます。そういった段階で、専任の監理技術者の配置ができなくなったということはありますので、そういったことが原因と思われます。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"詳しくないのですが、企業の中でそういう技術者がいらっしゃるのだけれども、その企業の中で幾つか工事が重なってしまって、そういう人を必要とする工事を同時期にはできないということで、そういう判断をされたという理解でよろしいか尋ねました。","respondent":"東野経理課長","answer":"監理技術者も様々いらっしゃるのですけれども、専任のとなりますと、その工事の期間は縛られるようなことになりますので、ほかの工事と重なった場合につきましては配置ができないというようなことも考えられます。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"意見だけ述べさせていただきたいのですけれども、どちらが多いとは言いませんけれども、両方の声を伺うのです。地元に住んでいる方は自分たちで納めた税金ですから様々な思いがあるのかなと聞いてはいるのですが、ただ、今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"私も聞きたいのですが、水辺のライトアップ整備工事（アイル橋）ですけれども、この工事では何か特殊技術が必要なのでしょうか。その辺、もし分かれば説明を求めました。","respondent":"東野経理課長","answer":"特に特殊技術が必要ということではありません。そうしますと、大体Ａクラスの業者というのが３９社おりますので、特にこれといって特殊な技術が必要というところではないものです。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"３社だけで、特段特殊技術が必要のないこういう工事に、何で品川区ではもっと多くの業者が入札に参加できないのですか。こういう入札に参加してもらう、そういう努力も必要だと思うのですが、いかがか尋ねました。","respondent":"東野経理課長","answer":"１億２,０００万円を超えるような案件ですので、そういったところでの条件という部分はどうしても出てくるのかなと思います。その中でも３社応募いただいたということで、入札としては十分成り立っている案件だと考えております。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問・要望","question":"逆の見方をすれば、本当に一部の人たちだけでやっているようにさえ感じてしまう。やはりここは何か改善していただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"新妻副委員長","kind":"質問","question":"よろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"須貝委員","kind":"意見","question":"それが特別区人事委員会で精査して民間事業所を調査したら、民間と公務員の特別給の差は０.０５か月しかないと。こんなに格差があっていいのかというぐらい、格差の桁が離れていると思うのですが、その辺について課長としてはどのように思われますかとの意見を述べました。","respondent":"黒田人事課長","answer":"令和元年８月から令和２年１月までの支給月数と、令和２年２月から７月までの月数を調査して、０.０５月の格差があるという調査結果です。これは毎年度同じような方式で調査をしている中で、そういった結果が出ているというものです。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"これから１２月に支給されるわけですが、税金を納めていて、非常に不信感を抱いてしまうと思うのです。同じ答弁になるのかと思うのですが、これでいいのでしょうかと思うので、ご見解を説明を求めました。","respondent":"黒田人事課長","answer":"事業所規模５０人以上の事業所を、現時点での経済状況がダイレクトに反映されるという仕組みではありませんが、このような結果が出たのかと思ってあります。","id":"exchange-034"},{"speaker":"湯澤委員","kind":"質問","question":"額にしてみたら２万円ということでありますけれども、その２万円というのが、大変大きく感じる方なんかもいらっしゃると思います。今回、ぜひ職員の方々がご納得できるようなきちんとした説明をされたほうがいいのではないかなと思いますが、その辺に関してはいかがか尋ねました。","respondent":"黒田人事課長","answer":"まず一義的に認識しなければならないというところでありますので、情勢適応の原則、そういったところを公務員として意識して仕事に当たるべきです。委員からご指摘ありましたところも含めて、職員には意識の醸成をしていきたいと思ってあります。","id":"exchange-035"},{"speaker":"湯澤委員","kind":"意見","question":"品川区の職員の皆さん、本当にこのコロナ禍においても頑張っていただいていると思うので、これからもしっかりと頑張れるような、気持ちの上でも、気を落とす、そういったことがないようにしていただければと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"調査数は１,１０７民間事業所ということなのですが、これは区内でいうと、パーセントといいますか、どれぐらいに当たるのですか。要するに、一般的なところの調査なのかということを把握したいと思って伺うのですけれども、いかがか尋ねました。","respondent":"黒田人事課長","answer":"特別区人事委員会の資料によれば、対象事業所が９,８６９事業所ありまして、その中から無作為抽出で１,１０７事業所を抽出したです。企業の中から一定程度、特別区内に存在する事業所の中の標準的なところを、特別区人事委員会が国の人事院と共同して調査しているです。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"課長としてもどうしようもないところでもあると思うのですけれども、どうこう言えるものではないと思うのですけれども、今後の課題かと思います。何か今後のことで、例えば庁内でこういうことについての議論があれば教えていただきたいと思うのですが、いかがか尋ねました。","respondent":"黒田人事課長","answer":"いわゆる２３区全体のということで、法令に基づいて給与の算定の仕組みがありますので、そういった決まりの中できちんと仕事をしていくというのが重要であると考えております。","id":"exchange-038"},{"speaker":"吉田委員","kind":"意見","question":"それはもちろん議会の中でも考えていかなければいけないことだと思いますけれども、みんなで議論していく必要があるのではないかなと思います。最後のほうは私の感想ですけれども、以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2182#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":29235,"voices":98}},{"id":"r02-20201110-14","meetingId":"r02-cm11","date":"2020年11月10日","dateIso":"2020-11-10","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時２３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"それから一般質問などでも私は質問してきたのですけれども、そういう公的なものに使ってほしいという要望がこの１０年間ずっとあったところです。本当は私などは要望どおり、この３つのもので、それぞれ敷地面積の何m2ほど使うのか尋ねました。","respondent":"佐藤企画調整課長","answer":"健康センターも５００m2程度で、その辺で５,０００m2弱は施設として使うというところで、５,０００m2弱を今のところ使う予定です。ちなみに現行のテーオーシーの建物は３,７００m2ですので、今より大分使うようなことを今計画しております。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"もし余っているようなら、ほかに何かに使えるのではないかと。例えば公園であったり、もう少し使いようがあるのではないかとお尋ねしようと思ったのですけれども、念のためその点はいかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"ぎりぎりと言いましても、若干施設と施設の間はそれなりに間を空けなければいけませんので、その辺のスペースは出ます。地域の集まりに使うとかいう場合には、本格的に何かまた新しいものを建てるというのはちょっと厳しいと考えています。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"それは、荏原複合施設は令和８年度までで、それから保育園２つに関しては令和１０年度までですけれども、だから２年間のずれがあるのですが、その残り２年間に関しても同様な感じなのか尋ねました。","respondent":"佐藤企画調整課長","answer":"暫定活用の関係ですけれども、それぞれの施設を改修・改築して、速やかに戻るというところで積み上げていった結果のスケジュールになっております。","id":"exchange-003"},{"speaker":"おくの委員","kind":"意見","question":"そうしますと、これらの３つの施設がなくなった後に本格活用ということになるのだと思うのですけれども、まず本格活用をお考えなのか。それから、その本格活用ということになると、その中身についてどういうことをお考えなのかとの意見を述べました。","respondent":"佐藤企画調整課長","answer":"当然暫定施設ですので、それが本来の目的を達してそれぞれの施設に戻った場合は、本格活用は当然区として検討して、本格活用するです。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"その本格活用の中身についてどういうことをお考えなのか尋ねました。","respondent":"佐藤企画調整課長","answer":"本格活用の中身なのですけれども、大変申し訳ないのですが、まだ時間があるというのと、それまでの間に様々な行政需要ももしかしたら変わる可能性もありますので、今後またじっくりとたたき台等を検討していきたいと考えております。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"その本格活用について今後考えるということなのですが、それではいつ頃からどういう形で考えていくということなのでしょうか。いつ頃から検討を始められる予定なのか尋ねました。","respondent":"佐藤企画調整課長","answer":"本日この時点でいつ頃かというのは特にまだ決まっていないところではありますけれども、当然期間が決まっていますので、それまでに間に合わせるように適切なタイミングで検討し、また議会に報告していきたいと考えております。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"例えば、先ほど保育園、特養ホーム、公園などが非常に有力な候補として地元のアンケートからは上がっているのだということを申し上げましたけれども、例えば特養ホームの建設ということになりましたならば、例えばの話ですけれども、どのぐらい前から検討が必要なのか尋ねました。","respondent":"佐藤企画調整課長","answer":"それなりに一定の検討と調整の必要があると思いますので、一概にここで例えば５年です、そこから逆算して適切な対応を考えていきたいと考えています。現時点ではちょっといつからというのはなかなか言いにくいです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そうしますと、この後は本格活用ということで、それまでに検討して本格活用をしていくのだということで確認させていただいていいでしょうか。これは１０年近く前だと思うのですが、区としてはこの施設はいつどういう形で建替えだったり改修をするかというのは、全部できているのか尋ねました。","respondent":"佐藤企画調整課長","answer":"今現在暫定で使って、もう一回暫定というは考えておりませんので、必然的に本格的になるのだろうと今現在は考えております。２点目の築年数等々、まず土地ありきの面があるので、具体的な計画というのは今のところ区のほうで作成しているものはないということです。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"逆に延長してでも、そういう場所があったら有効に使っていただいて、対応していただきたいと私は思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今の時点でのこういう計画がされているものの一覧表みたいなものはあるのでしょうか。では、どういうふうにしてその建替えを区として考えられているのか、今後の見通しというか方向性についても改めて伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"１点目の計画化のところですけれども、ご報告していないものに関しましては計画化がないです。２点目といたしまして、日常的に検討はしているところではありますが、新しく出てきた用地があればその都度対応していくというところが現状です。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"今回、６月の行財政改革特別委員会で出されていたのが４件あって、今の検討状況などがどうなっているのかということをご説明いただけたらと思います。今は区内にある公有地の中で、元芝アパートですとか、あと小山台住宅の建設の進捗状況をご説明いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/988746?Template=document&Id=6098#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":6742,"voices":29}},{"id":"r02-20201111-18","meetingId":"r02-cm11","date":"2020年11月11日","dateIso":"2020-11-11","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時４１分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"渡部副委員長","kind":"提案","question":"廃プラ・ＣＯ２削減、委員の皆様にはそれに対するご意見や積極的なご提案をいただいて、活発な議論をしていきたいと考えております。理事者よりご説明をお願いいたしますとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長、提坂環境課長、工藤品川区清掃事務所長","answer":"私からは、東京２０２０大会における持続可能性の取り組みについてご説明申し上げます。情報発信の主な取り組みですが… マイボトルを持参した方のための給水可能な給水スポットの設置ですとか、区の庁舎や区有施設等でも設置ができないかを検討してまいります。… みんなのメダルプロジェクト」が、大会組織委員会主催で平成２９年度から２年間実施されました。","id":"exchange-001"},{"speaker":"渡部副委員長","kind":"提案","question":"今期の委員会では、委員・理事者間の質疑応答にとどまらず、委員の皆様同士での活発な討議を中心にして進めていきたいと考えております。ぜひ積極的にご意見・ご提案等をほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"幾つか伺いたいのですが、このそれぞれのテーマについての品川区としての取り組みを幾つかご紹介いただけたらと考えています。これだけでは抜本的なペットボトル削減は達成できないと思うのですけれども、そこら辺についてのお考えはいかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長、提坂環境課長","answer":"こちらの主な取り組みの中の資源管理というところに、再利用するということを組織委員会で進めておりまして、区としても希望を出しています。大気・水・緑・生物多様性等というところでは… 先ほどご説明したとおり、あと周辺自治体などと情報を共有しながら、機会を捉えて要望を出していきたいと考えています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"このリユース食器の使用を広げていただきたいということについていかがでしょうか。展示計画の２番目のところがどういう内容なのかちょっと分かりづらいので、内容を少し知りたいので伺わせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"渡部副委員長","kind":"質問","question":"安藤委員、詳細については総務委員会、今回はあくまでもこの環境の取り組みという中でのご質問に対してお答えするということでよろしいでしょうか。その範囲で答弁をお願いいたします。","respondent":"提坂環境課長","answer":"来年度検討してまいりますというのは、例えば助成ができるかどうかとか、そういうことを検討しています。１日、そういう常設展示を行いまして、環境に対する意識を高めていただきたい。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、さらに様々な場面で使えるような制度を練り上げていっていただければという要望です。伺いたいのは、市民社会の見解も含めて視野を広く持って展示内容を考えていく必要があるのではないかと思うのですけれども、それはいかがか尋ねました。","respondent":"提坂環境課長","answer":"２０１３年度比の国の削減目標が２６％減ということでございまして、東京都が３８％減、品川区が４０％減ということで目標を定めてあります。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"それはそうなのですけれども、何でそうなっているのかというその要因について区がどう考えているのか、伺いたい。今後の方向性についての区のお考えを伺いたいのですが、この目標というのはどこに置いているのか、伺いたいと思います。","respondent":"工藤品川区清掃事務所長","answer":"それと、２点目のご質問の今後の考え方ですが、また集団回収をしながら地域の中でもコミュニケーションが果たされるというところがあります。私どもとしましてはやはりこの事業はしっかりと進めてまいるというのが考え方です。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"順次お伺いをしていきます。具体的にどうされているか、お聞きします。","respondent":"工藤品川区清掃事務所長","answer":"その認定事業者が選別等を行いまして、一定の中間処理を行いまして、それからいろいろと希少金属を取り出すような事業者があります。そういった中で、レアメタルとして取り出され、もう一度製品の中で活用されているというのが現状です。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。では、その後はその民間の事業者に行って、あまりにも活用方法が多岐にわたるので、区としてはそこまで細かく追えないということか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"実際、区としてこのようなものになったというところにはなかなかならないわけなのですけれども、私どもが確実にそういった形で認定事業者のほうに渡しておりますので、そういった中で有用な貴金属として、様々な製品等の部品に供給されているです。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"集団回収事業で、一方で、やはりインターネット通信販売とかで注文した物を梱包している段ボールが増えてきているということなのでしょうか。何かそのあたりの分析というのはされているのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"私どもも同様に考えてございまして、やはりインターネット通信販売の影響といった中で、本当に今かなりの量が出ているような状況です。今年になりましてコロナの影響で、いろいろとその辺の動きが一層加速されておりまして、量的にも増加しているような傾向になってあります。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問・要望","question":"ですから、どうせ今後作られるのでしたら、もう少しかなり機能的に持ち運びできるものにしていただきたいということを思っております。区民の方も使いやすいかと思うのですけれども、そうした今後のオリジナルエコバッグの在り方についてどのようにお考えなのかを説明を求めました。","respondent":"提坂環境課長","answer":"折りたたむというよりも、メインのバッグとしても使っていただけるように、ちょっとかわいらしいデザインのものを考えて作らせていただきました。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"次回はコンパクトに持ち運びできるようなものにしてほしいと求めましたので、ぜひご検討のほどよろしくお願いします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"3)の普及啓発事業の中で、どのような啓発がされているのかといったところが分かれば教えてほしいと求めました。来年度のこの中止の判断というのは、感染症が今また広がってきている中で、どのように判断されるのかというところを伺いたいと思います。","respondent":"提坂環境課長","answer":"好評であれば、今後庁舎とか区有施設に導入できないかとか、そういうことを改めて検討してまいりたいということでここに記載させていただきました。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"感染症の広がりからの、区としての判断基準は特に設けていないということでよろしかったでしょうか。そこのところをお伺いいたします。","respondent":"提坂環境課長、工藤品川区清掃事務所長","answer":"食べ物を大切にしようとか物を大切にしよう、それが地球がいつまでも元気でいられるとか、そういうような趣旨のものを作っているかと考えています。ＥＣＯフェスティバルについては、状況が日々変わっておりますので… 給水スポットの件ですけれども、イベント会場でのモデル的な実施を見まして、今後展開できるかどうかということを検討してまいりたいと思ってあります。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"これも換気はどうなるのだろうといったところが少し気になりました。要望も入るのですけれども、参加された方、そういったイメージをちょっとお知らせほしいと求めました。","respondent":"提坂環境課長","answer":"当然ながら換気については十分配慮しながら来場者の方に利用していただきたいと考えてございまして、あと、密を避けるような形で考えてあります。１年、１０年、お子さんにも分かりやすいような展示を考えてあります。","id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"この環境に配慮したというところをやはりその出店者側にも求めていってほしいと思いますので、そこら辺の強化もぜひお願いしたいと考えています。例えば１００円均一ショップに行くと、この有料化になったことで、品川区がどう受け止めているのかというところを少しお伺いしたいと思っています。","respondent":"提坂環境課長","answer":"は２年後に環境学習交流施設ができますので、その中で常設でできるのかとか、そういうことも検討しています。その辺、その辺も課題の一つとして捉えてありますので、今後検討してまいりたいと考えております。","id":"exchange-016"},{"speaker":"新妻委員","kind":"質問・要望","question":"実績としては１６０店舗になっているわけですので、何か表現としてそういうところも冊子の中に反映できるのか、ぜひご検討ほしいと求めました。ここら辺との連動ですとか、そこともぜひ連動しながら取り組みを進めてほしいと求めましたが、いかがか尋ねました。","respondent":"提坂環境課長","answer":"確かに今、都の施設、例えば都営地下鉄の駅とかで設置しているというのは聞いてあります。その中で、品川区でどういう給水スポットがあるかということをもう少し分かりやすい形にできればということも検討してまいりたいと考えています。","id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"品川区のキャラクターにシナモロールがいますので、そういうところともコラボできるのかどうかということも含めて、ぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"つる委員","kind":"確認","question":"まず基本的なところの確認で、２３区だと思うのですけれども、ごみの袋というのは半透明か透明であれば出していいということですか。そもそも基本のところを説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"ごみ袋につきましては、透明もしくは半透明ということでお願いしています。職員が作業をする際に、ある程度一定の内容物が分かるという部分、危険性とか安全面を考慮してそのような形でお願いしています。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"これは今存在としてあるのかどうかとか、どこかで購入できるのか、手に入るところはあるのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"カラス対策としての黄色いごみ袋というのを以前お作りしたことがあります。実際、現時点でどういった形で販売しているかというのは、申し訳ございませんがちょっと不明です。","id":"exchange-020"},{"speaker":"つる委員","kind":"提案","question":"品川区についてもこれは公明党としても提案させていただいてエコバッグを作っていただいて、素材はオーガニックコットンを使っている。だから、２３区で品川区だけ切り取ってやるということもまた違うのかもしれないのですけれども、品川区で何かあれば教えてほしいと求めました。","respondent":"工藤品川区清掃事務所長","answer":"レジ袋の有料化というのが、コンビニエンスストア等のレジ袋が減ってまいりますので、実際の現場の中で確認はしてみたいと思ってあります。","id":"exchange-021"},{"speaker":"つる委員","kind":"提案","question":"オリジナルエコバッグはざっくり１万個くらいでしょうか。この場で改めて提案も含めてちょっと確認したいのですが、その確認と、説明を求めました。","respondent":"提坂環境課長","answer":"その中で提案等をさせていただいて、それに乗ってくれる団体があるのかどうか、そういうことでちょっと検討してまいりたいと考えています。","id":"exchange-022"},{"speaker":"つる委員","kind":"提案","question":"それからエシカルファッションショーについては、ぜひいろいろな提案も含めて、区のほうからもやってほしいと求めました。飲み口型水飲栓というのか尋ねました。","respondent":"提坂環境課長","answer":"東京都のその設備については、まだ今の時点では区から要望は出してございませんけれども、先ほどの企業からの提供と設置数といった点を踏まえた上で、必要に応じて要望を出していきたいとは考えてあります。","id":"exchange-023"},{"speaker":"つる委員","kind":"質問・要望","question":"エコバッグのような形で、そういうことでこの推進につながるのではないかと思いますので、そういうあたりも含めて今後検討ほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"松澤委員","kind":"質問","question":"食べ残し削減のＰＲ活動というのは、変な話で、多分置いてくれる飲食店とかは皆“もったいない”推進店になるのではないかと。品川区の商店街の飲食店、品川区としてそういう区商店街連合会にお願いをするとか、そういうことはもうやっていただけているのか尋ねました。","respondent":"提坂環境課長","answer":"今まで加盟していただいた１５２店舗の皆様についても今までやってきたのですけれども、地道な活動は今までもやってありますし、今後も続けてまいります。","id":"exchange-025"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひご協力をお願いできますかとか、そういう形にするともっともっと盛り上がりが見えるのではないかと思っていますので、そこら辺を要望します。そういう企業に対する食品ロスの考えというか、こうやって提示していきたいというお考えがもしありましたら。","respondent":"提坂環境課長","answer":"コンビニ各社におかれましても、食品ロスとか環境問題については真剣に取り組んでいるということを聞いてあります。近々、その中でいろいろな考え方を伺って、区としてどういう形で連携ができるかということを模索してまいりたいと考えています。","id":"exchange-026"},{"speaker":"渡部副委員長","kind":"質問","question":"よろしいでしょうか。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"ホームページのほうだったりとかｉＰｈｏｎｅだったりとか、そういう機能が今すごく進んでいるというのは私も伺っています。何かそういう趣旨があるのかなと、そうではなく、全体的にもつけていく方向ということでお願いしたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"渡部副委員長","kind":"質問","question":"よろしいですか 〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"渡部副委員長","kind":"意見","question":"去る９月２８日の委員会では、ビーチバレーボールの競技会場である都立潮風公園へ視察に出かけました。○午後 ２時４１分閉会との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/312568?Template=document&Id=6584#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":32206,"voices":63}},{"id":"r02-20201113-10","meetingId":"r02-cm11","date":"2020年11月13日","dateIso":"2020-11-13","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"議会報告会等準備会議および広報会議からの報告事項","agenda":"議会報告会等準備会議および広報会議からの報告事項","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"次に連絡用の氏名・住所・電話番号の記入を求めるものです。これは、万が一感染者が出た場合に濃厚接触者を確認する、こうしたものでこのように記入を参加者に求めていくものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"意見","question":"品川区公式ＬＩＮＥの登録者は約３,７００人ということで、興味のある方にスマートフォンなどですぐ目にしてもらえるようになります。広報会議からの報告は以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"本多委員","kind":"質問","question":"立会小学校の３年生、非常に全員が矢継ぎ早に質問をしてきて、積極的な子どもたちだなとすごく感じました。いろいろなことを尋ねられて、子どもたちもすごい一生のいい思い出になったと思いますし、受ける我々も刺激的でよかったなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"質問者も皆、まず端的にまとめて質問して、我々答えるほうが少し厳しいかなということがありました。できれば、先生方でもいいのですが、スナップ写真か何かでも撮ってあげればよかったのではないかなということは、少し感じたところであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"もっといったら、鋭い質問に我々もどう対応するかも含めて、とてもいい機会になったのではないかなと思っています。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"非常に積極的な質問が飛びまして、敬意と言うと言い過ぎですけれども、ありがたかったなと思います。戸越小学校については……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"後ですか。ぜひ続けて、向こうからの提案があれば、ぜひ続けていってほしいなという機会になりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"大倉委員","kind":"意見","question":"時間も３分とか、もう少し長くても、子どもが分かれば見てくれるかなと思いました。議長席に座ってもらうとか、ほかの人に話をしたりしてくれると思いますので、そういったような時間も取ってもいいのかなと思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問","question":"１つだけ。何かそこ、改善の余地があるのかななどと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"こんの委員","kind":"質問","question":"小学校３年生、積極的に質問をされていたなと。印象的だったのが、議会事務局長になるためにはどうしたらいいですかという質問がたしかあったかなと思うと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"高橋伸明委員がもうその前に２回やられていたので、今までどのような質問があったのですかということを聞き取っておいてよかったなと。なぜ被選挙権は２５歳以上でないと立候補できないのですかと、やはり少し考えてしまうのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"ただ、どうしても議場ですから、対峙するわけです。でも、非常に子どもたち、よく勉強していました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"若林副委員長","kind":"質問","question":"答えのないような質問もありましたので、代表的な質問は事前にいただいて、これからあってもいいかなと。感想を持たれたか、逆にまたフィードバックをいただけると、またこの次の機会に活かされるのかなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5382#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":11811,"voices":41}},{"id":"r02-20201125-10","meetingId":"r02-cm11","date":"2020年11月25日","dateIso":"2020-11-25","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5384#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":6083,"voices":23}}]);
